EXTERNAL_TARGET_TIMEOUT_MS = 300000  # legacy fixed cap (kept for non-adaptive callers)
# Adaptive response-wait: a fixed cap is fragile — long "Extra/Extra High" reasoning
# blows past any value, while a real hang (login wall, network drop, page error)
# wastes the whole cap. Instead, only give up when the page is NOT actively
# generating: keep waiting while busy or output is still growing; fail fast after
# EXTERNAL_TARGET_STALL_TIMEOUT_MS of no progress, with an absolute ceiling.
EXTERNAL_TARGET_STALL_TIMEOUT_MS = 90000   # no busy + no new output for this long -> give up
EXTERNAL_TARGET_ABSOLUTE_MAX_MS = 900000   # hard ceiling even while busy (15 min backstop)
EXTERNAL_TARGET_STABLE_HITS = 3
EXTERNAL_TARGET_POLL_INTERVAL_MS = 1100
