# Per-service hard input limits for web @targets, keyed by a substring matched
# against the target's service identity / alias / url. Copilot rejects messages
# over 10240 characters and then DISABLES its send button, so a prompt bloated by
# retrieved context never gets a send action ("did not enable a send action").
# When the prompt exceeds the limit, the retrieved context is trimmed while the
# final user request is kept verbatim. 0 / absent = no limit (most services).
EXTERNAL_TARGET_INPUT_CHAR_LIMITS = {
    'copilot': 10000,
}


def external_target_input_char_limit(text: str) -> int:
    """Hard input-character limit for a web target, looked up from the shared
    EXTERNAL_TARGET_INPUT_CHAR_LIMITS registry by substring against any identifying
    text (service identity / alias / url). Returns 0 when the service has no limit.
    Shared by the @target Q&A flow and the online-memory sync flow so per-service
    limits live in exactly one place."""
    blob = str(text or '').lower()
    if not blob:
        return 0
    for key, limit in EXTERNAL_TARGET_INPUT_CHAR_LIMITS.items():
        if key and key in blob:
            try:
                return int(limit)
            except (TypeError, ValueError):
                return 0
    return 0


def show_web_view_offscreen(view) -> None:
    """Map a QWebEngineView off-screen instead of hiding it. A hidden (unmapped)
    view makes Blink treat the page as not-visible and pause rAF/compositing, so
    streamed answers never commit to the DOM and synthetic mouse clicks (Grok /
    Perplexity send buttons) never hit-test. Keeping it mapped but parked far
    off-screen as a non-activating, always-on-bottom tool window renders normally
    while staying invisible to the user. Shared by @target and online-memory views."""
    try:
        # Re-apply the window flags whenever the view is not currently a top-level
        # window. This matters because _return_online_memory_view re-parents memory
        # views with setParent(), which DROPS these flags (incl. WA_ShowWithoutActivating
        # and "does not accept focus"); a plain boolean "already shown" guard then
        # skipped re-applying them, so the next send focused a now-activatable window
        # and macOS popped it to the foreground. @target views are never re-parented,
        # which is exactly why they kept their flags and never popped. isWindow() is
        # True once flags are set, so this is a cheap no-op on repeated calls (no
        # native-window recreation / flicker) for views that stayed windows.
        if not view.isWindow():
            view.setWindowFlags(
                Qt.WindowType.Tool
                | Qt.WindowType.FramelessWindowHint
                | Qt.WindowType.WindowStaysOnBottomHint
                | Qt.WindowType.WindowDoesNotAcceptFocus
            )
        view.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
        view.move(-32000, -32000)
        view.show()
        view.move(-32000, -32000)
        view.lower()
    except Exception:
        logging.exception('Failed to show web view off-screen')
        try:
            view.hide()
        except Exception:
            pass


def external_target_alias_slug(value: str, fallback: str = 'target') -> str:
    text = str(value or '').strip().lower()
    if '://' in text:
        parsed = urlparse(text)
        text = parsed.netloc or parsed.path or text
        text = text.split('@')[-1]
        text = text.split(':')[0] or text
    text = re.sub(r'^www\.', '', text)
    text = re.sub(r'[^a-z0-9]+', '-', text).strip('-')
    text = re.sub(r'-+', '-', text)
    fallback = re.sub(r'[^a-z0-9]+', '-', str(fallback or 'target').lower()).strip('-') or 'target'
    return (text or fallback)[:48].strip('-') or fallback


def external_web_service_identity(url: str = '', label: str = '') -> tuple[str, str]:
    """Return a stable provider identity and launch URL for known AI web apps."""
    raw_url = str(url or '').strip()
    raw_label = str(label or '').strip()
    host = ''
    try:
        parsed = urlparse(raw_url)
        host = (parsed.netloc or '').split('@')[-1].split(':')[0].lower()
    except Exception:
        host = ''
    if not host and raw_label:
        host = raw_label.lower()
    host = re.sub(r'^www\.', '', host).strip()
    if host.endswith('claude.ai'):
        return 'claude.ai', 'https://claude.ai/new'
    if host.endswith('chatgpt.com') or host.endswith('openai.com'):
        return 'chatgpt.com', 'https://chatgpt.com/'
    if host.endswith('gemini.google.com'):
        return 'gemini.google.com', 'https://gemini.google.com/app'
    if host.endswith('perplexity.ai'):
        return 'perplexity.ai', 'https://www.perplexity.ai/'
    if host.endswith('grok.com') or host.endswith('x.ai'):
        return 'grok.com', 'https://grok.com/'
    if host.endswith('copilot.microsoft.com') or host.endswith('copilot.com'):
        return 'copilot.microsoft.com', 'https://copilot.microsoft.com/'
    return '', raw_url


def normalize_external_sessions(value) -> dict:
    if not isinstance(value, dict):
        return {}
    sessions = {}
    for key, raw in value.items():
        key_text = str(key or '').strip()
        if not key_text or not isinstance(raw, dict):
            continue
        sessions[key_text] = {
            'target_key': str(raw.get('target_key', key_text) or key_text).strip(),
            'alias': str(raw.get('alias', '') or '').strip(),
            'kind': str(raw.get('kind', '') or '').strip(),
            'label': str(raw.get('label', '') or '').strip(),
            'url': str(raw.get('url', '') or '').strip(),
            'source_url': str(raw.get('source_url', '') or '').strip(),
            'launch_url': str(raw.get('launch_url', '') or '').strip(),
            'service_identity': str(raw.get('service_identity', '') or '').strip(),
            'session_url': str(raw.get('session_url', '') or '').strip(),
            'terminal_kind': str(raw.get('terminal_kind', '') or '').strip(),
            'resume_id': str(raw.get('resume_id', '') or '').strip(),
            'transcript_path': str(raw.get('transcript_path', '') or '').strip(),
            'session_locator_score': str(raw.get('session_locator_score', '') or '').strip(),
            'session_locator_reason': str(raw.get('session_locator_reason', '') or '').strip(),
            'session_locator_discovered_at': str(raw.get('session_locator_discovered_at', '') or '').strip(),
            'last_prompt_hash': str(raw.get('last_prompt_hash', '') or '').strip(),
            'created_at': str(raw.get('created_at', '') or '').strip(),
            'updated_at': str(raw.get('updated_at', '') or '').strip(),
        }
    return sessions


class SmoothPanelWidget(QWidget):
    """Root panel background drawn with continuous-curvature corners."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._smooth_panel_bg = QColor('#FFFFFF')
        self._smooth_panel_border = QColor('#ECECEC')
        self._smooth_panel_radius = 59.0
        self._smooth_panel_border_width = 1.0

    def set_smooth_panel_background(self, bg_color, border_color, radius=59, border_width=1.0):
        bg = QColor(bg_color)
        border = QColor(border_color)
        if bg.isValid():
            self._smooth_panel_bg = bg
        if border.isValid():
            self._smooth_panel_border = border
        self._smooth_panel_radius = float(radius)
        self._smooth_panel_border_width = float(border_width)
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        try:
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            bw = max(0.0, float(getattr(self, '_smooth_panel_border_width', 1.0)))
            inset = bw / 2.0
            rect = QRectF(self.rect()).adjusted(inset, inset, -inset, -inset)
            path = smooth_round_rect_path(rect, getattr(self, '_smooth_panel_radius', 59.0))
            painter.fillPath(path, getattr(self, '_smooth_panel_bg', QColor('#FFFFFF')))
            if bw > 0:
                pen = QPen(getattr(self, '_smooth_panel_border', QColor('#ECECEC')), bw)
                pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
                painter.strokePath(path, pen)
        finally:
            painter.end()


def style_broccoli_context_menu(menu: QMenu) -> QMenu:
    dark = is_dark_theme(app)
    bg = '#2D2D2D' if dark else '#FFFFFF'
    border = '#3A3A3A' if dark else '#E5E5EA'
    text = '#F2F2F7' if dark else '#20242B'
    hover = '#3A3A3A' if dark else '#F2F2F7'
    separator = '#3A3A3A' if dark else '#E5E5EA'
    menu.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
    menu.setStyleSheet(f"""
        QMenu {{
            background-color: {bg};
            color: {text};
            border: 1px solid {border};
            border-radius: 12px;
            padding: 6px;
            font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
            font-size: 13px;
        }}
        QMenu::item {{
            background: transparent;
            border-radius: 8px;
            padding: 7px 28px 7px 12px;
            min-width: 120px;
        }}
        QMenu::item:selected {{
            background: {hover};
        }}
        QMenu::item:disabled {{
            color: {'#8E8E93' if dark else '#A0A0A6'};
        }}
        QMenu::separator {{
            height: 1px;
            background: {separator};
            margin: 5px 8px;
        }}
        QMenu::right-arrow {{
            width: 8px;
            height: 8px;
            padding-right: 8px;
        }}
    """)
    return menu
