# Injected at document creation into the hidden @target web views. A hidden
# QWebEngineView reports document.hidden=true / visibilityState='hidden', which
# makes streaming chat UIs (ChatGPT) pause writing the answer into the DOM. Make
# the page always believe it is visible and focused so streaming completes.
EXTERNAL_VIEW_VISIBILITY_SPOOF_JS = r'''
(function(){
  try {
    var defineVisible = function(obj, prop, value){
      try { Object.defineProperty(obj, prop, { configurable: true, get: function(){ return value; } }); } catch (e) {}
    };
    defineVisible(document, 'hidden', false);
    defineVisible(document, 'webkitHidden', false);
    defineVisible(document, 'visibilityState', 'visible');
    defineVisible(document, 'webkitVisibilityState', 'visible');
    try { Object.defineProperty(document, 'hasFocus', { configurable: true, value: function(){ return true; } }); } catch (e) {}
    var swallow = function(e){ try { e.stopImmediatePropagation(); } catch (err) {} };
    document.addEventListener('visibilitychange', swallow, true);
    document.addEventListener('webkitvisibilitychange', swallow, true);
    window.addEventListener('blur', swallow, true);
    window.addEventListener('pagehide', swallow, true);
  } catch (e) {}
})();
'''
