if NSObject is not None and objc is not None:
    class ThemeObserver(NSObject):
        def initWithApp_(self, app_obj):
            self = objc.super(ThemeObserver, self).init()
            self.app = app_obj
            return self

        def themeChanged_(self, notification):
            apply_theme(self.app)
else:
    class ThemeObserver:
        pass


def install_theme_observer(app_obj):
    if NSDistributedNotificationCenter is None or NSSelectorFromString is None or NSObject is None or objc is None:
        return None
    try:
        observer = ThemeObserver.alloc().initWithApp_(app_obj)
        center = NSDistributedNotificationCenter.defaultCenter()
        center.addObserver_selector_name_object_(
            observer,
            NSSelectorFromString("themeChanged:"),
            "AppleInterfaceThemeChangedNotification",
            None
        )
        return observer
    except Exception:
        return None


class MacNormalButton(QPushButton):
    def __init__(self, text, parent=None, always_dark=False):
        super().__init__(text, parent)
        self.setAutoDefault(False)
        self.setFixedHeight(22)
        self._always_dark = bool(always_dark)
        self._alert = False
        self._updating_style = False
        self.update_theme()

    def update_theme(self):
        if self._updating_style:
            return
        self._updating_style = True
        try:
            if self._alert:
                bg = "#FF4D4D"
                bg_hover = "#FF6666"
                bg_pressed = "#CC3D3D"
                bg_disabled = "#E6E6E6"
                text = "#FFFFFF"
                text_disabled = "#777777"
            else:
                dark = self._always_dark or bool(getattr(self, '_force_dark', False)) or is_dark_theme(app)
                if dark:
                    bg = "#404145"
                    bg_hover = "#4A4B4F"
                    bg_pressed = "#343538"
                    bg_disabled = "#2F3033"
                    text = "#FFFFFF"
                    text_disabled = "#777777"
                else:
                    bg = "#E7E7E7"
                    bg_hover = "#EEEEEE"
                    bg_pressed = "#DCDCDC"
                    bg_disabled = "#E1E1E1"
                    text = "#111111"
                    text_disabled = "#777777"
            self.setStyleSheet(f"""
                QPushButton {{
                    border: 1px solid transparent;
                    background-color: {bg};
                    border-radius: 6px;
                    padding: 1px 8px;
                    color: {text};
                }}
                QPushButton:hover {{
                    background-color: {bg_hover};
                }}
                QPushButton:pressed {{
                    background-color: {bg_pressed};
                }}
                QPushButton:disabled {{
                    background-color: {bg_disabled};
                    color: {text_disabled};
                }}
            """)
        finally:
            self._updating_style = False

    def changeEvent(self, event):
        super().changeEvent(event)
        if self._updating_style:
            return
        if event.type() in (
            QEvent.Type.PaletteChange,
            QEvent.Type.ApplicationPaletteChange,
        ):
            self.update_theme()

    def set_alert(self, enabled):
        enabled = bool(enabled)
        if self._alert == enabled:
            return
        self._alert = enabled
        self.update_theme()


class WhiteButton(QPushButton):
    def __init__(self, text, parent=None):
        super().__init__(text, parent)
        self._theme_updating = False
        self.setAutoDefault(False)
        self.setFixedHeight(30)
        self.apply_default_style()
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(40)
        shadow.setXOffset(0)
        shadow.setYOffset(0)
        shadow.setColor(QColor(0, 0, 0, 40))
        self.setGraphicsEffect(shadow)

    def apply_default_style(self):
        if self._theme_updating:
            return
        self._theme_updating = True
        try:
            dark = bool(getattr(self, '_force_dark', False)) or is_dark_theme(app)
            if dark:
                self.setStyleSheet("""
                    QPushButton {
                        background-color: #3A3A3A;
                        color: #F2F2F7;
                        border: 1px solid #4A4B4F;
                        border-radius: 15px;
                        font-size: 13px;
                        padding: 5px 20px;
                    }
                    QPushButton:hover {
                        background-color: #454547;
                    }
                    QPushButton:pressed {
                        background-color: #323234;
                    }
                    QPushButton:disabled {
                        background-color: #2E2E30;
                        color: #8E8E93;
                        border: 1px solid #3A3A3D;
                    }
                """)
            else:
                self.setStyleSheet("""
                    QPushButton {
                        background-color: white;
                        color: #444;
                        border: none;
                        border-radius: 15px;
                        font-size: 13px;
                        padding: 5px 20px;
                    }
                    QPushButton:hover {
                        background-color: #f5f5f5;
                    }
                    QPushButton:pressed {
                        background-color: #ececec;
                    }
                    QPushButton:disabled {
                        background-color: #f2f2f2;
                        color: #9a9a9a;
                    }
                """)
        finally:
            self._theme_updating = False

    def changeEvent(self, event):
        super().changeEvent(event)
        if self._theme_updating:
            return
        if event.type() in (
            QEvent.Type.PaletteChange,
            QEvent.Type.ApplicationPaletteChange,
        ):
            self.apply_default_style()


class BroccoliMessageDialog(QDialog):
    def __init__(self,
                 title: str,
                 message: str,
                 button_text: str = 'OK',
                 parent=None,
                 buttons: list[str] | None = None,
                 default_button_text: str | None = None,
                 size: QSize | None = None,
                 force_dark: bool = False):
        super().__init__(parent)
        self._theme_updating = False
        self._force_dark = bool(force_dark)
        self._panel_margin = 16
        self._panel_radius = 45
        self.selected_button = ''
        self.setModal(True)
        self.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        dialog_size = size if isinstance(size, QSize) else QSize(420, 178)
        self.setFixedSize(dialog_size)

        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(34, 30, 34, 30)
        root_layout.setSpacing(10)

        self.title_lbl = QLabel(str(title or ''), self)
        self.message_lbl = QLabel(str(message or ''), self)
        self.message_lbl.setWordWrap(True)
        self.message_lbl.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)

        root_layout.addWidget(self.title_lbl)
        root_layout.addWidget(self.message_lbl, 1)

        button_row = QHBoxLayout()
        button_row.setContentsMargins(0, 8, 0, 0)
        button_row.setSpacing(6)
        button_row.addStretch()
        labels = [str(item) for item in (buttons or [button_text]) if str(item).strip()]
        if not labels:
            labels = ['OK']
        self._dialog_buttons = []
        default_label = str(default_button_text or labels[0])
        for label in labels:
            button = MacNormalButton(label, self, always_dark=self._force_dark)
            button.setFixedWidth(max(84, button.sizeHint().width()))
            button.clicked.connect(lambda _checked=False, chosen=label: self._choose_button(chosen))
            if label == default_label:
                self.setFocusProxy(button)
                button.setFocus()
            self._dialog_buttons.append(button)
            button_row.addWidget(button)
        root_layout.addLayout(button_row)

        self._apply_theme()

    def _choose_button(self, label: str):
        self.selected_button = str(label or '')
        self.accept()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dark = self._force_dark or is_dark_theme(app)
        panel_rect = QRectF(
            self._panel_margin,
            self._panel_margin,
            self.width() - self._panel_margin * 2,
            self.height() - self._panel_margin * 2,
        )
        bg_path = smooth_round_rect_path(panel_rect, self._panel_radius)
        painter.fillPath(bg_path, QColor('#2D2D2D' if dark else '#FFFFFF'))
        painter.setPen(QPen(QColor('#3A3A3A' if dark else '#ECECEC'), 1))
        painter.drawPath(bg_path)
        painter.end()

    def _apply_theme(self):
        if self._theme_updating:
            return
        self._theme_updating = True
        dark = self._force_dark or is_dark_theme(app)
        try:
            self.title_lbl.setStyleSheet(
                f'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; '
                f'font-size: 14px; font-weight: 600; color: {"#F2F2F7" if dark else "#20242B"};'
            )
            self.message_lbl.setStyleSheet(
                f'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; '
                f'font-size: 13px; color: {"#C6CBD4" if dark else "#4A4F58"};'
            )
            for button in getattr(self, '_dialog_buttons', []):
                button.update_theme()
            self.update()
        finally:
            self._theme_updating = False

    def changeEvent(self, event):
        super().changeEvent(event)
        if self._theme_updating:
            return
        if event.type() in (QEvent.Type.PaletteChange, QEvent.Type.ApplicationPaletteChange):
            self._apply_theme()


def _center_broccoli_dialog(dialog: QDialog, parent=None):
    dialog.adjustSize()
    parent_widget = parent if isinstance(parent, QWidget) else QApplication.activeWindow()
    parent_geometry = parent_widget.frameGeometry() if parent_widget is not None else QApplication.primaryScreen().availableGeometry()
    dialog_geometry = dialog.frameGeometry()
    dialog_geometry.moveCenter(parent_geometry.center())
    dialog.move(dialog_geometry.topLeft())


def show_broccoli_message(parent, title: str, message: str, button_text: str = 'OK', force_dark: bool = False):
    dialog = BroccoliMessageDialog(title, message, button_text, parent, force_dark=force_dark)
    _center_broccoli_dialog(dialog, parent)
    dialog.exec()
    return dialog.selected_button or button_text


def ask_broccoli_message(parent,
                         title: str,
                         message: str,
                         buttons: list[str],
                         default_button_text: str | None = None,
                         size: QSize | None = None,
                         force_dark: bool = False) -> str:
    dialog = BroccoliMessageDialog(
        title,
        message,
        parent=parent,
        buttons=buttons,
        default_button_text=default_button_text,
        size=size,
        force_dark=force_dark,
    )
    _center_broccoli_dialog(dialog, parent)
    dialog.exec()
    return dialog.selected_button or (default_button_text or (buttons[0] if buttons else ''))


class AgentTerminalCommandApprovalDialog(QDialog):
    def __init__(self, request: dict, parent=None):
        super().__init__(parent)
        self.request = dict(request or {})
        self.selected_decision = 'deny'
        self._theme_updating = False
        self._panel_margin = 16
        self._panel_radius = 45
        self._read_only = bool(self.request.get('read_only', False))
        self._default_decision = 'allow' if self._read_only else 'deny'
        self._remaining = (
            AGENT_TERMINAL_READ_DEFAULT_ALLOW_SECONDS
            if self._read_only
            else AGENT_TERMINAL_WRITE_DEFAULT_DENY_SECONDS
        )
        self.setModal(True)
        self.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        base_width = 640
        base_height = 500
        if parent is not None:
            try:
                host = getattr(parent, 'qw3', None) or parent
                parent_width = int(host.width())
                parent_height = int(host.height())
                if parent_width > 0:
                    base_width = max(420, min(640, parent_width - 32))
                if parent_height > 0:
                    base_height = max(360, min(500, parent_height - 48))
            except Exception:
                pass
        self.setFixedSize(QSize(base_width, base_height))

        self.title_lbl = QLabel('Terminal Command Request', self)
        self.message_edit = QPlainTextEdit(self)
        self.message_edit.setReadOnly(True)
        self.message_edit.setPlainText(self._build_message())
        self.deny_button = MacNormalButton('Deny', self)
        self.allow_button = MacNormalButton('Allow', self)
        for button in (self.deny_button, self.allow_button):
            button.setCursor(Qt.CursorShape.PointingHandCursor)
            button.setFixedWidth(140)
        self.deny_button.clicked.connect(lambda: self._choose('deny'))
        self.allow_button.clicked.connect(lambda: self._choose('allow'))

        button_row = QHBoxLayout()
        button_row.setContentsMargins(0, 8, 0, 0)
        button_row.setSpacing(10)
        button_row.addStretch()
        button_row.addWidget(self.deny_button)
        button_row.addWidget(self.allow_button)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(36, 34, 36, 34)
        layout.setSpacing(10)
        layout.addWidget(self.title_lbl)
        layout.addWidget(self.message_edit, 1)
        layout.addLayout(button_row)

        self._timer = QTimer(self)
        self._timer.setInterval(1000)
        self._timer.timeout.connect(self._tick)
        self._apply_theme()
        self._refresh_countdown_buttons()
        self._timer.start()

    def _build_message(self) -> str:
        req = self.request
        parts = [
            'The Agent wants to run a local terminal command.',
            '',
            'Command:',
            str(req.get('command', '') or '').strip(),
            '',
            'Purpose:',
            str(req.get('purpose', '') or '').strip() or '(not provided)',
            '',
            'Expected result:',
            str(req.get('expected_result', '') or '').strip() or '(not provided)',
            '',
            f"Risk: {str(req.get('risk', '') or 'unknown')}",
        ]
        reasons = [str(item) for item in (req.get('risk_reasons') or []) if str(item).strip()]
        if reasons:
            parts.extend(['Risk reasons:', *[f'- {reason}' for reason in reasons]])
        targets = [str(item) for item in (req.get('target_paths') or []) if str(item).strip()]
        if targets:
            parts.extend(['', 'Target paths:', *[f'- {path}' for path in targets]])
        backup_manifest = str(req.get('backup_manifest_path', '') or '').strip()
        backup_dir = str(req.get('backup_dir', '') or '').strip()
        if backup_manifest or backup_dir:
            parts.extend(['', 'Backup:', backup_manifest or backup_dir])
        elif not bool(req.get('read_only', False)):
            parts.extend(['', 'Backup:', 'No explicit backup was created. This command should be allowed only if that is acceptable.'])
        parts.extend([
            '',
            'Possible results:',
            '- The command output will be shown in Terminal and returned to the Agent.',
            '- Read-only commands can expose local/private data to the Agent conversation.',
            '- Mutating commands can create, edit, delete, install, or change files/app state.',
        ])
        if self._read_only:
            parts.extend(['', 'Default: Allow after 10 minutes unless you deny it.'])
        else:
            parts.extend(['', 'Default: Deny after 30 minutes unless you allow it.'])
        return '\n'.join(parts)

    def _choose(self, decision: str):
        self.selected_decision = 'allow' if str(decision or '') == 'allow' else 'deny'
        self.accept()

    def _tick(self):
        self._remaining -= 1
        if self._remaining <= 0:
            self._choose(self._default_decision)
            return
        self._refresh_countdown_buttons()

    def _refresh_countdown_buttons(self):
        mins, secs = divmod(max(0, int(self._remaining)), 60)
        label = f'{mins:02d}:{secs:02d}'
        if self._default_decision == 'allow':
            self.allow_button.setText(f'Allow ({label})')
            self.deny_button.setText('Deny')
        else:
            self.deny_button.setText(f'Deny ({label})')
            self.allow_button.setText('Allow')

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dark = is_dark_theme(app)
        panel_rect = QRectF(
            self._panel_margin,
            self._panel_margin,
            self.width() - self._panel_margin * 2,
            self.height() - self._panel_margin * 2,
        )
        bg_path = smooth_round_rect_path(panel_rect, self._panel_radius)
        painter.fillPath(bg_path, QColor('#2D2D2D' if dark else '#FFFFFF'))
        painter.setPen(QPen(QColor('#3A3A3A' if dark else '#ECECEC'), 1))
        painter.drawPath(bg_path)
        painter.end()

    def _apply_theme(self):
        if self._theme_updating:
            return
        self._theme_updating = True
        dark = is_dark_theme(app)
        fg = '#F2F2F7' if dark else '#20242B'
        input_bg = '#343436' if dark else '#F7F8FA'
        border = '#4A4B4F' if dark else '#DDE2EA'
        try:
            self.setStyleSheet(
                'QDialog { background: transparent; }'
                f'QPlainTextEdit {{ background: {input_bg}; color: {fg}; '
                f'border: 1px solid {border}; border-radius: 8px; padding: 8px; '
                'font-family: Menlo, Monaco, monospace; font-size: 12px; }}'
            )
            self.title_lbl.setStyleSheet(
                f'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; '
                f'font-size: 16px; font-weight: 700; color: {fg};'
            )
            for button in (self.deny_button, self.allow_button):
                button.update_theme()
            self.update()
        finally:
            self._theme_updating = False


class MacWindowButton(QPushButton):
    def __init__(self, color, symbol, parent=None):
        super().__init__(parent)
        self.setFixedSize(16, 16)
        self.base_color = QColor(color)
        self.symbol = symbol
        self.hovered = False
        self.setStyleSheet('border: none; background: transparent;')

    def enterEvent(self, event):
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self.hovered = False
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        painter.setBrush(self.base_color)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.drawEllipse(0, 0, self.width(), self.height())
        if self.hovered:
            pen = QPen(QColor('black'))
            pen.setWidth(2)
            painter.setPen(pen)
            margin = 5
            if self.symbol == 'x':
                painter.drawLine(margin, margin, self.width() - margin, self.height() - margin)
                painter.drawLine(self.width() - margin, margin, margin, self.height() - margin)
            elif self.symbol == '-':
                painter.drawLine(margin, self.height() // 2, self.width() - margin, self.height() // 2)
            elif self.symbol == '+':
                painter.drawLine(self.width() // 2, margin, self.width() // 2, self.height() - margin)
                painter.drawLine(margin, self.height() // 2, self.width() - margin, self.height() // 2)


class WebFetchWatchEventBridge(QObject):
    file_detected = pyqtSignal(str)


class _WebFetchWatchdogHandler(FileSystemEventHandler):
    def __init__(self, bridge):
        super().__init__()
        self._bridge = bridge

    def _emit_if_candidate(self, path: str):
        if not path:
            return
        name = os.path.basename(path)
        if is_matching_webfetch_filename(name):
            self._bridge.file_detected.emit(path)

    def on_created(self, event):
        if not getattr(event, 'is_directory', False):
            self._emit_if_candidate(getattr(event, 'src_path', ''))

    def on_moved(self, event):
        if not getattr(event, 'is_directory', False):
            self._emit_if_candidate(getattr(event, 'dest_path', '') or getattr(event, 'src_path', ''))


class WebFetchWatchManager(QObject):
    file_imported = pyqtSignal(dict)
    status_changed = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._observer = None
        self._watch_dir = ''
        self._bridge = WebFetchWatchEventBridge()
        self._bridge.file_detected.connect(self._on_file_detected)

    @property
    def available(self) -> bool:
        return WATCHDOG_AVAILABLE

    @property
    def watch_dir(self) -> str:
        return self._watch_dir

    def stop(self):
        observer = self._observer
        self._observer = None
        self._watch_dir = ''
        if observer is not None:
            try:
                observer.stop()
                observer.join(timeout=2)
            except Exception:
                pass

    def start(self, folder: str):
        folder = str(folder or '').strip()
        if not self.available:
            self.status_changed.emit('watchdog is unavailable.')
            self.stop()
            return
        if not folder or not os.path.isdir(folder):
            self.stop()
            self.status_changed.emit('WebFetch download folder is not set.')
            return
        if self._observer is not None and self._watch_dir == folder:
            return
        self.stop()
        observer = Observer()
        handler = _WebFetchWatchdogHandler(self._bridge)
        observer.schedule(handler, folder, recursive=False)
        observer.daemon = True
        observer.start()
        self._observer = observer
        self._watch_dir = folder
        self.status_changed.emit(f'Watching {folder}')

    def _on_file_detected(self, path: str):
        QTimer.singleShot(400, lambda p=path: self._process_candidate(p, 0))

    def _process_candidate(self, path: str, attempt: int):
        if not path or not os.path.exists(path):
            return
        record = import_webfetch_file_to_inbox(path)
        if record is not None:
            self.file_imported.emit(record)
            return
        if attempt < 8:
            QTimer.singleShot(300, lambda p=path, a=attempt + 1: self._process_candidate(p, a))


