def specialized_auto_context_tokens(text: str, limit: int = 40) -> list[str]:
    raw = str(text or '').lower()
    tokens = []
    seen = set()

    def add(token: str):
        token = str(token or '').strip().lower()
        if not token or token in seen or token in SPECIALIZED_AUTO_CONTEXT_STOPWORDS:
            return
        if len(token) < 2:
            return
        seen.add(token)
        tokens.append(token)

    for token in re.findall(r'[a-z][a-z0-9_./:-]{2,}|[0-9][a-z0-9_./:-]{1,}', raw):
        add(token)
        if len(tokens) >= limit:
            return tokens

    try:
        cjk_terms = jieba.lcut(str(text or ''))
    except Exception:
        cjk_terms = re.findall(r'[\u4e00-\u9fff]{2,}', str(text or ''))
    for token in cjk_terms:
        token = str(token or '').strip()
        if len(token) < 2:
            continue
        if re.fullmatch(r'[\W_]+', token):
            continue
        add(token)
        if len(tokens) >= limit:
            break
    return tokens


def specialized_auto_context_coverage(query_text: str, available_context: str) -> tuple[float, list[str]]:
    tokens = specialized_auto_context_tokens(query_text)
    if not tokens:
        return 1.0, []
    haystack = str(available_context or '').lower()
    missing = [token for token in tokens if token.lower() not in haystack]
    coverage = (len(tokens) - len(missing)) / max(1, len(tokens))
    return coverage, missing


def specialized_auto_query_has_hint(query_text: str, hints: set[str]) -> bool:
    lowered = str(query_text or '').lower()
    return any(hint in lowered for hint in hints)


def normalize_planner_plan(plan: dict | None, available_skill_names: set[str] | None = None) -> dict:
    normalized = {
        'steps': [],
        'finalize_with_default_chat': False,
        'finalize_focus': '',
        'reason': '',
    }
    if not isinstance(plan, dict):
        return normalized
    allowed = {key for key, _label in SPECIALIZED_CAPABILITIES} | {BROWSER_USE_CAPABILITY, SPECIALIZED_SKILL_CAPABILITY}
    normalized_skill_names = None
    if available_skill_names is not None:
        normalized_skill_names = {str(name or '').strip().lower() for name in available_skill_names if str(name or '').strip()}
    raw_steps = plan.get('steps', [])
    if isinstance(raw_steps, list):
        for step in raw_steps:
            if not isinstance(step, dict):
                continue
            capability = str(step.get('capability', '')).strip()
            if capability not in allowed:
                continue
            skill_name = ''
            if capability == SPECIALIZED_SKILL_CAPABILITY:
                skill_name = sanitize_skill_name(step.get('skill_name', ''), '')
                if not skill_name:
                    continue
                if normalized_skill_names is not None and skill_name.lower() not in normalized_skill_names:
                    continue
            goal = str(step.get('goal', '')).strip()
            if not goal:
                continue
            normalized_step = {
                'capability': capability,
                'goal': goal,
                'depends_on_previous': bool(step.get('depends_on_previous', False)),
                'extract': str(step.get('extract', '')).strip(),
                'context_policy': normalize_specialized_step_context_policy(step.get('context_policy', 'auto')),
                'context_query': str(step.get('context_query', '') or '').strip(),
            }
            if skill_name:
                normalized_step['skill_name'] = skill_name
            normalized['steps'].append(normalized_step)
    normalized['finalize_with_default_chat'] = bool(plan.get('finalize_with_default_chat', False))
    normalized['finalize_focus'] = str(plan.get('finalize_focus', '')).strip()
    normalized['reason'] = str(plan.get('reason', '')).strip()
    return normalized


def normalize_dynamic_specialized_step(step: dict | None, available_skill_names: set[str] | None = None) -> dict | None:
    if not isinstance(step, dict):
        return None
    allowed = {key for key, _label in SPECIALIZED_CAPABILITIES} | {BROWSER_USE_CAPABILITY, SPECIALIZED_SKILL_CAPABILITY}
    normalized_skill_names = None
    if available_skill_names is not None:
        normalized_skill_names = {str(name or '').strip().lower() for name in available_skill_names if str(name or '').strip()}
    capability = str(step.get('capability', '') or '').strip()
    goal = str(step.get('goal', '') or '').strip()
    if capability not in allowed or not goal:
        return None
    normalized = {
        'capability': capability,
        'goal': goal,
        'depends_on_previous': bool(step.get('depends_on_previous', False)),
        'extract': str(step.get('extract', '') or '').strip(),
        'context_policy': normalize_specialized_step_context_policy(step.get('context_policy', 'auto')),
        'context_query': str(step.get('context_query', '') or '').strip(),
        'dynamic': True,
    }
    for key in ('retry_reason', 'delta_goal', 'source_strategy', 'success_criteria'):
        value = str(step.get(key, '') or '').strip()
        if value:
            normalized[key] = value
    if capability == SPECIALIZED_SKILL_CAPABILITY:
        skill_name = sanitize_skill_name(step.get('skill_name', ''), '')
        if not skill_name:
            return None
        if normalized_skill_names is not None and skill_name.lower() not in normalized_skill_names:
            return None
        normalized['skill_name'] = skill_name
    return normalized


# Auto-link bare URLs so every URL in the agent display is clickable. markdown2's
# link-patterns extra runs after code blocks/spans and existing links are protected,
# so it never linkifies inside code or double-links. http(s) keeps its href; a bare
# www. host gets an http:// href. Trailing sentence/CJK punctuation is excluded.
BROCCOLI_LINK_PATTERNS = [
    (re.compile(r'(?i)\bhttps?://[^\s<>()\[\]{}"\'`，。；！？、（）【】「」]+[^\s<>()\[\]{}"\'`，。；！？、（）【】「」.,;:!?]'),
     r'\g<0>'),
    (re.compile(r'(?i)\bwww\.[^\s<>()\[\]{}"\'`，。；！？、（）【】「」]+[^\s<>()\[\]{}"\'`，。；！？、（）【】「」.,;:!?]'),
     r'http://\g<0>'),
]

_BARE_URL_RE = re.compile(r'(?i)\b(?:https?://|www\.)[^\s<>()\[\]{}"\'`，。；！？、（）【】「」]+[^\s<>()\[\]{}"\'`，。；！？、（）【】「」.,;:!?]')


def linkify_plain_text_to_html(text: str) -> str:
    """HTML-escape plain text (e.g. user messages, which are NOT run through
    markdown) while turning bare URLs into clickable links. URLs are matched on the
    raw text; non-URL spans and the visible label are escaped, so it is injection
    safe and otherwise identical to html.escape()."""
    text = str(text or '')
    out = []
    last = 0
    for m in _BARE_URL_RE.finditer(text):
        out.append(html.escape(text[last:m.start()]))
        url = m.group(0)
        href = url if url[:4].lower() == 'http' else 'http://' + url
        out.append(f'<a href="{html.escape(href, quote=True)}" rel="nofollow">{html.escape(url)}</a>')
        last = m.end()
    out.append(html.escape(text[last:]))
    return ''.join(out)


_HTML_TAG_RE = re.compile(r'<[^>]+>')


def linkify_bare_urls_in_html(html_str: str) -> str:
    """Wrap bare URLs in an ALREADY-rendered HTML string with <a>, without touching
    existing links or code. Used to retroactively linkify stored pipeline-step HTML
    (message['display_prefix_html']) that was rendered before bare-URL auto-linking
    existed. Skips text inside <a>/<code>/<pre> and never rewrites tag internals."""
    s = str(html_str or '')
    if 'http://' not in s and 'https://' not in s and 'www.' not in s:
        return s

    def link_seg(seg: str) -> str:
        def repl(m):
            url = m.group(0)
            href = url if url[:4].lower() == 'http' else 'http://' + url
            return f'<a href="{href}" rel="nofollow">{url}</a>'
        return _BARE_URL_RE.sub(repl, seg)

    out = []
    pos = 0
    skip = 0
    for m in _HTML_TAG_RE.finditer(s):
        seg = s[pos:m.start()]
        if seg:
            out.append(seg if skip > 0 else link_seg(seg))
        tag = m.group(0)
        out.append(tag)
        low = tag.lower()
        if re.match(r'<\s*(a|code|pre)\b', low) and not low.rstrip().endswith('/>'):
            skip += 1
        elif re.match(r'<\s*/\s*(a|code|pre)\b', low) and skip > 0:
            skip -= 1
        pos = m.end()
    tail = s[pos:]
    if tail:
        out.append(tail if skip > 0 else link_seg(tail))
    return ''.join(out)


def render_markdown_fragment(mdstr: str) -> str:
    text = str(mdstr or '').strip()
    if not text:
        return ''
    extras = [
        'code-friendly',
        'fenced-code-blocks',
        'footnotes',
        'tables',
        'code-color',
        'pyshell',
        'nofollow',
        'cuddled-lists',
        'header-ids',
        'link-patterns',
    ]
    clean_one = text.replace('\\(', '$').replace('\\)', '$').replace('\\[', '$').replace('\\]', '$')
    clean_two = re.sub(
        r'\$(.*?)\$',
        lambda m: '$' + re.sub(r'[\n\t ]+', '', m.group(1)) + '$',
        clean_one,
        flags=re.DOTALL,
    )
    clean_three = re.sub(r'\|(\n(\t)*\n(\t)*)\|', '|\n|', clean_two)
    return markdown2.markdown(clean_three, extras=extras, link_patterns=BROCCOLI_LINK_PATTERNS)


def render_markdown_document_to_html(mdstr: str, dark: bool, display_prefix_html: str = '', display_prefix_map: dict[str, str] | None = None) -> str:
    qa_q_bg = '#2E5C91' if dark else '#D9EAF8'
