def render_chat_display_document_css(dark: bool) -> str:
    html_doc = render_markdown_document_to_html('', dark)
    return '\n'.join(re.findall(r'<style>\s*(.*?)\s*</style>', html_doc, re.DOTALL))


def build_pipeline_display_prefix(plan: dict, step_results: list[dict]) -> str:
    if not step_results:
        return ''

    sections = []
    if plan.get('steps'):
        route_text = ' → '.join(skill_step_label(step) for step in plan['steps'])
        sections.append(
            '<div class="pipeline-step">'
            '<div><strong>Planner</strong></div>'
            f'<div>{render_markdown_fragment("Planned steps: " + route_text)}</div>'
            '</div>'
        )
    for result in step_results:
        label = str(result.get('capability_label', result.get('capability', 'Step'))).strip()
        model_name = str(result.get('model_name', '')).strip()
        title = label + (f' · {model_name}' if model_name else '')
        goal = str((result.get('metadata') or {}).get('goal', '') or '').strip()
        body = str(result.get('text_output', '')).strip()
        if goal:
            body = f'Goal: {goal}\n\n' + body
        code_executions = (result.get('metadata') or {}).get('code_executions') or (result.get('metadata') or {}).get('python_executions') or []
        if code_executions:
            execution_lines = []
            for exec_index, execution in enumerate(code_executions, start=1):
                exec_result = execution.get('result') or {}
                language = normalize_code_runner_language(execution.get('language', '') or exec_result.get('language', ''), 'text')
                stdout = str(exec_result.get('stdout', '') or '').strip()
                stderr = str(exec_result.get('stderr', '') or '').strip()
                line = f'Execution {exec_index} ({language}): return code {exec_result.get("returncode")}'
                if exec_result.get('skipped', False):
                    line += ' · skipped'
                if stdout:
                    line += f'\nstdout: {stdout}'
                if stderr:
                    line += f'\nstderr: {stderr}'
                execution_lines.append(line)
            body = body + ('\n\n' if body else '') + 'Code execution results:\n' + '\n\n'.join(execution_lines)
        artifact_paths = [str(path).strip() for path in (result.get('artifacts') or []) if str(path).strip()]
        if artifact_paths:
            artifact_block = 'Artifacts:\n' + '\n'.join(f'- {path}' for path in artifact_paths)
            body = body + ('\n\n' if body else '') + artifact_block
        sections.append(
            '<div class="pipeline-step">'
            f'<div><strong>{html.escape(title)}</strong></div>'
            f'<div class="pipeline-step-body">{render_markdown_fragment(body)}</div>'
            '</div>'
        )
    return (
        '<details class="pipeline-details">'
        '<summary>Specialized steps</summary>'
        + ''.join(section for section in sections if section)
        + '</details>'
    )


def specialized_step_context_output(result: dict) -> str:
    if not isinstance(result, dict):
        return ''
    if 'context_output' in result:
        return str(result.get('context_output', '') or '').strip()
    return str(result.get('text_output', '') or '').strip()


def specialized_result_reviewed_output(result: dict) -> str:
    if not isinstance(result, dict):
        return ''
    return str(result.get('context_output', '') or '').strip()


def limit_specialized_context_output(text: str, limit: int = SPECIALIZED_STEP_CONTEXT_MAX_CHARS) -> str:
    content = str(text or '').strip()
    if len(content) <= limit:
        return content
    return content[:limit].rstrip() + '\n\n[Context output truncated.]'


def limit_specialized_final_reviewed_facts(text: str) -> str:
    content = str(text or '').strip()
    if len(content) <= SPECIALIZED_FINAL_REVIEWED_FACTS_CHARS:
        return content
    return content[:SPECIALIZED_FINAL_REVIEWED_FACTS_CHARS].rstrip() + '\n\n[Reviewed facts truncated.]'


def specialized_high_signal_lines(text: str, limit: int = 2400) -> str:
    content = str(text or '')
    if not content.strip() or limit <= 0:
        return ''
    patterns = [
        r'https?://',
        r'\b20\d{2}[-/年]\d{1,2}',
        r'\b\d{1,2}\s*[月/.-]\s*\d{1,2}',
        r'\b\d{1,2}:\d{2}\b',
        r'\b\d+\s*[–-]\s*\d+\b',
        r'\b(FT|AET|PEN|Scheduled|Fixture|Live|Final|Group|Round|Score|Sources?)\b',
        r'(比分|结果|完赛|未开赛|待赛|小组|决赛|半决赛|赛程|来源|官方|球场|城市|状态|北京时间|当地时间)',
    ]
    combined = re.compile('|'.join(f'(?:{pattern})' for pattern in patterns), re.IGNORECASE)
    selected = []
    seen = set()
    total = 0
    for raw_line in content.splitlines():
        line = raw_line.strip()
        if not line or line in seen or not combined.search(line):
            continue
        if total + len(line) + 1 > limit:
            break
        seen.add(line)
        selected.append(line)
        total += len(line) + 1
    return '\n'.join(selected).strip()


def limit_specialized_raw_evidence_for_final(text: str) -> tuple[str, str]:
    content = str(text or '').strip()
    if not content:
        return '', 'empty'
    if len(content) <= SPECIALIZED_FINAL_RAW_DIRECT_CHARS:
        return content, 'full'
    limit = SPECIALIZED_FINAL_RAW_EXCERPT_CHARS
    if len(content) <= limit:
        return content, 'full-medium'
    head_budget = max(1600, int(limit * 0.45))
    signal_budget = max(1200, int(limit * 0.25))
    tail_budget = max(1200, limit - head_budget - signal_budget - 300)
    head = content[:head_budget].rstrip()
    signal = specialized_high_signal_lines(content, signal_budget)
    tail = content[-tail_budget:].lstrip()
    parts = [
        '[Raw evidence excerpt: beginning]',
        head,
    ]
    if signal:
        parts.extend([
            '[Raw evidence excerpt: high-signal lines with dates/scores/status/sources]',
            signal,
        ])
    parts.extend([
        '[Raw evidence excerpt: ending]',
        tail,
        '[Raw evidence truncated for final prompt budget.]',
    ])
    return '\n\n'.join(part for part in parts if str(part or '').strip()), 'excerpt'


def specialized_result_sources_text(result: dict) -> str:
    if not isinstance(result, dict):
        return ''
    metadata = result.get('metadata') if isinstance(result.get('metadata'), dict) else {}
    sources = metadata.get('sources') or []
    lines = []
    for source in sources:
        if isinstance(source, dict):
            url = str(source.get('url', '') or '').strip()
            title = str(source.get('title', '') or '').strip()
            if url:
                lines.append(f'- {title + " " if title else ""}{url}')
        else:
            text = str(source or '').strip()
            if text:
                lines.append(f'- {text}')
    if lines:
        return '\n'.join(lines)
    raw = str(result.get('text_output', '') or '')
    urls = []
    for url in re.findall(r'https?://[^\s\]\)>"\']+', raw):
        cleaned = url.rstrip('.,;')
        if cleaned not in urls:
            urls.append(cleaned)
        if len(urls) >= 20:
            break
    return '\n'.join(f'- {url}' for url in urls)


def specialized_step_review_summary(result: dict) -> str:
    if not isinstance(result, dict):
        return ''
    metadata = result.get('metadata') if isinstance(result.get('metadata'), dict) else {}
    review = metadata.get('step_review') if isinstance(metadata.get('step_review'), dict) else {}
    if not review:
        return ''
    lines = [
        f"meets_goal: {'yes' if review.get('meets_goal', False) else 'no'}",
        f"next_action: {str(review.get('next_action', '') or '').strip() or 'accept'}",
    ]
    for key in ('missing', 'reason', 'retry_reason', 'delta_goal', 'source_strategy', 'success_criteria'):
        value = str(review.get(key, '') or '').strip()
        if value:
            lines.append(f'{key}: {value}')
    return '\n'.join(lines)


def specialized_progress_snippet(text: str, limit: int = SPECIALIZED_PROGRESS_SNIPPET_CHARS) -> str:
    content = re.sub(r'\s+', ' ', str(text or '')).strip()
    if len(content) <= limit:
        return content
    return content[:limit].rstrip() + '...'


def build_finalize_prompt(question_text: str,
                          shared_context: str,
                          step_results: list[dict]) -> str:
    step_sections = []
    total_step_chars = 0
    for result in step_results:
        capability = str(result.get('capability', '')).strip()
        model_name = str(result.get('model_name', '')).strip()
        metadata = result.get('metadata') if isinstance(result.get('metadata'), dict) else {}
        goal = str(metadata.get('goal', '') or '').strip()
        raw_text = str(result.get('text_output', '') or '').strip()
        raw_evidence, raw_mode = limit_specialized_raw_evidence_for_final(raw_text)
        reviewed_facts = limit_specialized_final_reviewed_facts(specialized_result_reviewed_output(result))
        review_summary = specialized_step_review_summary(result)
        sources_text = specialized_result_sources_text(result)
        artifact_paths = [str(path).strip() for path in (result.get('artifacts') or []) if str(path).strip()]
        if not raw_evidence and not reviewed_facts and not artifact_paths:
            continue
        skill_name = str((result.get('metadata') or {}).get('skill_name', '') or '').strip()
        header_capability = f'{capability}:{skill_name}' if capability == SPECIALIZED_SKILL_CAPABILITY and skill_name else capability
        header = header_capability + (f' ({model_name})' if model_name else '')
        step_parts = []
        if goal:
            step_parts.append('Goal:\n' + goal)
        if raw_evidence:
            step_parts.append(f'Raw evidence ({raw_mode}):\n' + raw_evidence)
        if reviewed_facts:
            step_parts.append('Reviewed facts / compressed handoff:\n' + reviewed_facts)
        if review_summary:
            step_parts.append('Reviewer assessment:\n' + review_summary)
        if sources_text:
            step_parts.append('Sources seen in this step:\n' + sources_text)
        if artifact_paths:
            step_parts.append('Artifacts:\n' + '\n'.join(f'- {path}' for path in artifact_paths))
        step_body = header + ':\n' + '\n\n'.join(step_parts)
        if total_step_chars + len(step_body) > SPECIALIZED_FINAL_TOTAL_STEP_CHARS:
            remaining = max(0, SPECIALIZED_FINAL_TOTAL_STEP_CHARS - total_step_chars)
            if remaining < 1200:
                step_sections.append('[Additional specialized-step evidence omitted because final prompt budget was reached.]')
                break
            step_body = step_body[:remaining].rstrip() + '\n\n[Step evidence truncated by final prompt total budget.]'
        step_sections.append(step_body)
        total_step_chars += len(step_body)
    prompt_parts = [
        'Use the specialized-step evidence below when answering the user.',
        build_runtime_context_block(),
        'Original user request:\n' + str(question_text or '').strip(),
    ]
    if shared_context.strip():
        prompt_parts.append('Retrieved context:\n' + shared_context.strip())
    if step_sections:
        prompt_parts.append('Specialized-step evidence package:\n' + '\n\n'.join(step_sections))
    prompt_parts.append(
        'Conflict handling rules:\n'
        '- Treat Raw evidence as the primary record. Reviewed facts are a compact handoff and must not erase concrete raw facts.\n'
        '- If different steps disagree, do not silently prefer the latest step. Explicitly list the conflict and choose a cautious answer policy.\n'
        '- Prefer official/current sources when they directly answer the same field, but preserve concrete secondary-source facts as unverified when they are useful.\n'
        '- Prefer concrete dates, teams, scores, venues, status fields, and URLs over vague summaries.\n'
        '- If a field cannot be verified, say exactly which field is uncertain. Do not turn the entire answer into "check it yourself".\n'
        '- If raw evidence contains a useful table/list/excerpt requested by the user, use it instead of asking the user to open a source manually.'
    )
    prompt_parts.append(
        'Now answer the user directly, integrating the useful results above. '
        'If a step already produced a concrete user-facing deliverable, preserve its concrete details unless there is an explicit conflict. '
        'When conflicts exist, include a clearly labeled conflict/verification-status section.'
    )
    return '\n\n'.join(prompt_parts)


def build_specialized_step_review_messages(capability: str,
                                           goal: str,
                                           question_text: str,
                                           downstream_extract: str,
                                           final_focus: str,
                                           output_text: str,
                                           artifact_paths: list[str],
                                           skill_catalog: str = '') -> list[dict]:
    downstream_need = downstream_extract.strip() or final_focus.strip() or 'the final user-facing answer'
    artifact_text = '\n'.join(f'- {path}' for path in artifact_paths if path)
    available = [key for key, _label in SPECIALIZED_CAPABILITIES] + [BROWSER_USE_CAPABILITY]
    if str(skill_catalog or '').strip():
        available.append(SPECIALIZED_SKILL_CAPABILITY)
    available_capabilities = ', '.join(available)
    skill_instruction = ''
    if str(skill_catalog or '').strip():
        skill_instruction = (
            '\nAvailable skills for dynamic new_step:\n'
            + str(skill_catalog or '').strip()
            + '\nIf a dynamic new_step uses capability "skill", include skill_name exactly.\n'
        )
    return [
        {
            'role': 'system',
            'content': (
                'You are a strict reviewer and evidence-preserving compressor for a multi-step assistant pipeline.\n\n'
                + build_runtime_context_block()
                + '\n\n'
                'Check whether the specialist output satisfies the explicit step goal. Then extract the evidence needed for the next step or final answer without destroying concrete details.\n'
                f'Available capabilities for dynamic new_step: {available_capabilities}.\n'
                + skill_instruction +
                'Rules:\n'
                '- Return JSON only.\n'
                '- Do not add facts not present in the specialist output.\n'
                '- context_output must contain only goal-satisfying information from the output.\n'
                '- Preserve concrete dates, teams, scores, numeric values, venues, status labels, file paths, source URLs, and stated uncertainty.\n'
                '- If the output contains a table/list needed by the final answer, preserve the relevant rows or fields; do not replace them with "see the source".\n'
                '- Remove only rambling, exact repetition, failed attempts, irrelevant background, and implementation chatter.\n'
                '- If the output only partially satisfies the goal, set meets_goal to false but still put the achieved useful evidence in context_output.\n'
                '- If nothing useful was achieved, context_output should be empty and missing should explain what is missing.\n'
                '- Keep context_output concise, but never make a concrete answer more vague merely to save tokens.\n'
                '- If the output contains conflicting claims, preserve the conflict explicitly instead of choosing silently.\n\n'
                'Dynamic planning rules:\n'
                '- Also decide whether the current plan is still sufficient after seeing this output.\n'
                '- Use next_action="accept" when the next existing step or final answer can proceed.\n'
                '- Use next_action="insert_step" only when another specialized step will add a clearly different capability or a targeted verification, not just repeat the same broad search.\n'
                '- Use next_action="retry_step" only when the same kind of step should be retried with a narrower or corrected goal.\n'
                '- For any retry_step or any new_step using web_search after a previous web_search, provide retry_reason, delta_goal, source_strategy, and success_criteria. If you cannot state these four fields concretely, use next_action="accept" and let final answer arbitrate uncertainty.\n'
                '- A targeted retry should verify specific missing or conflicting fields. Do not ask for another broad search of the same topic.\n'
                '- If code execution was skipped because a language is unsupported, retry or insert a step that rewrites equivalent code in the first supported executable language.\n'
                '- Use next_action="stop" only when continuing would be misleading or impossible.\n'
                '- If next_action is insert_step or retry_step, provide new_step with capability, goal, depends_on_previous, extract, context_policy, optional context_query, and the four retry-qualification fields when applicable.\n'
                '- If new_step capability is "skill", also provide skill_name exactly as listed.\n'
                '- The new_step goal must be concrete and self-contained. Do not add broad exploratory steps.\n\n'
                'Output format:\n'
                '{\n'
                '  "meets_goal": true,\n'
                '  "context_output": "only the useful goal-satisfying content",\n'
                '  "missing": "",\n'
                '  "reason": "short assessment",\n'
                '  "next_action": "accept",\n'
                '  "retry_reason": "",\n'
                '  "delta_goal": "",\n'
                '  "source_strategy": "",\n'
                '  "success_criteria": "",\n'
                '  "new_step": null\n'
                '}'
            ),
        },
        {
            'role': 'user',
            'content': (
                'Original user request:\n' + str(question_text or '').strip()
                + '\n\nStep capability:\n' + str(capability or '').strip()
                + '\n\nExplicit step goal:\n' + str(goal or '').strip()
                + '\n\nDownstream need:\n' + downstream_need
                + (('\n\nArtifacts produced:\n' + artifact_text) if artifact_text else '')
                + '\n\nSpecialist output to review:\n' + str(output_text or '').strip()
            ),
        },
    ]


def specialized_capability_label(capability: str) -> str:
    if capability == SPECIALIZED_SKILL_CAPABILITY:
        return 'Skill'
    if capability == BROWSER_USE_CAPABILITY:
        return 'Browser Use'
    for key, label in SPECIALIZED_CAPABILITIES:
        if key == capability:
            return label
    return capability.replace('_', ' ').title()


def build_skill_step_messages(skill: dict,
                              goal: str,
                              question_text: str,
                              shared_context: str,
                              previous_results: list[dict],
                              downstream_extract: str = '',
                              step_context: str = '') -> list[dict]:
    skill_name = sanitize_skill_name(skill.get('name', ''), 'Skill')
    skill_description = str(skill.get('description', '') or '').strip()
    skill_body = str(skill.get('raw_text', '') or '').strip()
    if len(skill_body) > SKILL_BODY_MAX_CHARS:
        skill_body = skill_body[:SKILL_BODY_MAX_CHARS].rstrip() + '\n\n[Skill instructions truncated.]'
    previous_sections = []
    for result in previous_results:
        body = specialized_step_context_output(result)
        if not body:
            continue
        previous_sections.append(
            f"{result.get('capability', 'previous_step')} ({result.get('model_name', '')}):\n{body}"
        )
    system_content = (
        'You are executing one inserted skill step inside a desktop assistant pipeline.\n'
        'The skill is not global context. Follow the skill instructions for this step only.\n'
        'Produce the concrete result needed by the step goal. Do not include hidden reasoning.\n'
        'If the skill produces a final deliverable, surface it clearly and avoid unnecessary restatement.\n\n'
        'Code execution rule:\n'
        '- If the skill requires deterministic counting, calculation, parsing, validation, or any actual code execution, do not invent the result.\n'
        '- Return a single fenced code block in a configured runner language that performs the check. The app will run it in a background worker and send you the real stdout/stderr before finalizing this skill step.\n'
        f'- {code_runner_catalog_text()}\n'
        '- After receiving execution output, correct any earlier numbers using the real stdout/stderr.\n\n'
        f'Skill name: {skill_name}\n'
        + (f'Skill description: {skill_description}\n\n' if skill_description else '\n')
        + 'Skill instructions:\n'
        + skill_body
    )
    if downstream_extract:
        system_content += f'\n\nThe next step will use your output for: "{downstream_extract}". Make that handoff explicit.'
    user_parts = [
        build_runtime_context_block(),
        'Original user request:\n' + str(question_text or '').strip(),
        'Current skill-step goal:\n' + str(goal or '').strip(),
    ]
    if shared_context.strip():
        user_parts.append('Global retrieved context:\n' + shared_context.strip())
    if step_context.strip():
        user_parts.append('Step-specific retrieved context:\n' + step_context.strip())
    if previous_sections:
        user_parts.append('Previous step output:\n' + '\n\n'.join(previous_sections))
    user_parts.append('Return only the skill-step result.')
    return [
        {'role': 'system', 'content': system_content},
        {'role': 'user', 'content': '\n\n'.join(user_parts)},
    ]


def build_specialized_step_messages(capability: str,
                                    goal: str,
                                    question_text: str,
                                    shared_context: str,
                                    previous_results: list[dict],
                                    downstream_extract: str = '',
                                    step_context: str = '') -> list[dict]:
    capability_prompts = {
        'task_reasoning': 'You are the task-reasoning specialist. Produce the strongest structured intermediate result for downstream use.',
        'web_search': 'You are the web-search specialist. If your model/service has search or current-knowledge capabilities, use them and return concise factual findings with useful URLs when available.',
        'text_to_speech': 'You are the text-to-speech specialist. Return the best textual handoff for speech generation or spoken delivery.',
        'speech_to_text': 'You are the speech-to-text specialist. Return the best transcription-style textual result.',
        'image_generation': 'You are the image-generation specialist. If your model/service can generate images, describe the produced image and the prompt used. Otherwise return a strong image prompt package for downstream use.',
        'video_generation': 'You are the video-generation specialist. If your model/service can generate video, describe the produced video and prompt used. Otherwise return a strong video prompt package for downstream use.',
        'video_to_text': 'You are the video-to-text specialist. Return a concise, useful textual summary/transcript-style result.',
    }
    system_content = capability_prompts.get(capability, 'You are a specialized assistant for this step.')
    system_content += (
        '\nIf this step needs deterministic counting, calculation, parsing, validation, or actual code execution, '
        'return a single fenced code block in a configured runner language. The app will run it in a background worker and send you the real stdout/stderr before finalizing this step. '
        'Do not claim computed results without execution. '
        + code_runner_catalog_text()
    )
    if downstream_extract:
        system_content += f'\nThe next step will use your output for: "{downstream_extract}". Ensure your response clearly surfaces that information.'
    previous_sections = []
    for result in previous_results:
        body = specialized_step_context_output(result)
        if not body:
            continue
        previous_sections.append(
            f"{result.get('capability', 'previous_step')} ({result.get('model_name', '')}):\n{body}"
        )
    user_parts = [
        build_runtime_context_block(),
        'Original user request:\n' + str(question_text or '').strip(),
    ]
    if goal.strip():
        user_parts.append('Current step goal:\n' + goal.strip())
    if shared_context.strip():
        user_parts.append('Global retrieved context:\n' + shared_context.strip())
    if step_context.strip():
        user_parts.append('Step-specific retrieved context:\n' + step_context.strip())
    if previous_sections:
        user_parts.append('Previous step output:\n' + '\n\n'.join(previous_sections))
    user_parts.append('Return only the result of this step.')
    return [
        {
            'role': 'system',
            'content': system_content,
        },
        {
            'role': 'user',
            'content': '\n\n'.join(user_parts),
        },
    ]


def query_contains_cjk(text: str) -> bool:
    return bool(re.search(r'[\u4e00-\u9fff]', str(text or '')))


def translate_query_to_english_keywords(query: str) -> str:
    text = str(query or '').strip()
    if not text or not query_contains_cjk(text):
        return ''
    cached = KEYWORD_TRANSLATION_CACHE.get(text)
    if cached is not None:
        return cached

    profile = load_active_settings_profile()
    api_key = str(profile.get('api_key', '')).strip()
    model = str(profile.get('model', '')).strip()
    if not api_key or not model:
        KEYWORD_TRANSLATION_CACHE[text] = ''
        return ''
    endpoint = profile_runtime_base_url(profile)
    try:
        timeout = int(profile.get('timeout', 60) or 60)
    except (TypeError, ValueError):
        timeout = 60

    messages = [
        {
            'role': 'system',
            'content': (
                'Translate the user query into concise English retrieval keywords. '
                'Return only a short English keyword phrase. Preserve names, products, '
                'schools, places, and important entities. Do not explain.'
            ),
        },
        {
            'role': 'user',
            'content': text,
        },
    ]
    translated = ''
    try:
        client = create_openai_client(api_key, endpoint, timeout)
        response = create_chat_completion(
            client,
            endpoint=endpoint,
            model=model,
            messages=messages,
            stream=False,
        )
        translated = (response.choices[0].message.content or '').strip()
    except Exception:
        translated = ''
    lines = [line.strip() for line in str(translated or '').splitlines() if line.strip()]
    translated = (lines[0] if lines else '').strip('\'"“”')
    KEYWORD_TRANSLATION_CACHE[text] = translated
    return translated


def _retrieval_debug_preview(text: str, limit: int = 220) -> str:
    preview = re.sub(r'\s+', ' ', str(text or '')).strip()
    if len(preview) > limit:
        preview = preview[:limit].rstrip() + '...'
    return preview


def print_retrieval_debug(scope: str, strategy: str, question: str, chunks: list[dict]) -> None:
    try:
        header = f"[Broccoli retrieval] scope={scope} strategy={strategy} hits={len(chunks)} question={_retrieval_debug_preview(question, 120)}"
        print(header)
        if not chunks:
            print("[Broccoli retrieval] (no hits)")
            return
        for index, chunk in enumerate(chunks, start=1):
            name = str(chunk.get('name', '')).strip()
            prefix = f"[Broccoli retrieval] #{index}"
            if name:
                prefix += f" {name}"
            print(prefix + f": {_retrieval_debug_preview(chunk.get('display_text') or chunk.get('text', ''))}")
    except Exception:
        pass


def clone_messages_as_text(messages: list[dict]) -> list[dict]:
    cloned = []
    for message in messages:
        content = message.get('content', '')
        if isinstance(content, list):
            parts = []
            for item in content:
                if not isinstance(item, dict):
                    continue
                if item.get('type') == 'text':
                    parts.append(str(item.get('text', '')))
            content = '\n'.join(part for part in parts if part).strip()
        cloned.append({'role': message.get('role', 'user'), 'content': str(content)})
    return cloned


def update_conversation_running_summary(record: dict,
                                        api_key: str,
                                        endpoint: str,
                                        model: str,
                                        timeout: int) -> dict:
    turns = record.get('display', {}).get('turns', [])
    if not turns:
        record['memory']['running_summary'] = ''
        record['memory']['last_summarized_turn_count'] = 0
        return record

    last_summarized = max(0, int(record.get('memory', {}).get('last_summarized_turn_count', 0) or 0))
    if last_summarized >= len(turns):
        return record

    new_turns = turns[last_summarized:]
    new_turn_blocks = []
    for turn in new_turns:
        if turn.get('question', '').strip():
            label = 'Q'
            if turn.get('question_time'):
                label += f" · {turn['question_time']}"
            new_turn_blocks.append(label + '\n' + turn['question'].strip())
        if turn.get('answer', '').strip():
            label = 'A'
            if turn.get('answer_time'):
                label += f" · {turn['answer_time']}"
            new_turn_blocks.append(label + '\n' + turn['answer'].strip())
    if not new_turn_blocks:
        return record

    existing_summary = record.get('memory', {}).get('running_summary', '').strip()
    client = create_openai_client(api_key, endpoint, timeout)
    summary_messages = [
        {
            'role': 'system',
            'content': (
                'You maintain compact conversation memory for a chat assistant. '
                'Summarize only prior conversation turns. Preserve factual details, '
                'decisions, preferences, open questions, names, numbers, code context, '
                'and unresolved follow-ups. Do not add new content. Keep it concise and '
                'structured for future prompts.'
            ),
        },
        {
            'role': 'user',
            'content': (
                ('Existing memory summary:\n' + existing_summary + '\n\n') if existing_summary else ''
            ) + 'New conversation turns to merge:\n' + '\n\n'.join(new_turn_blocks) + '\n\n'
              'Return the updated memory summary only.'
        },
    ]
    response = create_chat_completion(
        client,
        endpoint=endpoint,
        model=model,
        messages=summary_messages,
        stream=False,
    )
    updated_summary = (response.choices[0].message.content or '').strip()
    if updated_summary:
        record['memory']['running_summary'] = updated_summary
        record['memory']['last_summarized_turn_count'] = len(turns)
    return record


def ensure_conversation_retrieval_embeddings(record: dict,
                                             api_key: str,
                                             endpoint: str,
                                             timeout: int,
                                             embedding_model: str) -> dict:
    source_chunks = build_retrieval_chunks(record.get('messages', []))
    existing_chunks = {
        (chunk.get('id'), chunk.get('text')): chunk
        for chunk in record.get('retrieval', {}).get('chunks', [])
        if chunk.get('embedding')
    }
    merged_chunks = []
    pending_texts = []
    pending_indexes = []
    for chunk in source_chunks:
        existing = existing_chunks.get((chunk['id'], chunk['text']))
        if existing and existing.get('embedding'):
            chunk['embedding'] = list(existing['embedding'])
        else:
            pending_indexes.append(len(merged_chunks))
            pending_texts.append(chunk['text'])
        merged_chunks.append(chunk)

    if pending_texts:
        client = create_openai_client(api_key, endpoint, timeout)
        response = client.embeddings.create(model=embedding_model, input=pending_texts)
        for response_item, chunk_index in zip(response.data, pending_indexes):
            merged_chunks[chunk_index]['embedding'] = list(response_item.embedding)

    record['retrieval']['chunks'] = merged_chunks
    return record


def refresh_conversation_runtime_data_for_path(conversation_path: str,
                                               api_key: str,
                                               endpoint: str,
                                               model: str,
                                               timeout: int) -> dict:
    path = str(conversation_path or '').strip()
    if not path:
        return {'updated': False, 'stale': False, 'path': '', 'reason': 'empty_path'}
    record = load_conversation_record(path)
    if record is None:
        return {'updated': False, 'stale': False, 'path': path, 'reason': 'missing_record'}

    start_signature = conversation_messages_signature(record.get('messages', []))
    mutated = False
    turns = record.get('display', {}).get('turns', [])
    try:
        summarized_count = max(0, int(record.get('memory', {}).get('last_summarized_turn_count', 0) or 0))
    except (TypeError, ValueError):
        summarized_count = 0
    if summarized_count < len(turns):
        try:
            record = update_conversation_running_summary(record, api_key, endpoint, model, timeout)
            mutated = True
        except Exception:
            pass

    fresh_chunks = build_retrieval_chunks(record.get('messages', []))
    current_chunks = record.get('retrieval', {}).get('chunks', [])
    needs_retrieval_refresh = len(fresh_chunks) != len(current_chunks)
    if not needs_retrieval_refresh:
        for fresh_chunk, current_chunk in zip(fresh_chunks, current_chunks):
            if fresh_chunk.get('id') != current_chunk.get('id') or fresh_chunk.get('text') != current_chunk.get('text'):
                needs_retrieval_refresh = True
                break
            if not current_chunk.get('embedding'):
                needs_retrieval_refresh = True
                break
    if needs_retrieval_refresh:
        record['retrieval']['chunks'] = fresh_chunks
        mutated = True

    embedding_config = load_embedding_runtime_config()
    embedding_ok = False
    if embedding_config is not None:
        embedding_ok, _ = probe_embedding_capability(embedding_config['profile'])
    if embedding_ok and embedding_config is not None:
        embedding_chunks = record.get('retrieval', {}).get('chunks', [])
        if any(not chunk.get('embedding') for chunk in embedding_chunks):
            try:
                record = ensure_conversation_retrieval_embeddings(
                    record,
                    embedding_config['api_key'],
                    embedding_config['endpoint'],
                    embedding_config['timeout'],
                    embedding_config['model'],
                )
                mutated = True
            except Exception:
                pass

    if not mutated:
        return {'updated': False, 'stale': False, 'path': path, 'reason': 'unchanged'}

    latest = load_conversation_record(path)
    if latest is None:
        return {'updated': False, 'stale': True, 'path': path, 'reason': 'missing_latest_record'}
    if conversation_messages_signature(latest.get('messages', [])) != start_signature:
        return {'updated': False, 'stale': True, 'path': path, 'reason': 'messages_changed'}

    latest_memory = latest.get('memory', {}) if isinstance(latest.get('memory'), dict) else {}
    refreshed_memory = record.get('memory', {}) if isinstance(record.get('memory'), dict) else {}
    try:
        latest_count = int(latest_memory.get('last_summarized_turn_count', 0) or 0)
        refreshed_count = int(refreshed_memory.get('last_summarized_turn_count', 0) or 0)
    except (TypeError, ValueError):
        latest_count = 0
        refreshed_count = 0
    latest['memory'] = refreshed_memory if refreshed_count >= latest_count else latest_memory

    latest_embedding_by_key = {
        (chunk.get('id'), chunk.get('text')): chunk.get('embedding')
        for chunk in latest.get('retrieval', {}).get('chunks', [])
        if chunk.get('embedding')
    }
    refreshed_chunks = []
    for chunk in record.get('retrieval', {}).get('chunks', []):
        merged_chunk = dict(chunk)
        if not merged_chunk.get('embedding'):
            existing_embedding = latest_embedding_by_key.get((merged_chunk.get('id'), merged_chunk.get('text')))
            if existing_embedding:
                merged_chunk['embedding'] = list(existing_embedding)
        refreshed_chunks.append(merged_chunk)
    latest['retrieval'] = {'chunks': refreshed_chunks}
    saved = write_conversation_record(path, latest)
    return {'updated': True, 'stale': False, 'path': saved.get('path', path), 'reason': 'saved'}


def retrieve_conversation_chunks(record: dict,
                                 query: str,
                                 api_key: str,
                                 endpoint: str,
                                 timeout: int,
                                 embedding_model: str,
                                 top_k: int = CONVERSATION_RETRIEVAL_TOP_K,
                                 candidate_chunks: list[dict] | None = None) -> list[dict]:
    source_chunks = candidate_chunks if candidate_chunks is not None else record.get('retrieval', {}).get('chunks', [])
    chunks = [
        chunk for chunk in source_chunks
        if chunk.get('embedding') and chunk.get('text', '').strip()
    ]
    if not query.strip() or not chunks:
        return []
    client = create_openai_client(api_key, endpoint, timeout)
    query_embedding = client.embeddings.create(model=embedding_model, input=query).data[0].embedding
    ranked = []
    for chunk in chunks:
        ranked.append((vector_similarity(query_embedding, chunk['embedding']), chunk))
    ranked.sort(key=lambda item: item[0], reverse=True)

    results = []
    seen_texts = set()
    for _, chunk in ranked:
        text_key = chunk['text'].strip()
        if text_key in seen_texts:
            continue
        seen_texts.add(text_key)
        results.append(chunk)
        if len(results) >= top_k:
            break
    return results


def _keyword_query_terms(query: str) -> list[str]:
    text = str(query or '').strip().lower()
    if not text:
        return []
    tokens = []
    if re.search(r'[\u4e00-\u9fff]', text):
        tokens.extend(token.strip() for token in jieba.lcut(text) if token.strip())
    tokens.extend(re.findall(r'[\w\u4e00-\u9fff]+', text))
    ordered = []
    seen = set()
    for token in [text] + tokens:
        token = token.strip()
        if not token:
            continue
        if len(token) == 1 and not token.isdigit():
            continue
        if token in seen:
            continue
        seen.add(token)
        ordered.append(token)
    return ordered


def _rank_keyword_chunks(chunks: list[dict], terms: list[str], top_k: int) -> list[dict]:
    ranked = []
    for chunk in chunks:
        text = chunk.get('text', '').lower()
        if not text:
            continue
        score = 0.0
        for index, term in enumerate(terms):
            if term in text:
                if index == 0:
                    score += 12.0
                score += max(1.0, min(6.0, len(term) / 2.0))
        if score > 0:
            ranked.append((score, chunk))
    ranked.sort(key=lambda item: item[0], reverse=True)
    return [chunk for _, chunk in ranked[:top_k]]


def keyword_retrieve_conversation_chunks(record: dict,
                                         query: str,
                                         top_k: int = CONVERSATION_RETRIEVAL_TOP_K) -> list[dict]:
    chunks = record.get('retrieval', {}).get('chunks', []) or build_retrieval_chunks(record.get('messages', []))
    terms = _keyword_query_terms(query)
    if not terms:
        return chunks[:top_k]
    results = _rank_keyword_chunks(chunks, terms, top_k)
    if results or not query_contains_cjk(query):
        return results
    translated_query = translate_query_to_english_keywords(query)
    translated_terms = _keyword_query_terms(translated_query)
    if not translated_terms:
        return results
    merged_terms = terms + [term for term in translated_terms if term not in terms]
    return _rank_keyword_chunks(chunks, merged_terms, top_k)


def _fit_text_to_char_limit(text: str, max_chars: int) -> str:
    content = str(text or '')
    max_chars = max(0, int(max_chars or 0))
    if max_chars <= 0 or len(content) <= max_chars:
        return content
    if max_chars <= 120:
        return content[:max_chars].rstrip()
    head_chars = max(40, int(max_chars * 0.55))
    tail_chars = max(40, max_chars - head_chars - 80)
    omitted = len(content) - head_chars - tail_chars
    marker = f'\n\n[... {max(0, omitted)} chars omitted from this previous message ...]\n\n'
    fitted = content[:head_chars].rstrip() + marker + content[-tail_chars:].lstrip()
    return fitted[:max_chars].rstrip()


def _split_text_for_summary_batches(text: str,
                                    batch_chars: int = CONVERSATION_LONG_MESSAGE_SUMMARY_BATCH_CHARS) -> list[str]:
    content = str(text or '').strip()
    if not content:
        return []
    batch_chars = max(1000, int(batch_chars or CONVERSATION_LONG_MESSAGE_SUMMARY_BATCH_CHARS))
    return [content[index:index + batch_chars] for index in range(0, len(content), batch_chars)]


def _summarize_history_text_for_prompt(content: str,
                                       role: str,
                                       api_key: str,
                                       endpoint: str,
                                       model: str,
                                       timeout: int,
                                       target_chars: int = CONVERSATION_RECENT_MESSAGE_SUMMARY_TARGET_CHARS) -> str:
    text = str(content or '').strip()
    if not text:
        return ''
    target_chars = max(500, int(target_chars or CONVERSATION_RECENT_MESSAGE_SUMMARY_TARGET_CHARS))
    role_label = 'user' if str(role or '').strip().lower() == 'user' else 'assistant'
    batches = _split_text_for_summary_batches(text)
    if not batches:
        return ''

    def summarize_piece(piece: str, piece_target: int, label: str) -> str:
        client = create_openai_client(api_key, endpoint, timeout)
        messages = [
            {
                'role': 'system',
                'content': (
                    'Compress previous conversation content for future chat context. '
                    'Preserve concrete facts, names, numbers, user preferences, tasks, decisions, '
                    'open questions, and references needed to resolve pronouns such as this, that, '
                    'above, previous, 刚才, 上面, and 这个. Do not add new facts.'
                ),
            },
            {
                'role': 'user',
                'content': (
                    f'Summarize this previous {role_label} message {label} in no more than '
                    f'{piece_target} characters. Keep the same language when possible.\n\n'
                    f'{piece}'
                ),
            },
        ]
        response = create_chat_completion(
            client,
            endpoint=endpoint,
            model=model,
            messages=messages,
            stream=False,
        )
        return (response.choices[0].message.content or '').strip()

    try:
        if len(batches) == 1:
            summary = summarize_piece(batches[0], target_chars, '')
        else:
            per_batch_target = max(450, int(target_chars / max(1, len(batches))) + 200)
            summaries = []
            for index, batch in enumerate(batches, start=1):
                summaries.append(summarize_piece(batch, per_batch_target, f'part {index}/{len(batches)}'))
            merged = '\n'.join(part for part in summaries if part.strip()).strip()
            if len(merged) > target_chars:
                summary = summarize_piece(merged, target_chars, 'merged from batch summaries')
            else:
                summary = merged
    except Exception:
        summary = _fit_text_to_char_limit(text, target_chars)

    summary = _fit_text_to_char_limit(summary, target_chars)
    return (
        f'[Previous {role_label} message compressed from {len(text)} chars for context.]\n'
        + summary
    ).strip()


def build_budgeted_history_messages_for_prompt(history_messages: list[dict],
                                               api_key: str,
                                               endpoint: str,
                                               model: str,
                                               timeout: int,
                                               max_messages: int | None = CONVERSATION_RECENT_MESSAGES,
                                               per_message_max_chars: int = CONVERSATION_RECENT_MESSAGE_MAX_CHARS,
                                               total_max_chars: int = CONVERSATION_RECENT_MESSAGES_TOTAL_CHARS) -> list[dict]:
    normalized = []
    for message in history_messages or []:
        normalized_message = normalize_chat_history_message(message)
        if normalized_message:
            normalized.append(normalized_message)
    if max_messages is not None:
        normalized = normalized[-max(0, int(max_messages or 0)):]
    if not normalized:
        return []

    prompt_messages = []
    for message in normalized:
        role = message.get('role', 'user')
        content = str(message.get('content', '') or '')
        if len(content) > per_message_max_chars:
            content = _summarize_history_text_for_prompt(
                content,
                role,
                api_key,
                endpoint,
                model,
                timeout,
            )
        prompt_messages.append({'role': role, 'content': content})

    total_max_chars = max(1000, int(total_max_chars or CONVERSATION_RECENT_MESSAGES_TOTAL_CHARS))
    total_chars = sum(len(message.get('content', '')) for message in prompt_messages)
    if total_chars <= total_max_chars:
        return prompt_messages

    per_message_limit = max(500, int(total_max_chars / max(1, len(prompt_messages))) - 120)
    fitted = []
    for message in prompt_messages:
        content = str(message.get('content', '') or '')
        if len(content) > per_message_limit:
            content = _fit_text_to_char_limit(content, per_message_limit)
        fitted.append({'role': message.get('role', 'user'), 'content': content})
    return fitted


DEICTIC_HISTORY_REFERENCE_RE = re.compile(
    r'(刚才|剛才|刚刚|上面|上面的|前面|上一条|上一輪|之前|这个|这段|这些|这件|这里|'
    r'那个|那段|那些|它|他|她|其|this|that|above|previous|earlier|last)',
    re.IGNORECASE,
)


def build_deictic_history_resolution_note(question_text: str) -> str:
    if not DEICTIC_HISTORY_REFERENCE_RE.search(str(question_text or '')):
        return ''
    return (
        'The current user request appears to refer back to recent conversation content. '
        'Resolve pronouns and references such as "上面", "刚才", "这个", "this", '
        '"that", or "previous" from the actual recent user/assistant messages first. '
        'Use external context, saved memory, or retrieved documents only as secondary context '
        'when they are explicitly relevant.'
    )


def build_conversation_context_block(record: dict,
                                     relevant_chunks: list[dict],
                                     recent_message_count: int = CONVERSATION_RECENT_MESSAGES) -> str:
    blocks = []
    running_summary = record.get('memory', {}).get('running_summary', '').strip()
    if running_summary:
        blocks.append('Conversation memory summary:\n' + running_summary)

    recent_messages = record.get('messages', [])[-recent_message_count:] if recent_message_count > 0 else []
    if recent_messages:
        blocks.append('Recent conversation turns:\n' + render_chat_history_plaintext(recent_messages))

    if relevant_chunks:
        excerpt_blocks = []
        for index, chunk in enumerate(relevant_chunks, start=1):
            excerpt_blocks.append(f"[Relevant history excerpt {index}]\n{chunk.get('display_text', chunk.get('text', '')).strip()}")
        blocks.append('Relevant exact history excerpts:\n' + '\n\n'.join(excerpt_blocks))

    return '\n\n'.join(block for block in blocks if block).strip()


def build_history_context(messages: list[dict]) -> str:
    parts = []
    for message in messages:
        label = 'Q' if message['role'] == 'user' else 'A'
        parts.append(f'{label}: {message["content"]}')
    return '\n'.join(parts)


def should_use_display_history_context(messages: list[dict],
                                       max_chars: int = DISPLAY_HISTORY_CONTEXT_MAX_CHARS) -> bool:
    if not messages:
        return False
    try:
        plain = render_chat_history_plaintext(messages).strip()
    except Exception:
        plain = build_history_context(messages).strip()
    return bool(plain) and len(plain) <= max_chars


def build_chat_preview(history_messages: list[dict], question_text: str, answer_text: str = '') -> str:
    preview_messages = list(history_messages)
    preview_messages.append({'role': 'user', 'content': question_text})
    preview_messages.append({'role': 'assistant', 'content': answer_text})
    return render_chat_history_plaintext(preview_messages)


def parse_broccoli_output_attrs(raw_attrs: str) -> dict:
    attrs = {}
    for match in BROCCOLI_OUTPUT_ATTR_RE.finditer(str(raw_attrs or '')):
        key = match.group(1).strip().lower().replace('-', '_')
        value = match.group(3) if match.group(3) is not None else match.group(4)
        attrs[key] = html.unescape(str(value or '').strip())
    return attrs


def split_structured_outputs_from_answer(answer_text: str) -> tuple[str, list[dict]]:
    matches = list(BROCCOLI_OUTPUT_BLOCK_RE.finditer(str(answer_text or '')))
    if not matches:
        return str(answer_text or ''), []
    outputs = []
    # The UI is intentionally single-answer: if a model emits several blocks,
    # keep only the last one as the final chosen deliverable.
    match = matches[-1]
    attrs = parse_broccoli_output_attrs(match.group(1))
    kind = str(attrs.get('type', attrs.get('kind', 'text'))).strip().lower()
    if kind not in {'code', 'text'}:
        kind = 'text'
    content = html.unescape(match.group(2)).strip()
    if content:
        outputs.append(
            {
                'kind': kind,
                'title': str(attrs.get('title', '')).strip(),
                'filename': str(attrs.get('filename', '')).strip(),
                'content': content,
                'source': 'assistant_block',
            }
        )
    cleaned = BROCCOLI_OUTPUT_BLOCK_RE.sub('', str(answer_text or '')).strip()
    return cleaned, outputs


def strip_structured_outputs_from_display_text(text: str) -> str:
    return BROCCOLI_OUTPUT_BLOCK_RE.sub('', str(text or '')).strip()


def build_assistant_message_content(answer_text: str, mode_index: int, references: str = '', show_references: bool = False) -> tuple[str, str]:
    cleaned_answer = answer_text.strip()
    if mode_index in (0, 7):
        if show_references and references:
            cleaned_answer = (cleaned_answer + '\n\n' + references.strip()).strip()
        return cleaned_answer, ''

    extracted, remainder = extract_marker_block(cleaned_answer)
    if mode_index == 1:
        command_body = extracted or cleaned_answer
        message_body = remainder.strip()
        if message_body:
            message_body = message_body + '\n\n'
        message_body = message_body + 'Command:\n\n```applescript\n' + command_body.strip() + '\n```'
        return message_body.strip(), command_body.strip()

    body = extracted or cleaned_answer
    if remainder.strip() and remainder.strip() != body:
        body = remainder.strip() + '\n\n' + body
    return body.strip(), body.strip()


def extract_marker_block(text: str) -> tuple[str, str]:
    match = MARKER_BLOCK_RE.search(text)
    if not match:
        return '', text
    extracted = match.group(1).strip('\n').strip('\t').strip()
    remainder = MARKER_BLOCK_RE.sub('', text).strip('\n')
    return extracted, remainder


def format_regular_mode_output(prefix_text: str, answer_text: str) -> str:
    return ensure_message_separator(normalize_conversation_text(prefix_text + answer_text))


def format_special_mode_output(prefix_text: str, answer_text: str, mode_index: int) -> tuple[str, str]:
    combined = normalize_conversation_text(prefix_text + answer_text)
    extracted, remainder = extract_marker_block(combined)
    if not extracted:
        extracted = answer_text.strip()
    if mode_index == 1:
        body = remainder.strip('\n')
        if body:
            body = body + "Your command is:" + '\n\t' + extracted
        else:
            body = "Your command is:" + '\n\t' + extracted
        return ensure_message_separator(body), extracted

    body = remainder.strip('\n')
    if body and extracted:
        body = body + '\n' + extracted
    elif extracted:
        body = extracted
    return ensure_message_separator(body), extracted


def load_saved_timeout(default_timeout: int = 60) -> int:
    timeset = read_text_file(BasePath + 'timeout.txt', str(default_timeout))
    try:
        return int(timeset) if timeset else default_timeout
    except ValueError:
        return default_timeout


def vector_similarity(x: list[float], y: list[float]) -> float:
    return float(np.dot(np.array(x), np.array(y)))


def attachment_supports_embedding(path: str) -> bool:
    ext = os.path.splitext(str(path or ''))[1].lower()
    return ext in ATTACHMENT_TEXT_EXTS or ext in {'.pdf', '.docx'}


def _ocr_pdf_text(path: str) -> str:
    try:
        import fitz  # pymupdf
        import pytesseract
        from PIL import Image as _PILImage
    except Exception:
        return ''

    text_blocks = []
    try:
        doc = fitz.open(path)
        total = len(doc)
        max_pages = load_pdf_max_pages()
        pages_to_scan = total if max_pages == 0 else min(total, max_pages)
        for page_num in range(pages_to_scan):
            page = doc.load_page(page_num)
            pix = page.get_pixmap(matrix=fitz.Matrix(150 / 72, 150 / 72), alpha=False)
            pil_img = _PILImage.frombytes('RGB', (pix.width, pix.height), pix.samples)
            page_text = pytesseract.image_to_string(pil_img).strip()
            if page_text:
                text_blocks.append(page_text)
        doc.close()
    except Exception:
        return ''
    return '\n\n'.join(block for block in text_blocks if block).strip()


def extract_attachment_text(path: str,
                            allow_ocr: bool = True,
                            limit_chars: int | None = None) -> dict | None:
    path = str(path or '')
    if not path:
        return None
    name = os.path.basename(path)
    ext = os.path.splitext(path)[1].lower()
    mime, _ = mimetypes.guess_type(path)
    mime = mime or ''
    content = ''

    if ext == '.pdf' or 'pdf' in mime:
        try:
            from pdfminer.high_level import extract_text as _pdftext
            content = (_pdftext(path) or '').strip()
        except Exception:
            content = ''
        if not content and allow_ocr:
            content = _ocr_pdf_text(path)
    elif ext == '.docx':
        try:
            content = (docx2txt.process(path) or '').strip()
        except Exception:
            content = ''
    elif ext in ATTACHMENT_TEXT_EXTS or mime.startswith('text/'):
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                content = f.read()
        except Exception:
            content = ''
    else:
        return None

    if not content:
        return None
    if limit_chars is not None:
        content = content[:limit_chars]
    return {
        'kind': 'text',
        'name': name,
        'content': content,
        'source_path': path,
    }


def build_attachment_retrieval_chunks(documents: list[dict]) -> list[dict]:
    chunks = []
    for doc_index, document in enumerate(documents):
        name = str(document.get('name', f'Document {doc_index + 1}')).strip() or f'Document {doc_index + 1}'
        content = str(document.get('content', '')).strip()
        if not content:
            continue
        for chunk_index, chunk_text in enumerate(chunk_text_for_retrieval(content)):
            chunks.append(
                {
                    'id': f'd{doc_index}-c{chunk_index}',
                    'name': name,
                    'text': chunk_text,
                    'display_text': f'{name}\n{chunk_text}',
                    'source_type': document.get('source_type', ''),
                    'tool_name': document.get('tool_name', ''),
                }
            )
    return chunks


def keyword_retrieve_attachment_chunks(chunks: list[dict],
                                       query: str,
                                       top_k: int = ATTACHMENT_RETRIEVAL_TOP_K) -> list[dict]:
    terms = _keyword_query_terms(query)
    if not terms:
        return chunks[:top_k]
    results = _rank_keyword_chunks(chunks, terms, top_k)
    if results or not query_contains_cjk(query):
        return results
    translated_query = translate_query_to_english_keywords(query)
    translated_terms = _keyword_query_terms(translated_query)
    if not translated_terms:
        return results
    merged_terms = terms + [term for term in translated_terms if term not in terms]
    return _rank_keyword_chunks(chunks, merged_terms, top_k)


def retrieve_attachment_chunks(chunks: list[dict],
                               query: str,
                               api_key: str,
                               endpoint: str,
                               timeout: int,
                               embedding_model: str,
                               top_k: int = ATTACHMENT_RETRIEVAL_TOP_K,
                               min_cosine: float | None = None) -> list[dict]:
    if not query.strip() or not chunks:
        return []
    client = create_openai_client(api_key, endpoint, timeout)
    chunk_texts = [chunk['text'] for chunk in chunks]
    response = client.embeddings.create(model=embedding_model, input=chunk_texts)
    chunk_embeddings = [list(item.embedding) for item in response.data]
    query_embedding = client.embeddings.create(model=embedding_model, input=query).data[0].embedding
    # Explicit cosine for the relevance gate, so an absolute min_cosine threshold
    # is meaningful regardless of whether the embedding model returns unit-norm
    # vectors. Ranking itself stays on the existing dot-product score so behaviour
    # for callers that do not pass min_cosine is unchanged.
    query_vec = np.array(query_embedding, dtype=float)
    query_norm = float(np.linalg.norm(query_vec)) or 1.0
    ranked = []
    for chunk, embedding in zip(chunks, chunk_embeddings):
        chunk_vec = np.array(embedding, dtype=float)
        score = float(np.dot(query_vec, chunk_vec))
        cosine = score / (query_norm * (float(np.linalg.norm(chunk_vec)) or 1.0))
        ranked.append((score, cosine, chunk))
    ranked.sort(key=lambda item: item[0], reverse=True)

    results = []
    seen_ids = set()
    dropped = 0
    for _, cosine, chunk in ranked:
        if min_cosine is not None and cosine < float(min_cosine):
            dropped += 1
            continue
        if chunk['id'] in seen_ids:
            continue
        seen_ids.add(chunk['id'])
        results.append(chunk)
        if len(results) >= top_k:
            break
    if min_cosine is not None:
        top_cosine = ranked[0][1] if ranked else 0.0
        print(f'[Broccoli retrieval] min_cosine={float(min_cosine):.2f} '
              f'kept={len(results)} dropped={dropped} top_cosine={top_cosine:.3f}')
    return results


def build_attachment_context_block(relevant_chunks: list[dict]) -> str:
    if not relevant_chunks:
        return ''
    blocks = []
    for index, chunk in enumerate(relevant_chunks, start=1):
        blocks.append(
            f"[Attached document excerpt {index} — {chunk.get('name', 'Document')}]\n"
            f"{chunk.get('text', '').strip()}"
        )
    return 'Relevant excerpts from attached documents:\n' + '\n\n'.join(block for block in blocks if block)


def build_attachment_references(relevant_chunks: list[dict]) -> str:
    if not relevant_chunks:
        return ''
    names = []
    seen = set()
    for chunk in relevant_chunks:
        name = str(chunk.get('name', '')).strip()
        if not name or name in seen:
            continue
        seen.add(name)
        names.append(name)
    if not names:
        return ''
    return 'References:\n' + '\n'.join(f'- {name}' for name in names)


def _external_source_patterns(source: dict, key: str, default_value: str = '') -> list[str]:
    return _split_context_patterns(str(source.get(key, '') or default_value))


def _external_path_matches(path: str, root: str, include_patterns: list[str], exclude_patterns: list[str]) -> bool:
    rel = os.path.relpath(path, root).replace(os.sep, '/')
    name = os.path.basename(path)
    for pattern in exclude_patterns:
        normalized = pattern.replace(os.sep, '/')
        if fnmatch.fnmatch(rel, normalized) or fnmatch.fnmatch(name, normalized):
            return False
    if not include_patterns:
        return True
    return any(fnmatch.fnmatch(rel, pattern) or fnmatch.fnmatch(name, pattern) for pattern in include_patterns)


def collect_local_external_context_documents(source: dict) -> list[dict]:
    path = str(source.get('path', '') or '').strip()
    if not path or not os.path.exists(path):
        return []
    max_chars = normalize_external_context_max_chars(source.get('max_chars', DEFAULT_EXTERNAL_CONTEXT_MAX_CHARS))
    include_patterns = _external_source_patterns(source, 'include_patterns', DEFAULT_EXTERNAL_CONTEXT_INCLUDE_PATTERNS)
    exclude_patterns = _external_source_patterns(source, 'exclude_patterns', DEFAULT_EXTERNAL_CONTEXT_EXCLUDE_PATTERNS)
    source_name = str(source.get('name', '') or 'Local context').strip()
    documents = []

    def add_file(file_path: str):
        if len(documents) >= DEFAULT_EXTERNAL_CONTEXT_MAX_FILES:
            return
        extracted = extract_attachment_text(
            file_path,
            allow_ocr=False,
            limit_chars=min(DEFAULT_EXTERNAL_CONTEXT_FILE_CHARS, max_chars),
        )
        if not extracted or not str(extracted.get('content', '')).strip():
            return
        try:
            rel_name = os.path.relpath(file_path, path if os.path.isdir(path) else os.path.dirname(path))
        except Exception:
            rel_name = os.path.basename(file_path)
        documents.append(
            {
                'name': f'{source_name} / {rel_name}',
                'content': str(extracted.get('content', '') or ''),
                'source_path': file_path,
                'source_name': source_name,
                'source_type': 'local_path',
            }
        )

    if os.path.isfile(path):
        add_file(path)
        return documents

    for root, dirs, files in os.walk(path):
        dirs[:] = [
            dirname for dirname in dirs
            if dirname not in {'.git', 'node_modules', '.venv', '__pycache__'}
        ]
        for filename in sorted(files):
            file_path = os.path.join(root, filename)
            if _external_path_matches(file_path, path, include_patterns, exclude_patterns):
                add_file(file_path)
            if len(documents) >= DEFAULT_EXTERNAL_CONTEXT_MAX_FILES:
                return documents
    return documents


def collect_external_context_documents(sources: list[dict],
                                       question_text: str = '',
                                       progress_callback=None) -> list[dict]:
    local_documents = []
    mcp_documents = []
    mcp_sources = []
    for source in normalize_external_context_sources(sources):
        if not source.get('enabled', True) or not source.get('auto_context', True):
            continue
        if source.get('type') == 'local_path':
            local_documents.extend(collect_local_external_context_documents(source))
        elif source.get('type') in {'mcp_http', 'mcp_stdio'}:
            mcp_sources.append(source)
    for source in mcp_sources[:MCP_RETRIEVAL_MAX_SOURCES]:
        mcp_documents.extend(collect_mcp_external_context_documents(source, question_text, progress_callback))
    return mcp_documents + local_documents


def build_external_context_full_block(documents: list[dict], max_chars: int) -> str:
    blocks = []
    remaining = max(0, int(max_chars))
    for index, document in enumerate(documents, start=1):
        name = str(document.get('name', f'External source {index}') or f'External source {index}').strip()
        content = str(document.get('content', '') or '').strip()
        if not content or remaining <= 0:
            continue
        excerpt = content[:remaining]
        remaining -= len(excerpt)
        blocks.append(f"[External context {index} - {name}]\n{excerpt}")
    if not blocks:
        return ''
    return 'External context sources:\n' + '\n\n'.join(blocks)


def build_external_context_retrieval_block(relevant_chunks: list[dict]) -> str:
    if not relevant_chunks:
        return ''
    blocks = []
    for index, chunk in enumerate(relevant_chunks, start=1):
        blocks.append(
            f"[External context excerpt {index} - {chunk.get('name', 'External source')}]\n"
            f"{chunk.get('text', '').strip()}"
        )
    return 'Relevant excerpts from external context sources:\n' + '\n\n'.join(block for block in blocks if block)


def normalize_agent_supplement_records(supplements: list[dict] | None) -> list[dict]:
    normalized = []
    for item in supplements or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get('text', '') or '').strip()
        if not text:
            continue
        normalized.append(
            {
                'id': str(item.get('id', '') or '').strip(),
                'text': text,
                'created_at': str(item.get('created_at', '') or '').strip(),
            }
        )
    return normalized


def build_agent_supplement_instruction_block(supplements: list[dict] | None, *, continuation: bool = False) -> str:
    records = normalize_agent_supplement_records(supplements)
    if not records:
        return ''
    numbered = '\n'.join(
        f"{index}. {record['text']}"
        for index, record in enumerate(records, start=1)
    )
    if continuation:
        action = (
            'Please continue or revise the previous answer according to this added instruction. '
            'Briefly state that the user added this instruction, then explain the updated plan and continue.'
        )
    else:
        action = (
            'Treat this as a live user update for the current answer. '
            'In the final answer, explicitly state that the user added this instruction, '
            'then adjust the plan and subsequent work accordingly.'
        )
    return (
        'User added the following instruction while the previous answer was being generated:\n\n'
        f'{numbered}\n\n'
        f'{action}'
    ).strip()


def build_agent_supplement_step_result(supplements: list[dict] | None, *, stage: str = '') -> dict:
    block = build_agent_supplement_instruction_block(supplements, continuation=False)
    if not block:
        return {}
    return {
        'capability': 'user_supplement',
        'capability_label': 'User added instruction',
        'model_name': '',
        'text_output': block,
        'context_output': block,
        'artifacts': [],
        'metadata': {
            'goal': 'Apply the user instruction added during generation.',
            'execution_mode': 'user_input',
            'stage': str(stage or '').strip(),
        },
    }


class AsyncPreflightSignals(QObject):
    progress = pyqtSignal(str)
    plan_update = pyqtSignal(object)
    terminal_command = pyqtSignal(object)
    external_target = pyqtSignal(object)
    finished = pyqtSignal(object)
    failed = pyqtSignal(str)


class AsyncPreflightThread(threading.Thread):
    def __init__(self, owner, config: dict, signals: AsyncPreflightSignals):
        super().__init__(daemon=True)
        self.owner = owner
        self.config = config
        self.signals = signals
        self._stop_event = threading.Event()

    def request_stop(self):
        self._stop_event.set()

    def _run_terminal_command_request(self, arguments: dict) -> dict:
        request = build_agent_terminal_command_request(
            arguments,
            run_id=str(self.config.get('run_id', '') or ''),
            conversation_path=str(self.config.get('conversation_path', '') or ''),
        )
        request['event'] = threading.Event()
        request['result'] = None
        self.signals.terminal_command.emit(request)
        approval_window = (
            AGENT_TERMINAL_READ_DEFAULT_ALLOW_SECONDS
            if request.get('read_only', True)
            else AGENT_TERMINAL_WRITE_DEFAULT_DENY_SECONDS
        )
        timeout_seconds = int(request.get('timeout_seconds', 120) or 120)
        if not request['event'].wait(max(30, approval_window + timeout_seconds + 30)):
            return {
                'status': 'timeout',
                'text': 'Terminal command request timed out before completion.',
                'command': str(request.get('command', '') or ''),
            }
        result = request.get('result')
        if isinstance(result, dict):
            return result
        return {
            'status': 'failed',
            'text': 'Terminal command returned no result.',
            'command': str(request.get('command', '') or ''),
        }

    def _run_external_target_request(self, arguments: dict) -> dict:
        arguments = dict(arguments or {})
        request = {
            'id': f"external-step-{int(time.time() * 1000)}-{threading.get_ident()}",
            'run_id': str(self.config.get('run_id', '') or ''),
            'conversation_path': str(self.config.get('conversation_path', '') or ''),
            'profile_name': str(arguments.get('profile_name', '') or '').strip(),
            'prompt': str(arguments.get('prompt', '') or '').strip(),
            'goal': str(arguments.get('goal', '') or '').strip(),
            'question_text': str(arguments.get('question_text', '') or self.config.get('question_text', '') or '').strip(),
            'shared_context': str(arguments.get('shared_context', '') or '').strip(),
            'attachments': list(arguments.get('attachments') or self.config.get('attachments') or []),
            'attachment_records': list(arguments.get('attachment_records') or self.config.get('attachment_records') or []),
            'timeout': int(arguments.get('timeout', self.config.get('timeout', 180)) or 180),
            'api_key': str(self.config.get('api_key', '') or ''),
            'endpoint': str(self.config.get('endpoint', '') or ''),
            'model': str(self.config.get('model', '') or ''),
            'event': threading.Event(),
            'result': None,
        }
        self.signals.external_target.emit(request)
        if not request['event'].wait(max(60, int(request.get('timeout', 180) or 180) + 90)):
            return {
                'status': 'timeout',
                'answer': '',
                'text': f"External target {request['profile_name']} timed out before completion.",
            }
        result = request.get('result')
        if isinstance(result, dict):
            return result
        return {
            'status': 'failed',
            'answer': '',
            'text': f"External target {request['profile_name']} returned no result.",
        }

    def run(self):
        try:
            owner = self.owner

            def progress(message: str):
                if not self._stop_event.is_set() and str(message or '').strip():
                    self.signals.progress.emit(str(message or '').strip())

            def plan_update(payload: dict):
                if self._stop_event.is_set() or not isinstance(payload, dict):
                    return
                payload = dict(payload)
                payload.setdefault('run_id', str(self.config.get('run_id', '') or ''))
                payload.setdefault('conversation_path', str(self.config.get('conversation_path', '') or ''))
                self.signals.plan_update.emit(payload)

            def consume_supplements() -> list[dict]:
                provider = self.config.get('supplement_provider')
                if not callable(provider):
                    return []
                try:
                    return normalize_agent_supplement_records(provider() or [])
                except Exception:
                    return []

            raw_question_text = str(self.config.get('question_text', '') or '')
            question_text = str(self.config.get('retrieval_question_text', '') or raw_question_text)
            history_messages = list(self.config.get('history_messages') or [])
            retrieval_documents = list(self.config.get('retrieval_documents') or [])
            attachment_records = list(self.config.get('attachment_records') or [])
            api_key = str(self.config.get('api_key', '') or '')
            endpoint = str(self.config.get('endpoint', '') or '')
            model = str(self.config.get('model', '') or '')
            timeout = int(self.config.get('timeout', 60) or 60)
            mode_index = int(self.config.get('mode_index', 0) or 0)
            selected_message_indices = set(self.config.get('selected_message_indices') or [])
            skip_retrieval_for_blank_prompt = bool(self.config.get('skip_retrieval_for_blank_prompt', False))
            conversation_path = str(self.config.get('conversation_path', '') or '')

            if self._stop_event.is_set():
                self.signals.finished.emit({'cancelled': True})
                return

            attachment_context = ''
            attachment_references = ''
            if skip_retrieval_for_blank_prompt:
                retrieval_documents = []
            if retrieval_documents:
                progress('Reading attached documents')
                attachment_context, attachment_references = owner._build_attachment_retrieval_context(
                    question_text,
                    retrieval_documents,
                    api_key,
                    endpoint,
                    timeout,
                )

            if self._stop_event.is_set():
                self.signals.finished.emit({'cancelled': True})
                return

            context_blocks = []
            prompt_history_messages = []
            active_profile = load_active_settings_profile()
            if not skip_retrieval_for_blank_prompt and read_text_file(BasePath + 'history.txt', '0') == '1':
                progress('Retrieving conversation history')
                store = load_settings_store()
                globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
                display_limit = normalize_display_history_context_max_chars(
                    globals_store.get('display_history_context_max_chars', DISPLAY_HISTORY_CONTEXT_MAX_CHARS)
                )
                use_direct_history_messages = (
                    mode_index == 0
                    and bool(globals_store.get('prefer_displayed_history_context', False))
                    and should_use_display_history_context(history_messages, max_chars=display_limit)
                )
                prompt_history_messages = build_budgeted_history_messages_for_prompt(
                    history_messages,
                    api_key,
                    endpoint,
                    model,
                    timeout,
                    max_messages=None if use_direct_history_messages else CONVERSATION_RECENT_MESSAGES,
                    total_max_chars=CONVERSATION_DIRECT_HISTORY_MAX_CHARS
                    if use_direct_history_messages else CONVERSATION_RECENT_MESSAGES_TOTAL_CHARS,
                ) if mode_index == 0 else []
                if not use_direct_history_messages:
                    history_context = owner._build_active_history_context(
                        question_text,
                        history_messages,
                        api_key,
                        endpoint,
                        model,
                        timeout,
                        selected_message_indices=selected_message_indices,
                        refresh_ui=False,
                        conversation_path=conversation_path,
                        include_recent_messages=mode_index != 0,
                    )
                    if history_context:
                        context_blocks.append(history_context)
            if not skip_retrieval_for_blank_prompt:
                progress('Preparing external context and MCP sources')
                external_context = owner._build_external_context_prompt_context(question_text, progress_callback=progress)
                if external_context:
                    context_blocks.append(external_context)
            if not skip_retrieval_for_blank_prompt and active_profile.get('remember_memory', True):
                progress('Retrieving saved memory')
                memory_context = owner._build_saved_memory_prompt_context(question_text)
                if memory_context:
                    context_blocks.append(memory_context)
            if not skip_retrieval_for_blank_prompt:
                vision_context = owner._build_background_vision_prompt_context()
                if vision_context:
                    context_blocks.append(vision_context)
            history = '\n\n'.join(block for block in context_blocks if block).strip()
            shared_context = '\n\n'.join(
                block for block in ([history, attachment_context] if attachment_context else [history]) if block
            ).strip()
            supplement_results = []

            def fold_supplements(stage: str) -> str:
                supplements = consume_supplements()
                if not supplements:
                    return ''
                block = build_agent_supplement_instruction_block(supplements, continuation=False)
                result = build_agent_supplement_step_result(supplements, stage=stage)
                if result:
                    supplement_results.append(result)
                progress(
                    'User added an instruction during generation'
                    + ('\n' + specialized_progress_snippet(block) if block else '')
                )
                return block

            initial_supplement_context = fold_supplements('before_planning')
            effective_shared_context = '\n\n'.join(
                block for block in [shared_context, initial_supplement_context] if str(block or '').strip()
            ).strip()
            effective_question_text = '\n\n'.join(
                block for block in [question_text, initial_supplement_context] if str(block or '').strip()
            ).strip()

            plan = {'steps': [], 'finalize_with_default_chat': False, 'reason': ''}
            step_results = []
            if bool(self.config.get('external_target_mode', False)):
                self.signals.finished.emit(
                    {
                        'cancelled': False,
                        'attachment_context': attachment_context,
                        'attachment_references': attachment_references,
                        'history': history,
                        'shared_context': effective_shared_context,
                        'prompt_history_messages': prompt_history_messages,
                        'plan': {
                            'steps': [],
                            'finalize_with_default_chat': False,
                            'reason': 'External @ target request; Broccoli planner skipped.',
                        },
                        'step_results': supplement_results,
                        'external_target_mode': True,
                        'external_target': dict(self.config.get('external_target') or {}),
                        'external_target_alias': str(self.config.get('external_target_alias', '') or ''),
                        'external_user_request': str(self.config.get('external_user_request', '') or question_text),
                    }
                )
                return
            if mode_index == 0 and not skip_retrieval_for_blank_prompt:
                planner_conversation_context = build_planner_recent_conversation_context(history_messages)
                try:
                    enabled_skill_count = len(load_skill_records_from_store(enabled_only=True))
                    progress(
                        'Planning specialized steps'
                        + (f'\nEnabled skills available: {enabled_skill_count}' if enabled_skill_count else '')
                    )
                    plan_update({
                        'type': 'phase',
                        'phase': 'planning',
                        'status': 'running',
                        'title': 'Planning specialized steps',
                    })
                    plan = owner._plan_specialized_request(
                        effective_question_text,
                        attachment_records,
                        planner_conversation_context,
                    )
                    run_id_for_steps = re.sub(r'[^a-zA-Z0-9_-]+', '-', str(self.config.get('run_id', '') or 'run')).strip('-') or 'run'
                    for step_index, planned_step in enumerate(plan.get('steps', []) or [], start=1):
                        if isinstance(planned_step, dict) and not str(planned_step.get('_plan_step_id', '') or '').strip():
                            planned_step['_plan_step_id'] = f'planner-{run_id_for_steps}-{step_index}'
                    plan_update({
                        'type': 'plan_ready',
                        'plan': plan,
                    })
                except Exception:
                    plan = {'steps': [], 'finalize_with_default_chat': False, 'reason': ''}
                    plan_update({
                        'type': 'phase',
                        'phase': 'planning',
                        'status': 'failed',
                        'title': 'Planner failed; using default chat',
                    })
                if self._stop_event.is_set():
                    self.signals.finished.emit({'cancelled': True})
                    return
                after_planning_supplement_context = fold_supplements('after_planning')
                if after_planning_supplement_context:
                    effective_shared_context = '\n\n'.join(
                        block for block in [effective_shared_context, after_planning_supplement_context]
                        if str(block or '').strip()
                    ).strip()
                    effective_question_text = '\n\n'.join(
                        block for block in [effective_question_text, after_planning_supplement_context]
                        if str(block or '').strip()
                    ).strip()
                if plan.get('steps'):
                    step_results = owner._execute_specialized_plan(
                        plan,
                        effective_question_text,
                        effective_shared_context,
                        history_messages,
                        retrieval_documents,
                        api_key,
                        endpoint,
                        model,
                        timeout,
                        selected_message_indices,
                        attachment_records,
                        conversation_path=conversation_path,
                        progress_callback=progress,
                        stop_event=self._stop_event,
                        supplement_provider=consume_supplements,
                        terminal_command_runner=self._run_terminal_command_request,
                        external_target_runner=self._run_external_target_request,
                        plan_update_callback=plan_update,
                        plan_control_provider=lambda step_id: owner._agent_plan_control_for_step(
                            str(self.config.get('run_id', '') or ''),
                            str(step_id or ''),
                        ),
                    )

            if self._stop_event.is_set():
                self.signals.finished.emit({'cancelled': True})
                return
            final_supplement_context = fold_supplements('before_final_answer')
            if final_supplement_context:
                effective_shared_context = '\n\n'.join(
                    block for block in [effective_shared_context, final_supplement_context]
                    if str(block or '').strip()
                ).strip()
            step_results = supplement_results + list(step_results or [])

            self.signals.finished.emit(
                {
                    'cancelled': False,
                    'attachment_context': attachment_context,
                    'attachment_references': attachment_references,
                    'history': history,
                    'shared_context': effective_shared_context,
                    'prompt_history_messages': prompt_history_messages,
                    'plan': plan,
                    'step_results': step_results,
                }
            )
        except Exception as exc:
            self.signals.failed.emit(str(exc))


class AsyncChatSignals(QObject):
    delta = pyqtSignal(str)
    status = pyqtSignal(str)
    tool_permission = pyqtSignal(object)
    terminal_command = pyqtSignal(object)
    finished = pyqtSignal(object)
    failed = pyqtSignal(str)


class ExternalTerminalTargetSignals(QObject):
    status = pyqtSignal(str)
    finished = pyqtSignal(object)
    failed = pyqtSignal(str)


class ExternalAnswerPostprocessSignals(QObject):
    finished = pyqtSignal(object)


def deterministic_external_answer_cleanup(text: str) -> str:
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not text:
        return ''
    text = re.sub(r'[ \t]+\n', '\n', text)
    text = re.sub(r'\n{3,}', '\n\n', text)
    text = re.sub(r'(?m)^(#{1,6})([^#\s])', r'\1 \2', text)
    text = re.sub(r'(?m)^([*-])([^\s])', r'\1 \2', text)
    text = re.sub(r'(?m)^(\d+\.)([^\s])', r'\1 \2', text)
    return text.strip()


def external_answer_postprocess_is_safe(raw_answer: str, cleaned_answer: str) -> tuple[bool, str]:
    raw = deterministic_external_answer_cleanup(raw_answer)
    cleaned = deterministic_external_answer_cleanup(cleaned_answer)
    if not cleaned:
        return False, 'empty_cleaned'
    lower = cleaned.lower()
    forbidden_patterns = [
        r'\bnot a software engineering task\b',
        r'\bcoding task\b',
        r'\bsoftware engineering task\b',
        r'\bdebugging, writing code, refactoring\b',
        r'\bi\s+(?:am|as)\s+claude code\b',
        r'\bas claude code\b',
        r'\bas codex\b',
        r'\bextracted answer text\b',
        r'\bexternal source\b',
        r'\bwhat would you like to do\?\s*$',
    ]
    for pattern in forbidden_patterns:
        if re.search(pattern, lower):
            return False, f'forbidden_postprocess_pattern:{pattern}'
    if raw:
        if len(cleaned) > max(len(raw) * 2.2, len(raw) + 1800):
            return False, 'cleaned_too_long'
        if len(cleaned) < max(40, len(raw) * 0.28) and len(raw) > 180:
            return False, 'cleaned_too_short'
        raw_tokens = set(re.findall(r'[\w\u3040-\u30ff\u3400-\u9fff]{2,}', raw.lower()))
        cleaned_tokens = set(re.findall(r'[\w\u3040-\u30ff\u3400-\u9fff]{2,}', cleaned.lower()))
        if len(raw_tokens) >= 8:
            overlap = len(raw_tokens & cleaned_tokens) / max(1, len(raw_tokens))
            if overlap < 0.42:
                return False, f'low_content_overlap:{overlap:.2f}'
    return True, 'safe'


class ExternalAnswerPostprocessThread(threading.Thread):
    def __init__(self, config: dict, signals: ExternalAnswerPostprocessSignals):
        super().__init__(daemon=True)
        self.config = dict(config or {})
        self.signals = signals

    def run(self):
        payload = dict(self.config.get('payload') or {})
        raw_answer = str(payload.get('answer', '') or '').strip()
        result = dict(payload)
        result['raw_answer'] = raw_answer
        result['postprocessed'] = True
        if not raw_answer:
            self.signals.finished.emit(result)
            return
        api_key = str(self.config.get('api_key', '') or '').strip()
        model = str(self.config.get('model', '') or '').strip()
        endpoint = str(self.config.get('endpoint', '') or '').strip()
        try:
            timeout = int(self.config.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        if not api_key or not model:
            result['answer'] = deterministic_external_answer_cleanup(raw_answer)
            result['postprocess_status'] = 'skipped_missing_api_profile'
            self.signals.finished.emit(result)
            return
        user_request = str(self.config.get('user_request', '') or '').strip()
        clipped = raw_answer
        clipped_notice = ''
        if len(clipped) > EXTERNAL_TARGET_POSTPROCESS_MAX_CHARS:
            clipped = clipped[:EXTERNAL_TARGET_POSTPROCESS_MAX_CHARS].rstrip()
            clipped_notice = (
                '\n\nNote: The raw text was truncated before format-only cleanup because it exceeded '
                f'{EXTERNAL_TARGET_POSTPROCESS_MAX_CHARS} characters. Preserve all visible content.'
            )
        messages = [
            {
                'role': 'system',
                'content': (
                    'You are a deterministic Markdown formatting filter. You are not an assistant in this conversation.\n'
                    'Your only job is to reformat the provided raw answer text into clean Markdown while preserving content.\n\n'
                    'Rules:\n'
                    '- Do not answer the user. Do not evaluate the request. Do not discuss whether the task is coding, factual, reliable, or verifiable.\n'
                    '- Do not add facts, remove facts from the actual answer, summarize, translate, change claims, or add warnings.\n'
                    '- Do not mention yourself, your model, Claude Code, Codex, external sources, extracted text, or raw text.\n'
                    '- Fix Markdown spacing, paragraph breaks, headings, lists, tables, code fences, and readable line breaks.\n'
                    '- Add concise Markdown headings only when they directly organize existing content; do not invent new sections or conclusions.\n'
                    '- Remove text that is clearly unrelated page UI chrome, navigation, selectable/history item labels, '
                    'duplicated widgets, source-card boilerplate, or copied webpage controls rather than part of the answer.\n'
                    '- Keep citations/source mentions when they are part of the answer. If uncertain whether a line is answer content, keep it.\n'
                    '- Return only the cleaned Markdown. If you cannot safely clean it, return the raw answer text unchanged.'
                ),
            },
            {
                'role': 'user',
                'content': (
                    'Context for formatting only. Do not mention this context in the output.\n'
                    + (f'User request context:\n{user_request}\n\n' if user_request else '')
                    + 'Text to format:\n<answer>\n'
                    + clipped
                    + '\n</answer>'
                    + clipped_notice
                ),
            },
        ]
        try:
            client = create_openai_client(api_key, endpoint, timeout)
            response = create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=messages,
                stream=False,
            )
            cleaned = str(response.choices[0].message.content or '').strip()
            if cleaned:
                safe, safe_reason = external_answer_postprocess_is_safe(raw_answer, cleaned)
                result['postprocess_safety'] = safe_reason
                if safe:
                    result['answer'] = deterministic_external_answer_cleanup(cleaned)
                    result['postprocess_status'] = 'cleaned'
                else:
                    result['answer'] = deterministic_external_answer_cleanup(raw_answer)
                    result['postprocess_status'] = f'rejected_fallback_raw:{safe_reason}'
            else:
                result['answer'] = deterministic_external_answer_cleanup(raw_answer)
                result['postprocess_status'] = 'empty_cleaned_fallback_raw'
        except Exception as exc:
            result['answer'] = deterministic_external_answer_cleanup(raw_answer)
            result['postprocess_status'] = f'failed_fallback_raw: {exc}'
        self.signals.finished.emit(result)


class ExternalTerminalTargetThread(threading.Thread):
    def __init__(self, config: dict, signals: ExternalTerminalTargetSignals):
        super().__init__(daemon=True)
        self.config = dict(config or {})
        self.signals = signals
        self._stop_event = threading.Event()
        self._process = None
        self._master_fd = None

    def request_stop(self):
        self._stop_event.set()
        try:
            if self._master_fd is not None:
                os.write(self._master_fd, b'\x03')
        except Exception:
            pass
        try:
            if self._process is not None and self._process.poll() is None:
                self._process.terminate()
        except Exception:
            pass

    def _set_pty_size(self, fd: int, cols: int = 120, rows: int = 40):
        try:
            fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', int(rows), int(cols), 0, 0))
        except Exception:
            pass

    def run(self):
        command = str(self.config.get('command', '') or '').strip()
        prompt = str(self.config.get('prompt', '') or '').strip()
        terminal_kind = str(self.config.get('terminal_kind', '') or '').strip().lower()
        if terminal_kind == 'claude_tui':
            terminal_kind = 'claude'
        resume_id = str(self.config.get('resume_id', '') or '').strip()
        transcript_path = str(self.config.get('transcript_path', '') or '').strip()
        user_request = str(self.config.get('user_request', '') or '').strip()
        timeout = max(30, int(self.config.get('timeout', 180) or 180))
        startup_delay = max(1.0, float(self.config.get('startup_delay', 3.0) or 3.0))
        idle_seconds = max(3.0, float(self.config.get('idle_seconds', 7.0) or 7.0))
        if not command:
            self.signals.failed.emit('No terminal command was configured for this target.')
            return
        if not prompt:
            self.signals.failed.emit('No prompt was provided for the terminal target.')
            return
        master_fd = slave_fd = None
        raw = bytearray()
        try:
            before_snapshot = agent_cli_session_snapshot(terminal_kind) if terminal_kind in ('codex', 'claude') else {}
            started_wall = time.time()
            master_fd, slave_fd = pty.openpty()
            self._master_fd = master_fd
            self._set_pty_size(master_fd, cols=120, rows=40)
            env = os.environ.copy()
            env['TERM'] = 'xterm-256color'
            env['COLUMNS'] = '120'
            env['LINES'] = '40'
            env['NO_COLOR'] = '1'
            env['CLICOLOR'] = '0'
            self.signals.status.emit('Starting terminal target...')
            self._process = subprocess.Popen(
                command,
                shell=True,
                stdin=slave_fd,
                stdout=slave_fd,
                stderr=slave_fd,
                cwd=str(self.config.get('cwd', '') or Path.home()),
                env=env,
                preexec_fn=os.setsid if hasattr(os, 'setsid') else None,
            )
            try:
                os.close(slave_fd)
            except Exception:
                pass
            slave_fd = None
            try:
                flags = fcntl.fcntl(master_fd, fcntl.F_GETFL)
                fcntl.fcntl(master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)
            except Exception:
                pass
            started = time.monotonic()
            last_output = time.monotonic()
            prompt_sent = False
            saw_post_prompt_output = False
            last_status = 0.0
            while not self._stop_event.is_set():
                now = time.monotonic()
                if now - started > timeout:
                    self.signals.failed.emit('Terminal target timed out before producing a stable answer.')
                    return
                if not prompt_sent and now - started >= startup_delay:
                    self.signals.status.emit('Sending prompt to terminal target...')
                    os.write(master_fd, (prompt + '\r').encode('utf-8', errors='replace'))
                    prompt_sent = True
                    last_output = now
                try:
                    ready, _, _ = select.select([master_fd], [], [], 0.2)
                except Exception:
                    ready = []
                if ready:
                    while True:
                        try:
                            chunk = os.read(master_fd, 8192)
                        except BlockingIOError:
                            break
                        except OSError:
                            chunk = b''
                            break
                        if not chunk:
                            break
                        raw.extend(chunk)
                        if len(raw) > 512000:
                            del raw[:-512000]
                        last_output = time.monotonic()
                        if prompt_sent and time.monotonic() - started > startup_delay + 1.0:
                            saw_post_prompt_output = True
                    continue
                if prompt_sent and saw_post_prompt_output and now - last_output >= idle_seconds:
                    break
                if self._process is not None and self._process.poll() is not None and now - last_output > 1.0:
                    break
                if now - last_status > 5:
                    last_status = now
                    self.signals.status.emit('Waiting for terminal target output...')
            if self._stop_event.is_set():
                self.signals.failed.emit('Terminal target was stopped.')
                return
            raw_text = raw.decode('utf-8', errors='replace')
            answer = clean_external_terminal_answer(raw_text, prompt, command)
            if not answer:
                answer = strip_terminal_ansi_text(raw_text).strip()
            locator = {}
            if terminal_kind in ('codex', 'claude'):
                try:
                    locator = locate_agent_cli_session_after_run(
                        terminal_kind,
                        before_snapshot,
                        prompt=prompt,
                        user_request=user_request,
                        resume_id=resume_id,
                        transcript_path=transcript_path,
                        started_at=started_wall,
                    )
                except Exception as exc:
                    locator = {'accepted': False, 'reason': f'locator_failed:{exc}', 'kind': terminal_kind}
                if bool(locator.get('accepted')):
                    resume_id = str(locator.get('resume_id', '') or resume_id)
                    transcript_path = str(locator.get('transcript_path', '') or transcript_path)
            self.signals.finished.emit({
                'answer': answer,
                'raw_output': raw_text,
                'resume_id': resume_id,
                'transcript_path': transcript_path,
                'terminal_kind': terminal_kind,
                'terminal_locator': locator,
            })
        except Exception as exc:
            self.signals.failed.emit(str(exc))
        finally:
            try:
                if self._process is not None and self._process.poll() is None:
                    self._process.terminate()
                    try:
                        self._process.wait(timeout=2)
                    except Exception:
                        self._process.kill()
            except Exception:
                pass
            for fd in (slave_fd, master_fd):
                if fd is not None:
                    try:
                        os.close(fd)
                    except Exception:
                        pass


class AsyncChatThread(threading.Thread):
    def __init__(self, config: dict, signals: AsyncChatSignals):
        super().__init__(daemon=True)
        self.config  = config
        self.signals = signals
        self._stop_event = threading.Event()

    def request_stop(self):
        self._stop_event.set()

    def _consume_supplement_instruction(self, *, continuation: bool = False) -> str:
        provider = self.config.get('supplement_provider')
        if not callable(provider):
            return ''
        try:
            supplements = normalize_agent_supplement_records(provider() or [])
        except Exception:
            supplements = []
        block = build_agent_supplement_instruction_block(supplements, continuation=continuation)
        if block:
            self.signals.status.emit('Applying user-added instruction')
        return block

    def _stream_completion(self, client, messages: list[dict]) -> tuple[str, str, list[str]]:
        chunks = []
        finish_reason = ''
        citation_urls = []
        response_stream = create_chat_completion(
            client,
            endpoint=self.config.get('endpoint', ''),
            model=self.config['model'],
            messages=messages,
            stream=True,
        )
        for response in response_stream:
            if self._stop_event.is_set():
                return ''.join(chunks), 'stopped', citation_urls
            if not getattr(response, 'choices', None):
                for url in extract_perplexity_citation_urls(getattr(response, 'citations', None)):
                    if url not in citation_urls:
                        citation_urls.append(url)
                continue
            choice = response.choices[0]
            delta = getattr(choice.delta, 'content', None)
            if delta:
                chunks.append(delta)
                self.signals.delta.emit(delta)
            if getattr(choice, 'finish_reason', None):
                finish_reason = choice.finish_reason
            # Perplexity streams can expose provider-specific citations on the
            # stream chunks; keep this isolated to the Perplexity path instead
            # of assuming generic OpenAI-compatible behavior.
            for url in extract_perplexity_citation_urls(getattr(response, 'citations', None)):
                if url not in citation_urls:
                    citation_urls.append(url)
        return ''.join(chunks), finish_reason, citation_urls

    def _summarize_answer_excerpt(self, client, existing_summary: str, excerpt: str) -> str:
        excerpt = str(excerpt or '').strip()
        if not excerpt:
            return existing_summary
        messages = [
            {
                'role': 'system',
                'content': (
                    'You compress already-written assistant output into compact continuation memory. '
                    'Preserve facts, numbering progress, code context, unresolved steps, and structural '
                    'state needed to continue seamlessly. Do not add new content.'
                ),
            },
            {
                'role': 'user',
                'content': (
                    ('Existing continuation memory:\n' + existing_summary + '\n\n') if existing_summary else ''
                ) + 'New excerpt to fold into continuation memory:\n' + excerpt + '\n\n'
                    'Return only the updated continuation memory.'
            },
        ]
        try:
            response = create_chat_completion(
                client,
                endpoint=self.config.get('endpoint', ''),
                model=self.config['model'],
                messages=messages,
                stream=False,
            )
            candidate = (response.choices[0].message.content or '').strip()
            return candidate or existing_summary
        except Exception:
            if existing_summary:
                merged = (existing_summary + '\n' + excerpt[-1200:]).strip()
                return merged[-4000:]
            return excerpt[-1800:]

    def _build_continuation_messages(self, base_messages: list[dict], answer_summary: str, answer_tail: str) -> list[dict]:
        continuation_messages = clone_messages_as_text(base_messages)
        prompt_parts = [
            'Continue your previous answer to the same request.',
        ]
        if answer_summary.strip():
            prompt_parts.append('Compressed memory of the earlier part of your answer:\n' + answer_summary.strip())
        if answer_tail.strip():
            prompt_parts.append('Recent exact tail of your answer:\n' + answer_tail.strip())
        prompt_parts.append(
            'Continue from exactly where the answer stopped. Do not repeat prior text. '
            'Preserve the same language, tone, formatting, numbering, and code fences. '
            'Output only the continuation text.'
        )
        continuation_messages.append({'role': 'user', 'content': '\n\n'.join(prompt_parts)})
        return continuation_messages

    def _request_mcp_tool_permission(self, tool_meta: dict, arguments: dict) -> bool:
        permission_key = f"{tool_meta.get('source', {}).get('id', '')}:{tool_meta.get('tool_name', '')}"
        allowlist = self.config.setdefault('mcp_conversation_allowlist', set())
        if permission_key in allowlist:
            return True
        needs_confirmation = (not bool(tool_meta.get('read_only', True))) or bool(tool_meta.get('mutating', False))
        if not needs_confirmation:
            return True
        request = {
            'run_id': str(self.config.get('run_id', '') or ''),
            'conversation_path': str(self.config.get('conversation_path', '') or ''),
            'source_name': tool_meta.get('source_name', 'MCP source'),
            'tool_name': tool_meta.get('tool_name', ''),
            'arguments': arguments,
            'mutating': bool(tool_meta.get('mutating', False)),
            'read_only': bool(tool_meta.get('read_only', True)),
            'permission_key': permission_key,
            'decision': 'deny',
            'event': threading.Event(),
        }
        self.signals.tool_permission.emit(request)
        if not request['event'].wait(300):
            return False
        decision = str(request.get('decision', 'deny') or 'deny')
        if decision == 'always':
            allowlist.add(permission_key)
            return True
        return decision == 'allow'

    def _request_terminal_command(self, arguments: dict) -> dict:
        request = build_agent_terminal_command_request(
            arguments,
            run_id=str(self.config.get('run_id', '') or ''),
            conversation_path=str(self.config.get('conversation_path', '') or ''),
        )
        request['event'] = threading.Event()
        request['result'] = None
        self.signals.terminal_command.emit(request)
        approval_window = (
            AGENT_TERMINAL_READ_DEFAULT_ALLOW_SECONDS
            if request.get('read_only', True)
            else AGENT_TERMINAL_WRITE_DEFAULT_DENY_SECONDS
        )
        timeout_seconds = int(request.get('timeout_seconds', 120) or 120)
        if not request['event'].wait(max(30, approval_window + timeout_seconds + 30)):
            return {
                'status': 'timeout',
                'text': 'Terminal command request timed out before completion.',
                'command': str(request.get('command', '') or ''),
            }
        result = request.get('result')
        if isinstance(result, dict):
            return result
        return {
            'status': 'failed',
            'text': 'Terminal command returned no result.',
            'command': str(request.get('command', '') or ''),
        }

    def _run_completion_with_mcp_tools(self, client, messages: list[dict]) -> tuple[str, str]:
        sources = (self.config.get('mcp_sources') or []) if self.config.get('mcp_tool_runtime_enabled', False) else []
        self.signals.status.emit('Discovering enabled MCP and Terminal tools')
        tool_defs, tool_map = build_mcp_tool_runtime_bundle(sources)
        if bool(self.config.get('terminal_command_runtime_enabled', True)):
            terminal_tool_name = 'broccoli_terminal_run_command'
            tool_defs.append(
                {
                    'type': 'function',
                    'function': {
                        'name': terminal_tool_name,
                        'description': (
                            'Run a local shell command visibly in Broccoli Terminal after user approval. '
                            'Use this for reading or searching local files, project inspection, AppleScript/osascript, '
                            'or controlled local file operations. Do not use it for ordinary math or prose. '
                            'Write purpose, expected_result, and any explanatory fields in English. '
                            'Keep command and target_paths exact and untranslated.'
                        ),
                        'parameters': {
                            'type': 'object',
                            'properties': {
                                'command': {
                                    'type': 'string',
                                    'description': 'The exact shell command to run.',
                                },
                                'purpose': {
                                    'type': 'string',
                                    'description': 'Briefly explain in English why this command is needed.',
                                },
                                'expected_result': {
                                    'type': 'string',
                                    'description': 'Explain in English what information or result should come back.',
                                },
                                'risk': {
                                    'type': 'string',
                                    'enum': ['read', 'write', 'dangerous', 'unknown'],
                                    'description': 'Declare whether the command only reads, mutates files/state, is dangerous, or is unknown.',
                                },
                                'target_paths': {
                                    'type': 'array',
                                    'items': {'type': 'string'},
                                    'description': 'Explicit files or folders that may be modified, for backup before mutating commands.',
                                },
                                'timeout_seconds': {
                                    'type': 'integer',
                                    'description': 'Execution timeout in seconds, usually 30-180.',
                                },
                            },
                            'required': ['command', 'purpose', 'expected_result'],
                            'additionalProperties': False,
                        },
                    },
                }
            )
            tool_map[terminal_tool_name] = {
                'runtime': 'terminal_command',
                'tool_name': terminal_tool_name,
                'source_name': 'Broccoli Terminal',
                'read_only': False,
                'mutating': True,
            }
        if not tool_defs:
            return '', 'no_tools'
        current_messages = clone_messages_as_text(messages)
        finish_reason = ''
        for round_index in range(MCP_TOOL_RUNTIME_MAX_ROUNDS):
            supplement_block = self._consume_supplement_instruction(continuation=False)
            if supplement_block:
                current_messages.append({'role': 'user', 'content': supplement_block})
            self.signals.status.emit(f'Asking model to choose tools, round {round_index + 1}')
            response = create_chat_completion(
                client,
                endpoint=self.config.get('endpoint', ''),
                model=self.config['model'],
                messages=current_messages,
                tools=tool_defs,
                tool_choice='auto',
                stream=False,
            )
            choice = response.choices[0]
            message = choice.message
            finish_reason = getattr(choice, 'finish_reason', '') or ''
            tool_calls = getattr(message, 'tool_calls', None) or []
            if not tool_calls:
                return message.content or '', finish_reason
            assistant_message = {
                'role': 'assistant',
                'content': message.content or '',
                'tool_calls': [],
            }
            for tool_call in tool_calls:
                function = getattr(tool_call, 'function', None)
                function_name = getattr(function, 'name', '') if function is not None else ''
                arguments_text = getattr(function, 'arguments', '{}') if function is not None else '{}'
                assistant_message['tool_calls'].append(
                    {
                        'id': getattr(tool_call, 'id', ''),
                        'type': 'function',
                        'function': {
                            'name': function_name,
                            'arguments': arguments_text or '{}',
                        },
                    }
                )
            current_messages.append(assistant_message)
            for tool_call in tool_calls:
                function = getattr(tool_call, 'function', None)
                function_name = getattr(function, 'name', '') if function is not None else ''
                arguments_text = getattr(function, 'arguments', '{}') if function is not None else '{}'
                tool_meta = tool_map.get(function_name)
                try:
                    arguments = json.loads(arguments_text or '{}')
                    if not isinstance(arguments, dict):
                        arguments = {}
                except Exception:
                    arguments = {}
                if tool_meta is None:
                    result_text = f'MCP tool is unavailable: {function_name}'
                elif tool_meta.get('runtime') == 'terminal_command':
                    self.signals.status.emit('Requesting Terminal command approval')
                    result = self._request_terminal_command(arguments)
                    result_text = str(result.get('text', '') or '')
                    if not result_text:
                        result_text = _agent_terminal_result_text(str(result.get('output', '') or ''))
                elif self._request_mcp_tool_permission(tool_meta, arguments):
                    try:
                        self.signals.status.emit(
                            f"Calling {tool_meta.get('source_name', 'MCP source')} / {tool_meta.get('tool_name', '')}"
                        )
                        result = call_mcp_source_tool(tool_meta['source'], tool_meta['tool_name'], arguments)
                        result_text = _mcp_tool_result_to_text(result)
                    except Exception as exc:
                        result_text = f'MCP tool call failed: {exc}'
                else:
                    result_text = 'MCP tool call was denied by the user.'
                current_messages.append(
                    {
                        'role': 'tool',
                        'tool_call_id': getattr(tool_call, 'id', ''),
                        'content': (result_text or '')[:MCP_TOOL_RUNTIME_RESULT_CHARS],
                    }
                )
        self.signals.status.emit('Finishing answer from MCP tool results')
        supplement_block = self._consume_supplement_instruction(continuation=False)
        if supplement_block:
            current_messages.append({'role': 'user', 'content': supplement_block})
        response = create_chat_completion(
            client,
            endpoint=self.config.get('endpoint', ''),
            model=self.config['model'],
            messages=current_messages + [
                {
                    'role': 'user',
                    'content': 'Finish the answer using the tool results already provided. Do not call more tools.',
                }
            ],
            stream=False,
        )
        return response.choices[0].message.content or '', getattr(response.choices[0], 'finish_reason', '') or finish_reason

    def run(self):
        try:
            timeout = self.config.get('timeout', 60)
            client = OpenAI(
                api_key=self.config['api_key'],
                base_url=self.config['endpoint'],
                timeout=timeout,
            )
            base_messages = clone_messages_as_text(self.config['messages'])
            references = ''

            messages = clone_messages_as_text(base_messages)

            # Inject attachment content into the last user message (multimodal)
            attachments = self.config.get('attachments', [])
            if attachments:
                # Work on a shallow copy of the list so we don't mutate config
                messages = list(messages)
                for i in range(len(messages) - 1, -1, -1):
                    if messages[i]['role'] == 'user':
                        original_content = messages[i]['content']
                        # Build a multimodal content list.
                        # Each attachment is either a single dict or a list of
                        # dicts (multi-page PDF → one entry per page).
                        content_list: list = [{"type": "text", "text": original_content}]
                        for att_or_list in attachments:
                            items = att_or_list if isinstance(att_or_list, list) else [att_or_list]
                            for att in items:
                                if att['kind'] == 'image':
                                    content_list.append({
                                        "type": "image_url",
                                        "image_url": {
                                            "url": f"data:{att['mime']};base64,{att['b64']}"
                                        },
                                    })
                                else:
                                    content_list.append({
                                        "type": "text",
                                        "text": (
                                            f"\n\n[Attached file: {att['name']}]\n"
                                            f"{att['content']}"
                                        ),
                                    })
                        messages[i] = dict(messages[i])
                        messages[i]['content'] = content_list
                        break
            supplement_block = self._consume_supplement_instruction(continuation=False)
            if supplement_block:
                messages.append({'role': 'user', 'content': supplement_block})

            if (
                (
                    self.config.get('mcp_tool_runtime_enabled', False)
                    or self.config.get('terminal_command_runtime_enabled', False)
                )
                and int(self.config.get('mode_index', 0) or 0) == 0
            ):
                try:
                    answer_text, finish_reason = self._run_completion_with_mcp_tools(client, messages)
                    if finish_reason != 'no_tools':
                        self.signals.delta.emit(answer_text)
                        self.signals.finished.emit(
                            {
                                'answer': answer_text,
                                'references': references,
                                'finish_reason': finish_reason,
                                'mcp_tools_used': True,
                            }
                        )
                        return
                except Exception:
                    pass

            if self.config.get('stream', True):
                answer_segments = []
                answer_summary = ''
                live_tail = ''
                finish_reason = ''
                continuation_passes = 0
                current_messages = messages
                all_citation_urls = []

                while not self._stop_event.is_set():
                    segment_text, finish_reason, citation_urls = self._stream_completion(client, current_messages)
                    answer_segments.append(segment_text)
                    live_tail += segment_text
                    for url in citation_urls:
                        if url not in all_citation_urls:
                            all_citation_urls.append(url)

                    if finish_reason != 'length':
                        break

                    continuation_passes += 1
                    if continuation_passes >= CONTINUATION_MAX_PASSES:
                        break

                    if len(live_tail) > CONTINUATION_TAIL_CHARS:
                        excerpt_to_compress = live_tail[:-CONTINUATION_TAIL_CHARS]
                        live_tail = live_tail[-CONTINUATION_TAIL_CHARS:]
                        answer_summary = self._summarize_answer_excerpt(client, answer_summary, excerpt_to_compress)

                    current_messages = self._build_continuation_messages(base_messages, answer_summary, live_tail)
                    supplement_block = self._consume_supplement_instruction(continuation=False)
                    if supplement_block:
                        current_messages.append({'role': 'user', 'content': supplement_block})

                # Only emit finished if we weren't stopped — StopX already
                # called on_async_chat_finished directly on the main thread.
                if not self._stop_event.is_set():
                    answer_text = ''.join(answer_segments)
                    if is_perplexity_endpoint(self.config.get('endpoint', '')):
                        citations_block = format_perplexity_citations_block(all_citation_urls)
                        if citations_block:
                            answer_text = answer_text + ('\n\n' if answer_text else '') + citations_block
                    self.signals.finished.emit(
                        {
                            'answer': answer_text,
                            'references': references,
                            'finish_reason': finish_reason,
                            'continuation_passes': continuation_passes,
                        }
                    )
                return

            response = create_chat_completion(
                client,
                endpoint=self.config.get('endpoint', ''),
                model=self.config['model'],
                messages=messages,
                stream=False,
            )
            answer_text = response.choices[0].message.content or ''
            # Perplexity exposes citations on its chat-compatible responses, but
            # the field is provider-specific rather than OpenAI-standard.
            if is_perplexity_endpoint(self.config.get('endpoint', '')):
                citations_block = format_perplexity_citations_block(getattr(response, 'citations', None))
                if citations_block:
                    answer_text = answer_text + ('\n\n' if answer_text else '') + citations_block
            self.signals.finished.emit(
                {
                    'answer': answer_text,
                    'references': references,
                    'finish_reason': getattr(response.choices[0], 'finish_reason', ''),
                }
            )
        except Exception as exc:
            self.signals.failed.emit(str(exc))


class BrowserUseSignals(QObject):
    status = pyqtSignal(str)
    finished = pyqtSignal(object)
    failed = pyqtSignal(str)


def browser_use_worker_command() -> list[str]:
    if getattr(sys, 'frozen', False):
        worker_path = Path(sys.executable).with_name('BroccoliBrowserUseWorker')
        if sys.platform == 'win32':
            worker_path = worker_path.with_suffix('.exe')
        if not worker_path.exists():
            raise RuntimeError(f'Browser Use helper executable not found: {worker_path}')
        return [str(worker_path)]
    worker_path = Path(__file__).resolve().with_name('browser_use_worker.py')
    if not worker_path.exists():
        raise RuntimeError(f'Browser Use helper script not found: {worker_path}')
    return [sys.executable, '-X', 'faulthandler', str(worker_path)]


class BrowserUseThread(threading.Thread):
    def __init__(self, config: dict, signals: BrowserUseSignals | None = None):
        super().__init__(daemon=True)
        self.config = config
        self.signals = signals
        self._stop_event = threading.Event()
        self._process = None
        cancel_name = f'browser_use_{int(time.time() * 1000)}_{id(self)}.stop'
        self._cancel_path = os.path.join(BROCCOLI_APP_DATA_DIR, 'BrowserUseCancel', cancel_name)

    def _write_cancel_token(self):
        try:
            os.makedirs(os.path.dirname(self._cancel_path), exist_ok=True)
            with open(self._cancel_path, 'w', encoding='utf-8') as handle:
                handle.write('stop\n')
        except Exception:
            pass

    def _cleanup_cancel_token(self):
        try:
            if self._cancel_path and os.path.exists(self._cancel_path):
                os.remove(self._cancel_path)
        except Exception:
            pass

    def _terminate_process_async(self):
        process = self._process
        if process is None:
            return

        def terminate():
            try:
                if process.poll() is not None:
                    return
                try:
                    process.wait(timeout=1.5)
                    return
                except subprocess.TimeoutExpired:
                    pass
                if sys.platform != 'win32':
                    try:
                        os.killpg(os.getpgid(process.pid), signal.SIGTERM)
                    except Exception:
                        process.terminate()
                else:
                    process.terminate()
                try:
                    process.wait(timeout=1.5)
                    return
                except subprocess.TimeoutExpired:
                    pass
                if sys.platform != 'win32':
                    try:
                        os.killpg(os.getpgid(process.pid), signal.SIGKILL)
                    except Exception:
                        process.kill()
                else:
                    process.kill()
            except Exception:
                pass

        threading.Thread(target=terminate, daemon=True).start()

    def request_stop(self):
        self._stop_event.set()
        self._write_cancel_token()
        self._terminate_process_async()

    def run_blocking(self) -> dict:
        task = str(self.config.get('task', '') or '').strip()
        if not task:
            raise RuntimeError('Browser Use task is empty.')
        if self._stop_event.is_set():
            return {'cancelled': True, 'answer': 'Browser Use task was stopped before it started.'}
        env = os.environ.copy()
        env.setdefault('BROWSER_USE_CONFIG_DIR', os.path.join(BROCCOLI_APP_DATA_DIR, 'BrowserUseConfig'))
        os.makedirs(env['BROWSER_USE_CONFIG_DIR'], exist_ok=True)
        worker_config = dict(self.config)
        worker_config['cancel_path'] = self._cancel_path
        popen_kwargs = {
            'stdin': subprocess.PIPE,
            'stdout': subprocess.PIPE,
            'stderr': subprocess.PIPE,
            'text': True,
            'env': env,
        }
        if sys.platform == 'win32':
            popen_kwargs['creationflags'] = getattr(subprocess, 'CREATE_NEW_PROCESS_GROUP', 0)
        else:
            popen_kwargs['start_new_session'] = True
        try:
            self._process = subprocess.Popen(browser_use_worker_command(), **popen_kwargs)
            stdout, stderr = self._process.communicate(json.dumps(worker_config, ensure_ascii=False))
            if self._stop_event.is_set():
                return {'cancelled': True, 'answer': 'Browser Use task was stopped.'}
        finally:
            self._cleanup_cancel_token()
        result = None
        prefix = '__BROCCOLI_BROWSER_USE_RESULT__'
        for line in reversed((stdout or '').splitlines()):
            if line.startswith(prefix):
                try:
                    result = json.loads(line[len(prefix):])
                except Exception:
                    result = None
                break
        if isinstance(result, dict) and result.get('ok'):
            return result
        if isinstance(result, dict):
            error = str(result.get('error', '') or 'Browser Use failed.')
            trace = str(result.get('traceback', '') or '').strip()
            raise RuntimeError(error + (('\n\n' + trace) if trace else ''))
        detail = str(stderr or stdout or '').strip()
        code = self._process.returncode
        raise RuntimeError(detail or f'Browser Use worker exited with code {code}.')

    def run(self):
        try:
            if self.signals is not None:
                self.signals.status.emit('Starting Browser Use worker')
            result = self.run_blocking()
            if self.signals is not None:
                self.signals.finished.emit(result)
        except Exception as exc:
            if self.signals is not None:
                self.signals.failed.emit(str(exc))

