        # Match text1.MIN_H so both pills drive the bar to the same 40 px height
        _left_content.setMinimumHeight(self.text1.MIN_H)

        # ── Right pill: left hover stack (Transfer / Save / Share) ─
        self._bar_transfer_btn = AssistantCapsuleButton('♻️ Transfer', self)
        self._bar_transfer_btn.clicked.connect(self.transferview)
        _left_hover = AssistantHoverStack(
            main_btn=self._bar_transfer_btn,
            above_specs=[
                ('🔻 Save', self.ExportX),   # closest above
                ('🔺 Share', self.ShareX),            # topmost
                ('📸 Shot', self.start_region_capture),
                ('🏷️ Tag', self.open_current_agent_conversation_badge),
            ],
        )

        # ── Right pill: right hover stack (Send / Again / Clear) ──
        _right_hover = AssistantHoverStack(
            main_btn=self.btn_sub1,
            above_specs=[
                ('➕ Add note', self.AddAgentSupplementX),
                ('🧾 Queue', self.QueueAgentPromptX),
                ('🔹 Again', self.AgainX),
                ('🔸 New', self.ClearX),
            ],
        )

        button_width = max(
            self._bar_transfer_btn.sizeHint().width(),
            self.btn_sub1.sizeHint().width(),
            self._bar_transfer_btn.fontMetrics().horizontalAdvance('♻️ Transfer') + 36,
            self.btn_sub1.fontMetrics().horizontalAdvance('🔺 Send') + 36,
            self.btn_sub1.fontMetrics().horizontalAdvance('⛔️ Stop') + 36,
        )
        self._bar_transfer_btn.setFixedWidth(button_width)
        self.btn_sub1.setFixedWidth(button_width)
        _left_hover.setFixedWidth(button_width)
        _right_hover.setFixedWidth(button_width)

        # ── Right pill content: [left_hover | text1 | right_hover] ─
        _right_content = QWidget()
        _right_content.setMinimumHeight(self.text1.MIN_H)
        _right_content_lay = QHBoxLayout(_right_content)
        _right_content_lay.setContentsMargins(0, 0, 0, 0)
        _right_content_lay.setSpacing(8)
        _right_content_lay.addWidget(_left_hover)
        _right_content_lay.addWidget(self.text1, 1, Qt.AlignmentFlag.AlignVCenter)
        _right_content_lay.addWidget(_right_hover)

