        ap_layout.addWidget(self.real1)
        # Attachment tray — zero-height by default; slides in via animation
        self._attachment_tray = AttachmentTray()
        _tray_wrap = QWidget()
        _tray_wrap.setMaximumHeight(0)   # hidden via height, not visibility
        self._attachment_tray_wrap = _tray_wrap
        _tray_wl = QHBoxLayout(_tray_wrap)
        _tray_wl.setContentsMargins(4, 4, 4, 4)
        _tray_wl.setSpacing(0)
        _tray_wl.addWidget(self._attachment_tray, 1)
        ap_layout.addWidget(_tray_wrap)
        ap_layout.addWidget(self._assistant_bar)
        # Drag/drop is handled at the MyWidget window level (see dragEnterEvent etc.)
        # No signals from assistant_page needed — kept for potential future use.
        # Tray slide animation (animates maximumHeight of the wrapper)
        _TRAY_WRAP_H = AttachmentTray.TRAY_H + 8   # TRAY_H + _tray_wl top/bottom margins
        self._TRAY_WRAP_H = _TRAY_WRAP_H
        # Animates maximumHeight; valueChanged also pins minimumHeight to the same
        # value — this is equivalent to setFixedHeight() each frame and FORCES the
        # layout to shrink real2/real1 rather than just capping the tray size.
        self._tray_anim = QPropertyAnimation(self._attachment_tray_wrap, b'maximumHeight', self)
        self._tray_anim.setDuration(220)
        self._tray_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._tray_anim.valueChanged.connect(self._attachment_tray_wrap.setMinimumHeight)
        # Auto-hide when tray reports it became empty
        self._attachment_tray.became_empty.connect(self._hide_tray_animated)

