    def _set_prompt_edit_read_only(self, enabled: bool):
        self.text1.setReadOnly(bool(enabled))
        if hasattr(self, '_text1_popup'):
            self._text1_popup.edit.setReadOnly(bool(enabled))

    def _clear_and_hide_agent_prompt_after_send(self):
        self._set_prompt_edit_read_only(False)
        self._prompt_syncing = True
        blockers = []
        try:
            blockers.append(QSignalBlocker(self.text1))
            self.text1.clear()
            if hasattr(self, '_text1_popup'):
                blockers.append(QSignalBlocker(self._text1_popup.edit))
                self._text1_popup.edit.clear()
        finally:
            blockers.clear()
            self._prompt_syncing = False
        try:
            self.text1._emit_multiline_if_needed()
        except Exception:
            pass
        if hasattr(self, '_text1_popup'):
            self._text1_popup.hide()
        if hasattr(self, '_slash_command_popup'):
            self._slash_command_popup.hide()
        if hasattr(self, '_mention_target_popup'):
            self._mention_target_popup.hide()
        self._refresh_text1_popup_visibility()
        self._update_send_shortcut_enabled()

    def _clear_agent_prompt_if_unchanged(self, sent_text: str):
        if str(self.text1.toPlainText() or '') != str(sent_text or ''):
            return
        self._clear_and_hide_agent_prompt_after_send()

    def _install_selection_context_menus(self):
        if not hasattr(self, '_selection_context_widgets'):
            self._selection_context_widgets = set()
        widgets = []
        for name in ('real1', 'real2'):
            widget = getattr(self, name, None)
            if widget is not None:
                widgets.append(widget)
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None:
            for widget in (getattr(terminal, 'output', None), getattr(terminal, 'input_line', None)):
                if widget is not None:
                    widgets.append(widget)
        for panel_name in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, panel_name, None)
            for view in list(getattr(panel, '_views', []) or []):
                if view is not None:
                    widgets.append(view)
        for widget in widgets:
            ident = id(widget)
            if ident in self._selection_context_widgets:
                continue
            try:
                if isinstance(widget, QWebEngineView):
                    widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
                    widget.customContextMenuRequested.connect(
                        lambda pos, w=widget: self._handle_selection_context_menu_at(w, w.mapToGlobal(pos))
                    )
                    self._selection_context_widgets.add(ident)
                    continue
                if self._is_terminal_selection_context_widget(widget):
                    widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
                    widget.customContextMenuRequested.connect(
                        lambda pos, w=widget: self._handle_selection_context_menu_at(w, w.mapToGlobal(pos))
                    )
                    self._selection_context_widgets.add(ident)
                    continue
                widget.installEventFilter(self)
                self._selection_context_widgets.add(ident)
            except Exception:
                pass

    def eventFilter(self, obj, event):
        slash_popup = getattr(self, '_slash_command_popup', None)
        mention_popup = getattr(self, '_mention_target_popup', None)
        if obj is getattr(self, 'text1', None) and event.type() == QEvent.Type.KeyPress:
            if mention_popup is not None and mention_popup.isVisible():
                key = event.key()
                if key in (Qt.Key.Key_Down, Qt.Key.Key_Up):
                    count = mention_popup.list_widget.count()
                    if count:
                        row = mention_popup.list_widget.currentRow()
                        delta = 1 if key == Qt.Key.Key_Down else -1
                        mention_popup.list_widget.setCurrentRow(max(0, min(count - 1, row + delta)))
                    return True
                if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                    command = mention_popup.current_command()
                    if command:
                        self._insert_mention_target(command)
                        return True
                if key == Qt.Key.Key_Escape:
                    mention_popup.hide()
                    return True
            if slash_popup is not None and slash_popup.isVisible():
                key = event.key()
                if key in (Qt.Key.Key_Down, Qt.Key.Key_Up):
                    count = slash_popup.list_widget.count()
                    if count:
                        row = slash_popup.list_widget.currentRow()
                        delta = 1 if key == Qt.Key.Key_Down else -1
                        slash_popup.list_widget.setCurrentRow(max(0, min(count - 1, row + delta)))
                    return True
                if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                    command = slash_popup.current_command()
                    if command:
                        self._insert_slash_command(command)
                        return True
                if key == Qt.Key.Key_Escape:
                    slash_popup.hide()
                    return True
        if slash_popup is not None and obj is slash_popup.list_widget and event.type() == QEvent.Type.KeyPress:
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                command = slash_popup.current_command()
                if command:
                    self._insert_slash_command(command)
                    return True
            if event.key() == Qt.Key.Key_Escape:
                slash_popup.hide()
                self.text1.setFocus()
                return True
        if isinstance(obj, QWebEngineView):
            return False
        if event.type() == QEvent.Type.ContextMenu and self._is_selection_context_widget(obj):
            if self._handle_selection_context_menu(obj, event):
                return True
        return super().eventFilter(obj, event)

    def _current_slash_query(self) -> str:
        text = self.text1.toPlainText()
        cursor_pos = self.text1.textCursor().position()
        before_cursor = text[:cursor_pos]
        line_start = before_cursor.rfind('\n') + 1
        current_line = before_cursor[line_start:]
        stripped = current_line.lstrip()
        if not stripped.startswith('/'):
            return ''
        return stripped

    def _refresh_slash_command_popup(self):
        popup = getattr(self, '_slash_command_popup', None)
        if popup is None:
            return
        query = self._current_slash_query()
        focus_widget = QApplication.focusWidget()
        focus_ok = focus_widget is self.text1 or focus_widget is popup.list_widget
        mention_visible = bool(getattr(getattr(self, '_mention_target_popup', None), 'isVisible', lambda: False)())
        if query and focus_ok and self.stacked_widget.currentIndex() == TAB_API and not mention_visible:
            popup.show_for_anchor(self.text1, query)
        else:
            popup.hide()

    def _insert_slash_command(self, command: str):
        command = str(command or '')
        if not command:
            return
        cursor = self.text1.textCursor()
        text = self.text1.toPlainText()
        pos = cursor.position()
        before = text[:pos]
        line_start = before.rfind('\n') + 1
        line_prefix = text[line_start:pos]
        slash_offset = len(line_prefix) - len(line_prefix.lstrip())
        replace_start = line_start + slash_offset
        cursor.setPosition(replace_start)
        cursor.setPosition(pos, QTextCursor.MoveMode.KeepAnchor)
        cursor.insertText(command)
        self.text1.setTextCursor(cursor)
        if getattr(self, '_slash_command_popup', None) is not None:
            self._slash_command_popup.hide()
        self.text1.setFocus()

    def _current_mention_query(self) -> str:
        text = self.text1.toPlainText()
        cursor_pos = self.text1.textCursor().position()
        before_cursor = text[:cursor_pos]
        line_start = before_cursor.rfind('\n') + 1
        token_start = max(line_start, before_cursor.rfind(' ') + 1, before_cursor.rfind('\t') + 1)
        token = before_cursor[token_start:]
        if not token.startswith('@'):
            return ''
        return token

    def _refresh_mention_target_popup(self):
        popup = getattr(self, '_mention_target_popup', None)
        if popup is None:
            return
        query = self._current_mention_query()
        focus_widget = QApplication.focusWidget()
        focus_ok = focus_widget is self.text1 or focus_widget is popup.list_widget
        if query and focus_ok and self.stacked_widget.currentIndex() == TAB_API:
            if getattr(self, '_slash_command_popup', None) is not None:
                self._slash_command_popup.hide()
            popup.show_for_anchor(self.text1, query)
        else:
            popup.hide()

    def _insert_mention_target(self, command: str):
        command = str(command or '')
        if not command:
            return
        cursor = self.text1.textCursor()
        text = self.text1.toPlainText()
        pos = cursor.position()
        before = text[:pos]
        line_start = before.rfind('\n') + 1
        token_start = max(line_start, before.rfind(' ') + 1, before.rfind('\t') + 1)
        cursor.setPosition(token_start)
        cursor.setPosition(pos, QTextCursor.MoveMode.KeepAnchor)
        cursor.insertText(command)
        self.text1.setTextCursor(cursor)
        if getattr(self, '_mention_target_popup', None) is not None:
            self._mention_target_popup.hide()
        self.text1.setFocus()

    def _selection_context_owner(self, obj):
        current = obj
        terminal = getattr(self, 'terminal_widget', None)
        terminal_output = getattr(terminal, 'output', None) if terminal is not None else None
        terminal_input = getattr(terminal, 'input_line', None) if terminal is not None else None
        while current is not None:
            if current in (getattr(self, 'real1', None), getattr(self, 'real2', None)):
                return current
            if current in (terminal_output, terminal_input):
                return current
            for panel_name in ('ai_web_panel', 'localhost_panel'):
                panel = getattr(self, panel_name, None)
                if current in list(getattr(panel, '_views', []) or []):
                    return current
            if isinstance(current, QWebEngineView):
                return current
            current = current.parentWidget() if hasattr(current, 'parentWidget') else None
        return obj

    def _is_selection_context_widget(self, obj) -> bool:
        owner = self._selection_context_owner(obj)
        if owner in (getattr(self, 'real1', None), getattr(self, 'real2', None)):
            return True
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None and owner in (getattr(terminal, 'output', None), getattr(terminal, 'input_line', None)):
            return True
        for panel_name in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, panel_name, None)
            if owner in list(getattr(panel, '_views', []) or []):
                return True
        return isinstance(owner, QWebEngineView)

    def _is_terminal_selection_context_widget(self, obj) -> bool:
        obj = self._selection_context_owner(obj)
        terminal = getattr(self, 'terminal_widget', None)
        return bool(terminal is not None and obj in (getattr(terminal, 'output', None), getattr(terminal, 'input_line', None)))

    def _selected_text_from_widget(self, obj) -> str:
        obj = self._selection_context_owner(obj)
        try:
            if isinstance(obj, QWebEngineView):
                return str(obj.page().selectedText() or '').strip()
        except Exception:
            return ''
        try:
            if isinstance(obj, QLineEdit):
                return str(obj.selectedText() or '').strip()
            if hasattr(obj, 'textCursor'):
                cursor = obj.textCursor()
                if cursor.hasSelection():
                    return cursor.selectedText().replace('\u2029', '\n').strip()
        except Exception:
            return ''
        return ''

    def _handle_selection_context_menu(self, obj, event) -> bool:
        return self._handle_selection_context_menu_at(obj, event.globalPos())

    def _handle_selection_context_menu_at(self, obj, global_pos) -> bool:
        obj = self._selection_context_owner(obj)
        selected_text = self._selected_text_from_widget(obj)
        if isinstance(obj, QWebEngineView):
            if not selected_text:
                return True
            menu = style_broccoli_context_menu(QMenu(self))
            copy_action = menu.addAction('Copy')
            copy_action.triggered.connect(
                lambda _checked=False, view=obj: view.page().triggerAction(QWebEnginePage.WebAction.Copy)
            )
        else:
            try:
                menu = style_broccoli_context_menu(obj.createStandardContextMenu())
            except Exception:
                menu = style_broccoli_context_menu(QMenu(self))
            if not selected_text:
                if menu is not None:
                    menu.exec(global_pos)
                    return True
                return False
        if menu.actions():
            menu.addSeparator()
        replace_menu = menu.addMenu('Replace prompt with selection')
        append_menu = menu.addMenu('Append selection to prompt')
        targets = [
            ('Agent', TAB_API),
            ('Web', TAB_WEB),
            ('Localhost', TAB_LOCALHOST),
            ('Terminal', TAB_TERMINAL),
        ]
        for label, target in targets:
            replace_action = replace_menu.addAction(label)
            replace_action.triggered.connect(
                lambda _checked=False, t=target, text=selected_text: self._route_selection_to_prompt(t, text, append=False)
            )
            append_action = append_menu.addAction(label)
            append_action.triggered.connect(
                lambda _checked=False, t=target, text=selected_text: self._route_selection_to_prompt(t, text, append=True)
            )
        if self._is_terminal_selection_context_widget(obj):
            favorite_action = menu.addAction('Add selection to Terminal favorites')
            favorite_action.triggered.connect(
                lambda _checked=False, text=selected_text: self._add_terminal_favorite_from_text(text)
            )
        output_action = menu.addAction('Add selection to Generated outputs')
        output_action.triggered.connect(lambda _checked=False, text=selected_text: self._add_selected_text_output(text))
        menu.exec(global_pos)
        return True

    def _set_plain_text_prompt(self, editor, text: str, append: bool):
        text = str(text or '')
        if append:
            current = editor.toPlainText() if hasattr(editor, 'toPlainText') else editor.text()
            merged = (str(current).rstrip() + '\n\n' + text).strip() if str(current).strip() else text
        else:
            merged = text
        if hasattr(editor, 'setPlainText'):
            editor.setPlainText(merged)
            try:
                cursor = editor.textCursor()
                cursor.movePosition(QTextCursor.MoveOperation.End)
                editor.setTextCursor(cursor)
            except Exception:
                pass
        else:
            editor.setText(merged)
            try:
                editor.end(False)
            except Exception:
                pass

    def _select_main_tab(self, index: int):
        index = max(0, min(3, int(index)))
        try:
            self.pill_nav.select(index)
        except Exception:
            self.stacked_widget.setCurrentIndex(index)
        if self.stacked_widget.currentIndex() != index:
            self.stacked_widget.setCurrentIndex(index)

    def _route_text_to_api_prompt(self, text: str, append: bool = False, new_conversation: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        if new_conversation:
            self.ClearX()
        self._select_main_tab(TAB_API)
        self._set_plain_text_prompt(self.text1, text, append)
        self.text1.setFocus()
        self._refresh_text1_popup_visibility()

    def _route_text_to_external_prompt(self, target_index: int, text: str, append: bool = False, site_index=None):
        text = str(text or '').strip()
        if not text:
            return
        target_index = int(target_index)
        self._select_main_tab(target_index)
        panel, dock = self._external_prompt_panel_for_index(target_index)
        if panel is None or dock is None:
            return
        try:
            if site_index is not None:
                panel.select_site(int(site_index))
        except Exception:
            pass
        panel.set_prompt_dock_visible(True, animated=True)
        self._set_plain_text_prompt(dock.prompt_edit, text, append)
        dock.prompt_edit.setFocus()

    def _route_text_to_terminal_prompt(self, text: str, append: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        self._select_main_tab(TAB_TERMINAL)
        terminal = getattr(self, 'terminal_widget', None)
        input_line = getattr(terminal, 'input_line', None) if terminal is not None else None
        if input_line is not None:
            self._set_plain_text_prompt(input_line, text, append)
            input_line.setFocus()

    def _route_selection_to_prompt(self, target_index: int, text: str, append: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        target_index = int(target_index)
        if target_index == TAB_API:
            self._route_text_to_api_prompt(text, append)
            return
        if target_index in EXTERNAL_PROMPT_TAB_INDICES:
            self._route_text_to_external_prompt(target_index, text, append)
            return
        if target_index == TAB_TERMINAL:
            self._route_text_to_terminal_prompt(text, append)

    def _add_selected_text_output(self, text: str):
        text = str(text or '').strip()
        if not text:
            return
        created_at = datetime.datetime.now().isoformat(timespec='seconds')
        snippet = re.sub(r'\s+', ' ', text).strip()
        if len(snippet) > 48:
            snippet = snippet[:48].rstrip() + '...'
        tab_labels = MAIN_TAB_LABELS
        current_index = self.stacked_widget.currentIndex()
        tab_label = tab_labels[current_index] if 0 <= current_index < len(tab_labels) else 'Selection'
        scope_key = self._tab_output_scope_key(current_index)
        output = {
            'id': f'sel-{int(time.time() * 1000)}',
            'kind': 'text',
            'title': f'Selected text · {created_at}',
            'filename': 'selected-text.txt',
            'content': text,
            'path': '',
            'question': f'{tab_label} selection · {snippet or "Selected text"}',
            'question_index': -1,
            'assistant_index': -1,
            'created_at': created_at,
            'source': 'manual_selection',
            'tab_scope': scope_key or 'api',
        }
        if scope_key:
            outputs = merge_output_records(self._load_tab_outputs(scope_key), [output])
            self._save_tab_outputs(scope_key, outputs)
        else:
            history_messages = get_current_chat_history_messages()
            self._ensure_active_conversation(text, history_messages)
            record = load_conversation_record(self._active_conversation_path) if self._active_conversation_path else None
            if record is None:
                record = create_conversation_record('Selected outputs', history_messages=history_messages)
                self._active_conversation_path = record['path']
            record['outputs'] = merge_output_records(record.get('outputs', []), [output])
            record['updated_at'] = created_at
            saved = write_conversation_record(self._active_conversation_path, record)
            self._active_conversation_path = saved['path']
        self._refresh_outputs_panel(prefer_latest=True)
        self.show_outputs_panel()

    def _sync_prompt_from_inline(self):
        if getattr(self, '_prompt_syncing', False):
            return
        text = self.text1.toPlainText()
        cursor_pos = self.text1.textCursor().position()
        self._prompt_syncing = True
        try:
            if self._text1_popup.edit.toPlainText() != text:
                blocker = QSignalBlocker(self._text1_popup.edit)
                self._text1_popup.edit.setPlainText(text)
                del blocker
            cursor = self._text1_popup.edit.textCursor()
            cursor.setPosition(min(cursor_pos, len(text)))
            self._text1_popup.edit.setTextCursor(cursor)
        finally:
            self._prompt_syncing = False
        self._refresh_text1_popup_visibility()

    def _sync_prompt_from_popup(self):
        if getattr(self, '_prompt_syncing', False):
            return
        text = self._text1_popup.edit.toPlainText()
        cursor_pos = self._text1_popup.edit.textCursor().position()
        self._prompt_syncing = True
        try:
            if self.text1.toPlainText() != text:
                blocker = QSignalBlocker(self.text1)
                self.text1.setPlainText(text)
                del blocker
            cursor = self.text1.textCursor()
            cursor.setPosition(min(cursor_pos, len(text)))
            self.text1.setTextCursor(cursor)
        finally:
            self._prompt_syncing = False
        self.text1._emit_multiline_if_needed()
        self._refresh_text1_popup_visibility()

    def _prompt_widget_has_focus(self, widget) -> bool:
        current = widget
        while current is not None:
            if current is self.text1 or current is self._text1_popup or current is self._text1_popup.edit:
                return True
            current = current.parentWidget()
        return False

    def _should_show_text1_popup(self) -> bool:
        if not hasattr(self, '_text1_popup'):
            return False
        if not self.isVisible() or not self._is_assistant_tab():
            return False
        if not self._right_pill._active or not self.text1.isVisible():
            return False
        if not self.text1.has_multiline_content():
            return False
        return self._prompt_widget_has_focus(QApplication.focusWidget())

    def _update_text1_popup_geometry(self):
        if not hasattr(self, '_text1_popup'):
            return
        if self._text1_popup.isVisible():
            self._text1_popup.show_for_anchor(self.text1)
        if hasattr(self, '_slash_command_popup') and self._slash_command_popup.isVisible():
            self._slash_command_popup.show_for_anchor(self.text1, self._current_slash_query())
        if hasattr(self, '_mention_target_popup') and self._mention_target_popup.isVisible():
            self._mention_target_popup.show_for_anchor(self.text1, self._current_mention_query())

    def _refresh_text1_popup_visibility(self):
        if not hasattr(self, '_text1_popup'):
            return
        if self._should_show_text1_popup():
            self._text1_popup.show_for_anchor(self.text1)
        else:
            focus_widget = QApplication.focusWidget()
            if (
                self._text1_popup.isVisible()
                and not self.text1.has_multiline_content()
                and self._prompt_widget_has_focus(focus_widget)
                and focus_widget is not self.text1
            ):
                self.text1.setFocus()
            self._text1_popup.hide_animated()

    def _on_prompt_focus_changed(self, _old, _new):
        QTimer.singleShot(0, self._refresh_text1_popup_visibility)
        QTimer.singleShot(0, self._refresh_slash_command_popup)
        QTimer.singleShot(0, self._refresh_mention_target_popup)

    def _sync_branch_state_metadata(self, state: dict | None):
        if not isinstance(state, dict):
            return
        node_by_id = {}
        checked_node_ids = set()
        message_index_to_node_id = {}

        def walk(node: dict, parent_id: str = ''):
            node['parent_id'] = parent_id
            node_id = str(node.get('id', '')).strip()
            if not node_id:
                return
            node_by_id[node_id] = node
            try:
                msg_idx = int(node.get('message_index', -1))
            except (TypeError, ValueError):
                msg_idx = -1
            if msg_idx >= 0:
                message_index_to_node_id[msg_idx] = node_id
            if bool(node.get('checked', True)):
                checked_node_ids.add(node_id)
            for child in node.get('children', []) or []:
                walk(child, node_id)

        for root in state.get('roots', []) or []:
            walk(root, '')
        state['node_by_id'] = node_by_id
        state['checked_node_ids'] = checked_node_ids
        state['message_index_to_node_id'] = message_index_to_node_id
        if not bool(state.get('append_as_child', False)):
            state['active_node_id'] = ''
        elif str(state.get('active_node_id', '')).strip() not in node_by_id:
            if node_by_id:
                latest = max(node_by_id.values(), key=lambda node: int(node.get('message_index', -1) or -1))
                state['active_node_id'] = str(latest.get('id', ''))
            else:
                state['active_node_id'] = ''
        next_id = 1
        for node_id in node_by_id:
            if node_id.startswith('q'):
                try:
                    next_id = max(next_id, int(node_id[1:]) + 1)
                except Exception:
                    pass
        state['next_id'] = max(1, int(state.get('next_id', next_id) or next_id))

    def _sort_branch_nodes_by_message_index(self, nodes: list[dict]) -> list[dict]:
        ordered = []
        for node in list(nodes or []):
            if not isinstance(node, dict):
                continue
            node['children'] = self._sort_branch_nodes_by_message_index(node.get('children', []) or [])
            ordered.append(node)
        ordered.sort(key=lambda node: int(node.get('message_index', -1) or -1))
        return ordered

    def _build_branch_state_from_messages(self, messages: list[dict], stored_branches: dict | None = None) -> dict:
        state = {
            'conversation_path': str(self._active_conversation_path or ''),
            'roots': [],
            'node_by_id': {},
            'checked_node_ids': set(),
            'message_index_to_node_id': {},
            'active_node_id': '',
            'next_id': 1,
            'append_as_child': False,
        }
        user_messages = {
            message_index: str(message.get('content', '')).strip()
            for message_index, message in enumerate(messages or [])
            if str(message.get('role', '')).strip().lower() == 'user'
        }
        used_indices = set()
        used_ids = set()

        def unique_node_id(raw_id: str, message_index: int) -> str:
            base = str(raw_id or '').strip() or f"q{message_index + 1}"
            candidate = base
            suffix = 2
            while candidate in used_ids:
                candidate = f'{base}_{suffix}'
                suffix += 1
            used_ids.add(candidate)
            return candidate

        def build_node(node_data: dict, parent_id: str = '') -> dict | None:
            if not isinstance(node_data, dict):
                return None
            try:
                message_index = int(node_data.get('message_index', -1))
            except (TypeError, ValueError):
                return None
            if message_index not in user_messages or message_index in used_indices:
                return None
            used_indices.add(message_index)
            full_text = user_messages[message_index]
            node_id = unique_node_id(node_data.get('id', ''), message_index)
            node = {
                'id': node_id,
                'text': full_text,
                'full_text': full_text,
                'message_index': message_index,
                'checked': True,
                'children': [],
                'parent_id': parent_id,
            }
            for child_data in node_data.get('children', []) or []:
                child = build_node(child_data, node_id)
                if child is not None:
                    node['children'].append(child)
            return node

        branch_payload = stored_branches if isinstance(stored_branches, dict) else {}
        for root_data in branch_payload.get('roots', []) or []:
            root_node = build_node(root_data, '')
            if root_node is not None:
                state['roots'].append(root_node)

        for message_index in sorted(user_messages):
            if message_index in used_indices:
                continue
            node_id = unique_node_id('', message_index)
            full_text = user_messages[message_index]
            state['roots'].append({
                'id': node_id,
                'text': full_text,
                'full_text': full_text,
                'message_index': message_index,
                'checked': True,
                'children': [],
                'parent_id': '',
            })

        state['roots'] = self._sort_branch_nodes_by_message_index(state.get('roots', []))
        self._sync_branch_state_metadata(state)
        active_node_id = str(branch_payload.get('active_node_id', '')).strip()
        if bool(branch_payload.get('append_as_child', False)) and active_node_id in state['node_by_id']:
            state['active_node_id'] = active_node_id
        else:
            state['active_node_id'] = ''
        state['append_as_child'] = bool(branch_payload.get('append_as_child', False) and state.get('active_node_id'))
        return state

    def _serialize_branch_state_for_storage(self, state: dict | None) -> dict:
        if not isinstance(state, dict):
            return {'roots': [], 'active_node_id': '', 'append_as_child': False}

        def serialize_node(node: dict) -> dict:
            return {
                'id': str(node.get('id', '')).strip(),
                'message_index': int(node.get('message_index', -1) or -1),
                'children': [serialize_node(child) for child in node.get('children', []) or []],
            }

        active_node_id = str(state.get('active_node_id', '')).strip()
        if not bool(state.get('append_as_child', False)) or active_node_id not in state.get('node_by_id', {}):
            active_node_id = ''
        return {
            'roots': [serialize_node(node) for node in state.get('roots', []) or []],
            'active_node_id': active_node_id,
            'append_as_child': bool(state.get('append_as_child', False) and active_node_id),
        }

    def _persist_active_branch_structure(self, state: dict | None = None):
        if not self._active_conversation_path:
            return
        if state is None:
            state = self._current_branch_state()
        if not isinstance(state, dict):
            return
        record = self._load_active_conversation_record()
        if record is None:
            return
        record['branches'] = self._serialize_branch_state_for_storage(state)
        saved = write_conversation_record(self._active_conversation_path, record)
        self._active_conversation_path = saved['path']

    def _current_branch_state(self) -> dict | None:
        path = self._branch_state_key()
        if not path:
            return None
        return self._branch_states.get(path)

    def _branch_state_key(self, history_messages: list[dict] | None = None) -> str:
        path = str(self._active_conversation_path or '').strip()
        if path:
            return path
        if history_messages is None:
            history_messages = get_current_chat_history_messages()
        return '__current__' if history_messages else ''

    def _ensure_branch_state_loaded(self, history_messages: list[dict] | None = None) -> dict | None:
        path = self._branch_state_key(history_messages)
        if not path:
            self.branch_panel.set_branch_state(None)
            return None
        state = self._branch_states.get(path)
        if state is None:
            record = None
            if history_messages is None:
                record = self._load_active_conversation_record() if path == str(self._active_conversation_path or '').strip() else load_conversation_record(path) if path and path != '__current__' else None
                history_messages = list(record.get('messages', [])) if record else []
            elif path == str(self._active_conversation_path or '').strip():
                record = self._load_active_conversation_record()
            elif path and path != '__current__':
                record = load_conversation_record(path)
            stored_branches = record.get('branches') if record else None
            state = self._build_branch_state_from_messages(history_messages or [], stored_branches)
            state['conversation_path'] = path
            self._branch_states[path] = state
        else:
            state['conversation_path'] = path
            self._sync_branch_state_metadata(state)
        self.branch_panel.set_branch_state(state)
        return state

    def _selected_branch_message_indices(self, history_messages: list[dict], state: dict | None = None) -> set[int]:
        if state is None:
            state = self._ensure_branch_state_loaded(history_messages)
        if not state:
            return set(range(len(history_messages or [])))
        selected_user_indices = {
            int(node.get('message_index', -1))
            for node_id, node in state.get('node_by_id', {}).items()
            if node_id in state.get('checked_node_ids', set())
        }
        if not selected_user_indices:
            return set()
        selected_indices = set()
        keep = False
        for message_index, message in enumerate(history_messages or []):
            if str(message.get('role', '')).strip().lower() == 'user':
                keep = message_index in selected_user_indices
                if keep:
                    selected_indices.add(message_index)
            elif keep:
                selected_indices.add(message_index)
        return selected_indices

    def _filter_history_messages_by_branch(self, history_messages: list[dict]) -> tuple[list[dict], set[int]]:
        state = self._ensure_branch_state_loaded(history_messages)
        selected_indices = self._selected_branch_message_indices(history_messages, state)
        if not selected_indices:
            return [], set()
        return [
            message for message_index, message in enumerate(history_messages)
            if message_index in selected_indices
        ], selected_indices

    def _append_question_to_branch_state(self, question_text: str, message_index: int):
        path = self._branch_state_key()
        if not path:
            return
        state = self._ensure_branch_state_loaded(get_current_chat_history_messages())
        if state is None:
            state = self._build_branch_state_from_messages([])
            state['conversation_path'] = path
            self._branch_states[path] = state
        node_id = f"q{int(state.get('next_id', 1) or 1)}"
        state['next_id'] = int(state.get('next_id', 1) or 1) + 1
        parent_id = str(state.get('active_node_id', '') or '').strip()
        append_as_child = bool(state.get('append_as_child', False))
        parent = state.get('node_by_id', {}).get(parent_id) if (append_as_child and parent_id) else None
        node = {
            'id': node_id,
            'text': str(question_text or '').strip(),
            'full_text': str(question_text or '').strip(),
            'message_index': int(message_index),
            'checked': True,
            'children': [],
            'parent_id': parent_id if parent is not None else '',
        }
        if parent is None:
            state.setdefault('roots', []).append(node)
        else:
            parent.setdefault('children', []).append(node)
            current = parent
            while current is not None:
                current['checked'] = True
                current = state.get('node_by_id', {}).get(str(current.get('parent_id', '')).strip())
        state['roots'] = self._sort_branch_nodes_by_message_index(state.get('roots', []))
        state['active_node_id'] = node_id
        if parent is not None:
            state['append_as_child'] = True
        self._sync_branch_state_metadata(state)
        self.branch_panel.set_branch_state(state)
        self._persist_active_branch_structure(state)

    def _refresh_branch_state_from_current_conversation(self):
        if not self._active_conversation_path:
            self.branch_panel.set_branch_state(None)
            return
        record = self._load_active_conversation_record()
        history_messages = list(record.get('messages', [])) if record else get_current_chat_history_messages()
        self._ensure_branch_state_loaded(history_messages)

    def _on_branch_state_changed(self, state: dict):
        path = self._branch_state_key()
        if not path:
            return
        self._sync_branch_state_metadata(state)
        self._branch_states[path] = state

    def _jump_to_message_index(self, message_index: int):
        message_index = max(0, int(message_index))
        self.real2.page().runJavaScript(
            "(() => { const el = document.getElementById('msg-%d'); if (el) { el.scrollIntoView({behavior:'smooth', block:'center'}); } })();" % message_index
        )

    def _branch_panel_shown_rect(self):
        width = min(500, max(320, self.qw3.width() - 36))
        height = min(760, max(360, self.qw3.height() - 36))
        x = max(18, (self.qw3.width() - width) // 2)
        return QRect(x, 18, width, height)

    def _branch_panel_hidden_rect(self):
        shown = self._branch_panel_shown_rect()
        return QRect(shown.x(), -shown.height() - 24, shown.width(), shown.height())

    def _update_branch_overlay_geometry(self):
        if not hasattr(self, '_branch_scrim'):
            return
        stacked_pos = self.stacked_widget.mapTo(self.qw3, QPoint(0, 0))
        trigger_w = max(0, self.stacked_widget.width() - 20)
        self._branch_trigger_btn.setGeometry(
            stacked_pos.x() + 10,
            stacked_pos.y(),
            trigger_w,
            self._branch_trigger_band_h,
        )
        self._branch_trigger_btn.raise_()
        self._branch_scrim.setGeometry(self.qw3.rect())
        if self._branch_panel_visible:
            self.branch_panel.setGeometry(self._branch_panel_shown_rect())
        else:
            self.branch_panel.setGeometry(self._branch_panel_hidden_rect())
        self._raise_webfetch_panel_if_visible()

    def _raise_webfetch_panel_if_visible(self):
        if hasattr(self, 'webfetch_panel') and self.webfetch_panel.isVisible():
            self.webfetch_panel.raise_()

    def _outputs_panel_shown_rect(self):
        safe_w = max(280, self.qw3.width() - 56)
        safe_h = max(320, self.qw3.height() - 96)
        width = min(620, safe_w)
        height = min(620, safe_h)
        x = max(28, (self.qw3.width() - width) // 2)
        y = max(38, (self.qw3.height() - height) // 2)
        return QRect(x, y, width, height)

    def _outputs_panel_hidden_rect(self):
        shown = self._outputs_panel_shown_rect()
        return QRect(shown.x(), -shown.height() - 24, shown.width(), shown.height())

    def _update_outputs_overlay_geometry(self):
        if not hasattr(self, '_outputs_scrim'):
            return
        pill_pos = self.pill_nav.mapTo(self, QPoint(0, 0))
        trigger_y = max(self.qw3.pos().y() + 2, pill_pos.y() - self._branch_trigger_band_h - 2)
        self._outputs_trigger_btn.setGeometry(
            pill_pos.x(),
            trigger_y,
            max(0, self.pill_nav.width()),
            self._branch_trigger_band_h,
        )
        self._outputs_trigger_btn.raise_()
        self._outputs_scrim.setGeometry(self.qw3.rect())
        if self._outputs_panel_visible:
            self.outputs_panel.setGeometry(self._outputs_panel_shown_rect())
        else:
            self.outputs_panel.setGeometry(self._outputs_panel_hidden_rect())

    def _share_panel_shown_rect(self):
        safe_w = max(280, self.qw3.width() - 56)
        safe_h = max(320, self.qw3.height() - 96)
        width = min(620, safe_w)
        height = min(620, safe_h)
        x = max(28, (self.qw3.width() - width) // 2)
        y = max(38, (self.qw3.height() - height) // 2)
        return QRect(x, y, width, height)

    def _share_panel_hidden_rect(self):
        shown = self._share_panel_shown_rect()
        return QRect(shown.x(), shown.y() - 32, shown.width(), shown.height())

    def _update_share_overlay_geometry(self):
        if not hasattr(self, '_share_scrim'):
            return
        self._share_scrim.setGeometry(self.qw3.rect())
        if self._share_panel_visible:
            self.share_panel.setGeometry(self._share_panel_shown_rect())
        else:
            self.share_panel.setGeometry(self._share_panel_hidden_rect())

    def show_branch_panel(self):
        if self.stacked_widget.currentIndex() != TAB_API or self._branch_panel_visible:
            return
        if self._settings_panel_visible:
            self.hide_settings_panel()
        if self._history_panel_visible:
            self.hide_history_panel()
        if self._links_panel_visible:
            self.hide_links_panel()
        if self._branch_panel_visible:
            self.hide_branch_panel()
        if self._outputs_panel_visible:
            self.hide_outputs_panel()
        self._refresh_branch_state_from_current_conversation()
        self._branch_trigger_btn.hide()
        self._settings_trigger_btn.hide()
        self._history_trigger_btn.hide()
        self._links_trigger_btn.hide()
        self._outputs_trigger_btn.hide()
        if self._branch_panel_anim is not None:
            self._branch_panel_anim.stop()
        if self._branch_scrim_anim is not None:
            self._branch_scrim_anim.stop()
        self._update_branch_overlay_geometry()
        self._branch_panel_visible = True
        start_rect = self._branch_panel_hidden_rect()
        end_rect = self._branch_panel_shown_rect()
        self._branch_scrim.show()
        self._branch_scrim.raise_()
        self.branch_panel.setGeometry(start_rect)
        self.branch_panel.show()
        self.branch_panel.raise_()
        self._branch_scrim_opacity.setOpacity(0.0)
        self._branch_panel_anim = QPropertyAnimation(self.branch_panel, b'geometry', self)
        self._branch_panel_anim.setDuration(260)
        self._branch_panel_anim.setStartValue(start_rect)
        self._branch_panel_anim.setEndValue(end_rect)
        self._branch_panel_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._branch_scrim_anim = QPropertyAnimation(self._branch_scrim_opacity, b'opacity', self)
        self._branch_scrim_anim.setDuration(220)
        self._branch_scrim_anim.setStartValue(0.0)
        self._branch_scrim_anim.setEndValue(1.0)
        self._branch_scrim_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._branch_panel_anim.start()
        self._branch_scrim_anim.start()
        self.branch_panel.setFocus()

    def hide_branch_panel(self):
        if not self._branch_panel_visible:
            return
        if self._branch_panel_anim is not None:
            self._branch_panel_anim.stop()
        if self._branch_scrim_anim is not None:
            self._branch_scrim_anim.stop()
        start_rect = self.branch_panel.geometry()
        end_rect = self._branch_panel_hidden_rect()
        start_opacity = self._branch_scrim_opacity.opacity()
        self._branch_panel_visible = False
        self._branch_panel_anim = QPropertyAnimation(self.branch_panel, b'geometry', self)
        self._branch_panel_anim.setDuration(220)
        self._branch_panel_anim.setStartValue(start_rect)
        self._branch_panel_anim.setEndValue(end_rect)
        self._branch_panel_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._branch_panel_anim.finished.connect(self._finish_hide_branch_panel)
        self._branch_scrim_anim = QPropertyAnimation(self._branch_scrim_opacity, b'opacity', self)
        self._branch_scrim_anim.setDuration(200)
        self._branch_scrim_anim.setStartValue(start_opacity)
        self._branch_scrim_anim.setEndValue(0.0)
        self._branch_scrim_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._branch_panel_anim.start()
        self._branch_scrim_anim.start()

    def _finish_hide_branch_panel(self):
        self.branch_panel.hide()
        self._branch_scrim.hide()
        if self.stacked_widget.currentIndex() == TAB_API:
            self._branch_trigger_btn.show()
            self._branch_trigger_btn.raise_()
            self._raise_webfetch_panel_if_visible()
        self._outputs_trigger_btn.show()
        self._outputs_trigger_btn.raise_()
        self._settings_trigger_btn.show()
        self._settings_trigger_btn.raise_()
        if self.stacked_widget.currentIndex() == TAB_API:
            self._history_trigger_btn.show()
            self._history_trigger_btn.raise_()
            self._links_trigger_btn.show()
            self._links_trigger_btn.raise_()

    def show_outputs_panel(self):
        if self._outputs_panel_visible:
            return
        if self._settings_panel_visible:
            self.hide_settings_panel()
        if self._history_panel_visible:
            self.hide_history_panel()
        if self._links_panel_visible:
            self.hide_links_panel()
        if self._branch_panel_visible:
            self.hide_branch_panel()
        if self._terminal_history_panel_visible:
            self.hide_terminal_history_panel()
        if self._terminal_favorites_panel_visible:
            self.hide_terminal_favorites_panel()
        self.outputs_panel.set_force_dark(self.stacked_widget.currentIndex() == TAB_TERMINAL)
        self._refresh_outputs_panel(prefer_latest=True)
        self._branch_trigger_btn.hide()
        self._outputs_trigger_btn.hide()
        self._settings_trigger_btn.hide()
        self._history_trigger_btn.hide()
        self._links_trigger_btn.hide()
        self._hide_terminal_side_triggers()
        if self._outputs_panel_anim is not None:
            self._outputs_panel_anim.stop()
        if self._outputs_scrim_anim is not None:
            self._outputs_scrim_anim.stop()
        self._update_outputs_overlay_geometry()
        self._outputs_panel_visible = True
        start_rect = self._outputs_panel_hidden_rect()
        end_rect = self._outputs_panel_shown_rect()
        self._outputs_scrim.show()
        self._outputs_scrim.raise_()
        self.outputs_panel.setGeometry(start_rect)
        self.outputs_panel.show()
        self.outputs_panel.raise_()
        self._outputs_scrim_opacity.setOpacity(0.0)
        self._outputs_panel_anim = QPropertyAnimation(self.outputs_panel, b'geometry', self)
        self._outputs_panel_anim.setDuration(260)
        self._outputs_panel_anim.setStartValue(start_rect)
        self._outputs_panel_anim.setEndValue(end_rect)
        self._outputs_panel_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._outputs_scrim_anim = QPropertyAnimation(self._outputs_scrim_opacity, b'opacity', self)
        self._outputs_scrim_anim.setDuration(220)
        self._outputs_scrim_anim.setStartValue(0.0)
        self._outputs_scrim_anim.setEndValue(1.0)
        self._outputs_scrim_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._outputs_panel_anim.start()
        self._outputs_scrim_anim.start()
        self.outputs_panel.setFocus()

    def hide_outputs_panel(self):
        if not self._outputs_panel_visible:
            return
        if self._outputs_panel_anim is not None:
            self._outputs_panel_anim.stop()
        if self._outputs_scrim_anim is not None:
            self._outputs_scrim_anim.stop()
        start_rect = self.outputs_panel.geometry()
        end_rect = self._outputs_panel_hidden_rect()
        start_opacity = self._outputs_scrim_opacity.opacity()
        self._outputs_panel_visible = False
        self._outputs_panel_anim = QPropertyAnimation(self.outputs_panel, b'geometry', self)
        self._outputs_panel_anim.setDuration(220)
        self._outputs_panel_anim.setStartValue(start_rect)
        self._outputs_panel_anim.setEndValue(end_rect)
        self._outputs_panel_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._outputs_panel_anim.finished.connect(self._finish_hide_outputs_panel)
        self._outputs_scrim_anim = QPropertyAnimation(self._outputs_scrim_opacity, b'opacity', self)
        self._outputs_scrim_anim.setDuration(200)
        self._outputs_scrim_anim.setStartValue(start_opacity)
        self._outputs_scrim_anim.setEndValue(0.0)
        self._outputs_scrim_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._outputs_panel_anim.start()
        self._outputs_scrim_anim.start()

    def _finish_hide_outputs_panel(self):
        self.outputs_panel.hide()
        self._outputs_scrim.hide()
        if self.stacked_widget.currentIndex() == TAB_API:
            self._branch_trigger_btn.show()
            self._branch_trigger_btn.raise_()
            self._raise_webfetch_panel_if_visible()
            self._history_trigger_btn.show()
            self._history_trigger_btn.raise_()
            self._links_trigger_btn.show()
            self._links_trigger_btn.raise_()
        self._outputs_trigger_btn.show()
        self._outputs_trigger_btn.raise_()
        self._settings_trigger_btn.show()
        self._settings_trigger_btn.raise_()
        if self.stacked_widget.currentIndex() == TAB_TERMINAL:
            self._show_terminal_side_triggers()

    def show_share_panel(self, pixmap: QPixmap):
        if pixmap.isNull():
            return
        for visible_attr, hide_func in (
            ('_settings_panel_visible', self.hide_settings_panel),
            ('_history_panel_visible', self.hide_history_panel),
            ('_links_panel_visible', self.hide_links_panel),
            ('_branch_panel_visible', self.hide_branch_panel),
            ('_outputs_panel_visible', self.hide_outputs_panel),
        ):
            if getattr(self, visible_attr, False):
                hide_func()
        self.share_panel.set_pixmap(pixmap)
        self._branch_trigger_btn.hide()
        self._outputs_trigger_btn.hide()
        self._settings_trigger_btn.hide()
        self._history_trigger_btn.hide()
        self._links_trigger_btn.hide()
        if self._share_panel_anim is not None:
            self._share_panel_anim.stop()
        if self._share_scrim_anim is not None:
            self._share_scrim_anim.stop()
        self._update_share_overlay_geometry()
        self._share_panel_visible = True
        start_rect = self._share_panel_hidden_rect()
        end_rect = self._share_panel_shown_rect()
        self._share_scrim.show()
        self._share_scrim.raise_()
        self.share_panel.setGeometry(start_rect)
        self.share_panel.show()
        self.share_panel.raise_()
        self._share_scrim_opacity.setOpacity(0.0)
        self._share_panel_anim = QPropertyAnimation(self.share_panel, b'geometry', self)
        self._share_panel_anim.setDuration(240)
        self._share_panel_anim.setStartValue(start_rect)
        self._share_panel_anim.setEndValue(end_rect)
        self._share_panel_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._share_scrim_anim = QPropertyAnimation(self._share_scrim_opacity, b'opacity', self)
        self._share_scrim_anim.setDuration(200)
        self._share_scrim_anim.setStartValue(0.0)
        self._share_scrim_anim.setEndValue(1.0)
        self._share_scrim_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._share_panel_anim.start()
        self._share_scrim_anim.start()

    def hide_share_panel(self):
        if not self._share_panel_visible:
            return
        if self._share_panel_anim is not None:
            self._share_panel_anim.stop()
        if self._share_scrim_anim is not None:
            self._share_scrim_anim.stop()
        start_rect = self.share_panel.geometry()
        end_rect = self._share_panel_hidden_rect()
        start_opacity = self._share_scrim_opacity.opacity()
        self._share_panel_visible = False
        self._share_panel_anim = QPropertyAnimation(self.share_panel, b'geometry', self)
        self._share_panel_anim.setDuration(180)
        self._share_panel_anim.setStartValue(start_rect)
        self._share_panel_anim.setEndValue(end_rect)
        self._share_panel_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._share_panel_anim.finished.connect(self._finish_hide_share_panel)
        self._share_scrim_anim = QPropertyAnimation(self._share_scrim_opacity, b'opacity', self)
        self._share_scrim_anim.setDuration(170)
        self._share_scrim_anim.setStartValue(start_opacity)
        self._share_scrim_anim.setEndValue(0.0)
        self._share_scrim_anim.setEasingCurve(QEasingCurve.Type.InCubic)
        self._share_panel_anim.start()
        self._share_scrim_anim.start()

    def _finish_hide_share_panel(self):
        self.share_panel.hide()
        self._share_scrim.hide()
        if self.stacked_widget.currentIndex() == TAB_API:
            self._branch_trigger_btn.show()
            self._branch_trigger_btn.raise_()
            self._raise_webfetch_panel_if_visible()
            self._outputs_trigger_btn.show()
            self._outputs_trigger_btn.raise_()
            self._history_trigger_btn.show()
            self._history_trigger_btn.raise_()
            self._links_trigger_btn.show()
            self._links_trigger_btn.raise_()
        self._settings_trigger_btn.show()
        self._settings_trigger_btn.raise_()

    def _copy_share_image(self):
        pixmap = self.share_panel.pixmap()
        if not pixmap.isNull():
            QApplication.clipboard().setPixmap(pixmap)

    def _save_share_image_as(self):
        pixmap = self.share_panel.pixmap()
        if pixmap.isNull():
            return
        default_path = os.path.join(str(Path.home()), f"Broccoli-share-{datetime.datetime.now().strftime('%Y%m%d-%H%M%S')}.png")
        target, _ = QFileDialog.getSaveFileName(self, 'Save share image', default_path, 'PNG Image (*.png)')
        if target:
            pixmap.save(target, 'PNG')

    def ShareX(self):
        if self.stacked_widget.currentIndex() != TAB_API:
            return
        choice = ask_broccoli_message(
            self,
            'Share',
            'Choose what to share from the current Agent conversation.',
            ['Full Markdown', 'Task Capsule', 'Screenshot', 'Cancel'],
            default_button_text='Screenshot',
            size=QSize(500, 190),
        )
        if choice == 'Full Markdown':
            self._share_full_markdown_text()
            return
        if choice == 'Task Capsule':
            self._start_task_capsule_share()
            return
        if choice == 'Screenshot':
            self._share_screenshot_current_api_output()
            return

    def _current_conversation_markdown_for_share(self) -> str:
        messages = get_current_chat_history_messages()
        if messages:
            return render_chat_history_markdown(messages).strip()
        fallback = read_text_file(BasePath + 'output.txt', '').strip()
        if fallback:
            return fallback
        if getattr(self, 'real1', None) is not None:
            return self.real1.toPlainText().strip()
        return ''

    def _share_full_markdown_text(self):
        text = self._current_conversation_markdown_for_share()
        if not text.strip():
            self._show_broccoli_message('Share', 'There is no conversation markdown to share.')
            return
        self._show_share_text_dialog('Full Markdown', text)

    def _start_task_capsule_share(self):
        text = self._current_conversation_markdown_for_share()
        if not text.strip():
            self._show_broccoli_message('Task Capsule', 'There is no conversation content to summarize.')
            return
        self._start_task_capsule_share_from_markdown(
            text,
            dialog_title='Task Capsule',
            dialog_subtitle='Generated via the active API profile. Edit before sending.',
        )

    def _terminal_share_title(self, payload: dict) -> str:
        payload = payload if isinstance(payload, dict) else {}
        kind = str(payload.get('kind', '') or '').strip().lower()
        if kind == 'codex':
            return 'Codex'
        if kind == 'claude':
            return 'Claude Code'
        title = str(payload.get('title', '') or '').strip()
        return title or 'Terminal'

    def _terminal_markdown_for_share(self, payload: object) -> str:
        payload = payload if isinstance(payload, dict) else {}
        kind = str(payload.get('kind', '') or '').strip().lower()
        title = self._terminal_share_title(payload)
        transcript_path = str(payload.get('transcript_path', '') or '').strip()
        text = ''
        if kind in {'codex', 'claude'} and transcript_path and os.path.exists(transcript_path):
            text = load_agent_cli_transcript_text(kind, transcript_path)
        if not str(text or '').strip():
            text = str(payload.get('text', '') or '').strip()
        if not text.strip():
            return ''
        meta_lines = [
            f'Source: {title}',
            f'Time: {datetime.datetime.now().isoformat(timespec="seconds")}',
        ]
        session_id = str(payload.get('resume_id', '') or payload.get('session_id', '') or '').strip()
        if session_id:
            meta_lines.append(f'Session: {session_id}')
        if transcript_path:
            meta_lines.append(f'Transcript: {transcript_path}')
        return (
            f'# Terminal Session - {title}\n\n'
            + '\n'.join(meta_lines)
            + '\n\n```text\n'
            + text.strip()
            + '\n```'
        )

    def _show_terminal_share_menu(self, payload: object):
        if self.stacked_widget.currentIndex() != TAB_TERMINAL:
            return
        markdown = self._terminal_markdown_for_share(payload)
        if not markdown.strip():
            show_broccoli_message(self, 'Share', 'There is no terminal text to share.', force_dark=True)
            return
        choice = ask_broccoli_message(
            self,
            'Share',
            'Choose what to share from the current Terminal session.',
            ['Full Markdown', 'Task Capsule', 'Cancel'],
            default_button_text='Full Markdown',
            size=QSize(500, 170),
            force_dark=True,
        )
        title = self._terminal_share_title(payload if isinstance(payload, dict) else {})
        if choice == 'Full Markdown':
            self._show_share_text_dialog(
                f'Full Markdown - {title}',
                markdown,
                subtitle='Edit before sending.',
                force_dark=True,
            )
            return
        if choice == 'Task Capsule':
            self._start_task_capsule_share_from_markdown(
                markdown,
                dialog_title=f'Task Capsule - {title}',
                dialog_subtitle='Generated via the active API profile. Edit before sending.',
                source_meta={'source': 'terminal', 'title': title},
                force_dark=True,
            )

    def _start_task_capsule_share_from_markdown(self,
                                                markdown_text: str,
                                                *,
                                                dialog_title: str = 'Task Capsule',
                                                dialog_subtitle: str = '',
                                                source_meta: dict | None = None,
                                                force_dark: bool = False):
        markdown_text = str(markdown_text or '').strip()
        if not markdown_text:
            show_broccoli_message(
                self,
                'Task Capsule',
                'There is no conversation content to summarize.',
                force_dark=force_dark,
            )
            return
        running = getattr(self, '_task_capsule_share_thread', None)
        if running is not None and running.is_alive():
            show_broccoli_message(
                self,
                'Task Capsule',
                'A Task Capsule is already being generated.',
                force_dark=force_dark,
            )
            return
        profile = load_active_settings_profile()
        api_key = str(profile.get('api_key', '') or '').strip()
        endpoint = profile_runtime_base_url(profile)
        model = str(profile.get('model', '') or '').strip()
        timeout = int(profile.get('timeout', 60) or 60)
        if not api_key or not endpoint or not model:
            show_broccoli_message(
                self,
                'Task Capsule',
                'No active API profile is configured.',
                force_dark=force_dark,
            )
            return
        capsule_id = 'tc_' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
        signals = AsyncTaskCapsuleSignals()
        signals.finished.connect(self._on_task_capsule_share_finished)
        signals.failed.connect(self._on_task_capsule_share_failed)
        thread = AsyncTaskCapsuleThread(
            {
                'markdown_text': markdown_text,
                'api_key': api_key,
                'endpoint': endpoint,
                'model': model,
                'timeout': timeout,
                'capsule_id': capsule_id,
                'dialog_title': dialog_title,
                'dialog_subtitle': dialog_subtitle,
                'source_meta': dict(source_meta or {}),
                'force_dark': bool(force_dark),
            },
            signals,
        )
        self._task_capsule_share_signals = signals
        self._task_capsule_share_thread = thread
        self._task_capsule_share_force_dark = bool(force_dark)
        thread.start()
        show_broccoli_message(
            self,
            'Task Capsule',
            'Generating Task Capsule in the background.',
            force_dark=force_dark,
        )

    def _on_task_capsule_share_finished(self, payload: object):
        self._task_capsule_share_thread = None
        force_dark = bool(getattr(self, '_task_capsule_share_force_dark', False))
        self._task_capsule_share_force_dark = False
        if not isinstance(payload, dict):
            show_broccoli_message(
                self,
                'Task Capsule',
                'Task Capsule generation returned an invalid result.',
                force_dark=force_dark,
            )
            return
        force_dark = bool(payload.get('force_dark', force_dark))
        text = str(payload.get('text', '') or '').strip()
        if not text:
            show_broccoli_message(
                self,
                'Task Capsule',
                'Task Capsule generation returned empty output.',
                force_dark=force_dark,
            )
            return
        self._show_share_text_dialog(
            str(payload.get('dialog_title', '') or payload.get('title', '') or 'Task Capsule'),
            text,
            subtitle=str(payload.get('dialog_subtitle', '') or ''),
            force_dark=force_dark,
        )

    def _on_task_capsule_share_failed(self, message: str):
        self._task_capsule_share_thread = None
        force_dark = bool(getattr(self, '_task_capsule_share_force_dark', False))
        self._task_capsule_share_force_dark = False
        show_broccoli_message(
            self,
            'Task Capsule',
            str(message or 'Task Capsule generation failed.'),
            force_dark=force_dark,
        )

    def _show_share_text_dialog(self, title: str, text: str, subtitle: str = '', force_dark: bool = False):
        dialog = ShareTextDialog(title, text, owner=self, parent=self, subtitle=subtitle, force_dark=force_dark)
        dialog.apply_requested.connect(self._handle_share_text_apply)
        dialog.fit_to_parent(margin=48)
        _center_broccoli_dialog(dialog, self)
        if not hasattr(self, '_share_text_dialogs'):
            self._share_text_dialogs = []
        self._share_text_dialogs.append(dialog)

        def forget_dialog(_result=0, dlg=dialog):
            try:
                self._share_text_dialogs.remove(dlg)
            except ValueError:
                pass

        dialog.finished.connect(forget_dialog)
        dialog.show()
        dialog.raise_()
        dialog.activateWindow()

    def _handle_share_text_apply(self, payload: object):
        if not isinstance(payload, dict):
            return
        text = str(payload.get('text', '') or '').strip()
        if not text:
            return
        try:
            target_index = int(payload.get('target_index', TAB_API))
        except (TypeError, ValueError):
            target_index = TAB_API
        append = bool(payload.get('append', False))
        new_conversation = bool(payload.get('new_conversation', False))
        site_index = payload.get('site_index', None)

        def apply_payload():
            if target_index == TAB_API:
                self._route_text_to_api_prompt(
                    text,
                    append=append,
                    new_conversation=new_conversation,
                )
            elif target_index in EXTERNAL_PROMPT_TAB_INDICES:
                self._route_text_to_external_prompt(
                    target_index,
                    text,
                    append=append,
                    site_index=site_index,
                )
            elif target_index == TAB_TERMINAL:
                self._route_text_to_terminal_prompt(text, append=append)

        QTimer.singleShot(0, apply_payload)

    def _share_screenshot_current_api_output(self):
        if self.real2.isVisible():
            self.real2.page().runJavaScript(
                """
                (() => {
                  const sel = window.getSelection();
                  if (!sel || sel.rangeCount === 0 || !sel.toString().trim()) return null;
                  const container = document.createElement('div');
                  for (let i = 0; i < sel.rangeCount; i++) {
                    const range = sel.getRangeAt(i);
                    const fragment = range.cloneContents();
                    let host = range.commonAncestorContainer;
                    if (host && host.nodeType !== Node.ELEMENT_NODE) host = host.parentElement;
                    const styledHost = host && host.closest
                      ? host.closest('.qa-label, .user-message-plain, .attachment-display-block, .pipeline-details, .pipeline-step-body, pre, code, blockquote, table, p, li, h1, h2, h3, h4, h5, h6, td, th')
                      : null;
                    if (styledHost && styledHost !== document.body && styledHost !== document.documentElement) {
                      const wrapper = styledHost.cloneNode(false);
                      wrapper.appendChild(fragment);
                      container.appendChild(wrapper);
                    } else {
                      container.appendChild(fragment);
                    }
                  }
                  const styles = Array.from(document.querySelectorAll('style, link[rel~="stylesheet"]'))
                    .map(el => el.outerHTML)
                    .join('\\n');
                  return {
                    html: container.innerHTML,
                    text: sel.toString(),
                    styles,
                    base: document.baseURI || '',
                    width: Math.ceil((document.documentElement && document.documentElement.clientWidth) || window.innerWidth || 0)
                  };
                })();
                """,
                self._handle_real2_share_selection,
            )
            return
        cursor = self.real1.textCursor()
        text = cursor.selectedText().replace('\u2029', '\n') if cursor.hasSelection() else self.real1.toPlainText()
        self._capture_text_as_share_image(text)

    def _handle_real2_share_selection(self, selection):
        if isinstance(selection, dict) and str(selection.get('text', '') or '').strip():
            fragment = str(selection.get('html', '') or '').strip()
            if fragment:
                width = int(float(selection.get('width', self.real2.width()) or self.real2.width()))
                width = max(360, min(max(360, self.real2.width()), width))
                self._capture_html_fragment_as_share_image(
                    fragment,
                    extra_head_html=str(selection.get('styles', '') or ''),
                    width=width,
                    base_url=str(selection.get('base', '') or ''),
                )
                return
            self._capture_text_as_share_image(str(selection.get('text', '') or ''))
            return
        self._capture_real2_full_share_image()

    def _share_html_document(self, body_html: str, extra_head_html: str = '') -> str:
        dark = is_dark_theme(app)
        bg = '#2D2D2D' if dark else '#FFFFFF'
        fg = '#F2F2F7' if dark else '#20242B'
        table_border = '#4A4B4F' if dark else '#D9DDE4'
        code_bg = '#343436' if dark else '#F7F8FA'
        return f"""
        <html>
        <head>
          <meta charset="utf-8">
          {extra_head_html}
          <style>
            body {{
              margin: 0;
              padding: 24px;
              background: {bg};
              color: {fg};
              font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
              font-size: 15px;
              line-height: 1.62;
            }}
            body > .share-capture {{
              max-width: 860px;
              margin: 0 auto;
            }}
            pre, code {{
              font-family: "SF Mono", Menlo, Monaco, monospace;
              background: {code_bg};
              border-radius: 10px;
            }}
            pre {{
              padding: 14px;
              white-space: pre-wrap;
              word-break: break-word;
            }}
            table {{
              border-collapse: collapse;
              max-width: 100%;
            }}
            th, td {{
              border: 1px solid {table_border};
              padding: 8px;
            }}
            img, video {{
              max-width: 100%;
            }}
            .user-message-plain {{
              white-space: pre-wrap;
              word-break: break-word;
            }}
          </style>
        </head>
        <body><div class="share-capture">{body_html}</div></body>
        </html>
        """

    def _capture_text_as_share_image(self, text: str):
        text = str(text or '').strip()
        if not text:
            return
        body = f'<div style="white-space: pre-wrap; word-break: break-word;">{html.escape(text)}</div>'
        self._capture_html_fragment_as_share_image(body)

    def _capture_html_fragment_as_share_image(self,
                                             fragment_html: str,
                                             extra_head_html: str = '',
                                             width: int | None = None,
                                             base_url: str = ''):
        width = int(width or min(900, max(360, self.qw3.width() - 96)))
        self._capture_html_document_as_share_image(
            self._share_html_document(fragment_html, extra_head_html=extra_head_html),
            width,
            base_url,
        )

    def _capture_html_document_as_share_image(self, html_document: str, width: int, base_url: str = ''):
        width = min(1600, max(320, int(width or 0) + 180))
        view = QWebEngineView(self.qw3)
        view.setGeometry(-10000, -10000, width, 200)
        view.show()
        self._share_temp_view = view

        def _loaded(ok):
            try:
                view.loadFinished.disconnect(_loaded)
            except Exception:
                pass
            if not ok:
                view.deleteLater()
                if self._share_temp_view is view:
                    self._share_temp_view = None
                return
            self._capture_webview_static_page(
                view,
                lambda pixmap: self._finish_temp_share_capture(view, pixmap),
            )

        view.loadFinished.connect(_loaded)
        if base_url:
            view.setHtml(html_document, QUrl(base_url))
        else:
            view.setHtml(html_document)

    def _finish_temp_share_capture(self, view: QWebEngineView, pixmap: QPixmap):
        if view is not None:
            view.deleteLater()
        if self._share_temp_view is view:
            self._share_temp_view = None
        self.show_share_panel(pixmap)

    def _share_background_color(self) -> QColor:
        return QColor('#2D2D2D' if is_dark_theme(app) else '#FFFFFF')

    def _share_pixel_is_background(self, image: QImage, x: int, y: int, bg: QColor, tolerance: int = 18) -> bool:
        pixel = image.pixel(x, y)
        alpha = (pixel >> 24) & 0xFF
        if alpha < 8:
            return True
        red = (pixel >> 16) & 0xFF
        green = (pixel >> 8) & 0xFF
        blue = pixel & 0xFF
        return (
            abs(red - bg.red()) <= tolerance
            and abs(green - bg.green()) <= tolerance
            and abs(blue - bg.blue()) <= tolerance
        )

    def _share_row_has_content(self, image: QImage, y: int, bg: QColor, x1: int = 0, x2: int | None = None) -> bool:
        width = image.width()
        if x2 is None:
            x2 = width - 1
        x1 = max(0, min(width - 1, int(x1)))
        x2 = max(0, min(width - 1, int(x2)))
        if x2 < x1:
            return False
        step = 1 if (x2 - x1) <= 900 else 2
        for x in range(x1, x2 + 1, step):
            if not self._share_pixel_is_background(image, x, y, bg):
                return True
        if step > 1 and not self._share_pixel_is_background(image, x2, y, bg):
            return True
        return False

    def _share_column_has_content(self, image: QImage, x: int, bg: QColor, y1: int, y2: int) -> bool:
        height = image.height()
        y1 = max(0, min(height - 1, int(y1)))
        y2 = max(0, min(height - 1, int(y2)))
        if y2 < y1:
            return False
        step = 1 if (y2 - y1) <= 1600 else 2
        for y in range(y1, y2 + 1, step):
            if not self._share_pixel_is_background(image, x, y, bg):
                return True
        if step > 1 and not self._share_pixel_is_background(image, x, y2, bg):
            return True
        return False

    def _share_image_content_bounds(self, image: QImage, bg: QColor) -> QRect:
        return share_image_content_bounds(image, bg)

    def _crop_share_image_to_content(self, image: QImage) -> QImage:
        return crop_share_image_to_content(image, self._share_background_color())

    def _compress_share_vertical_whitespace(self, image: QImage) -> QImage:
        return compress_share_vertical_whitespace(image, self._share_background_color())

    def _finalize_share_image(self, image: QImage) -> QImage:
        return finalize_share_image_worker(image, self._share_background_color())

    def _finalize_share_image_async(self, image: QImage, callback):
        if image.isNull():
            return
        self._share_finalize_request_id += 1
        request_id = self._share_finalize_request_id
        self._share_finalize_callback = callback
        self._share_finalize_signals = AsyncShareImageSignals()
        self._share_finalize_signals.finished.connect(
            self._on_share_image_finalized,
            Qt.ConnectionType.QueuedConnection,
        )
        self._share_finalize_thread = AsyncShareImageThread(
            image.copy(),
            self._share_background_color(),
            self._share_finalize_signals,
            request_id,
        )
        self._share_finalize_thread.start()

    def _on_share_image_finalized(self, payload):
        if not isinstance(payload, dict):
            return
        if int(payload.get('request_id', 0) or 0) != self._share_finalize_request_id:
            return
        image = payload.get('image')
        callback = self._share_finalize_callback
        self._share_finalize_callback = None
        self._share_finalize_signals = None
        self._share_finalize_thread = None
        if not isinstance(image, QImage) or image.isNull():
            return
        pixmap = QPixmap.fromImage(image)
        pixmap.setDevicePixelRatio(1.0)
        if callable(callback):
            callback(pixmap)

    def _capture_real2_full_share_image(self):
        self.real2.page().runJavaScript(
            """
            (() => ({
              html: document.documentElement ? document.documentElement.outerHTML : '',
              base: document.baseURI || '',
              width: Math.ceil((document.documentElement && document.documentElement.clientWidth) || window.innerWidth || 0)
            }))();
            """,
            self._capture_real2_html_payload_as_share_image,
        )

    def _capture_real2_html_payload_as_share_image(self, payload):
        if not isinstance(payload, dict):
            self._capture_text_as_share_image(self.real1.toPlainText())
            return
        html_document = str(payload.get('html', '') or '')
        if not html_document.strip():
            return
        width = int(float(payload.get('width', self.real2.width()) or self.real2.width()))
        width = max(360, min(1600, max(width, self.real2.width())))
        self._capture_html_document_as_share_image(
            html_document,
            width,
            str(payload.get('base', '') or ''),
        )

    def _capture_webview_full_page(self, view: QWebEngineView, callback):
        if self._capture_webview_static_page(view, callback):
            return
        self._capture_webview_full_page_by_scroll(view, callback)

    def _capture_webview_static_page(self, view: QWebEngineView, callback) -> bool:
        if view is None or view.width() <= 0 or view.height() <= 0:
            return False
        view.page().runJavaScript(
            """
            (() => {
              const doc = document.documentElement;
              const body = document.body || doc;
              const originalX = window.scrollX || doc.scrollLeft || 0;
              const originalY = window.scrollY || doc.scrollTop || 0;
              window.scrollTo(0, 0);
              const docW = Math.ceil(Math.max(
                body ? body.scrollWidth : 0,
                doc ? doc.scrollWidth : 0,
                doc ? doc.clientWidth : 0,
                window.innerWidth || 0
              ));
              const docH = Math.ceil(Math.max(
                body ? body.scrollHeight : 0,
                doc ? doc.scrollHeight : 0,
                doc ? doc.clientHeight : 0,
                window.innerHeight || 0
              ));
              const rects = [];
              const addRect = (rect) => {
                if (!rect || rect.width < 1 || rect.height < 1) return;
                rects.push({
                  left: rect.left,
                  top: rect.top,
                  right: rect.right,
                  bottom: rect.bottom
                });
              };
              const root = document.querySelector('.share-capture') || body;
              const walker = document.createTreeWalker(
                root,
                NodeFilter.SHOW_TEXT,
                {
                  acceptNode: (node) => (
                    node.nodeValue && node.nodeValue.trim()
                      ? NodeFilter.FILTER_ACCEPT
                      : NodeFilter.FILTER_REJECT
                  )
                }
              );
              const range = document.createRange();
              let node;
              while ((node = walker.nextNode())) {
                range.selectNodeContents(node);
                for (const rect of range.getClientRects()) addRect(rect);
              }
              if (range.detach) range.detach();
              const mediaSelector = [
                'img', 'video', 'canvas', 'svg', 'table', 'pre', 'blockquote',
                '.attachment-display-block', '.pipeline-details',
                '.qa-label', '.pipeline-default-heading'
              ].join(',');
              root.querySelectorAll(mediaSelector).forEach((el) => {
                const st = window.getComputedStyle(el);
                if (!st || st.display === 'none' || st.visibility === 'hidden' || Number(st.opacity || 1) === 0) {
                  return;
                }
                addRect(el.getBoundingClientRect());
              });
              if (!rects.length) addRect((root || body).getBoundingClientRect());
              const padLeft = 56;
              const padRight = 160;
              const padTop = 88;
              const padBottom = 96;
              const left = Math.max(0, Math.floor(Math.min(...rects.map(r => r.left)) - padLeft));
              const top = Math.max(0, Math.floor(Math.min(...rects.map(r => r.top)) - padTop));
              const right = Math.ceil(Math.max(...rects.map(r => r.right)) + padRight);
              const bottom = Math.ceil(Math.max(...rects.map(r => r.bottom)) + padBottom);
              return {
                originalX,
                originalY,
                contentLeft: left,
                contentTop: top,
                contentWidth: Math.max(1, right - left),
                contentHeight: Math.max(1, bottom - top),
                layoutWidth: Math.ceil((doc && doc.clientWidth) || window.innerWidth || 0)
              };
            })();
            """,
            lambda metrics: self._start_webview_static_capture(view, metrics, callback),
        )
        return True

    def _start_webview_static_capture(self, view: QWebEngineView, metrics, callback):
        if not isinstance(metrics, dict):
            self._capture_webview_full_page_by_scroll(view, callback)
            return
        content_left = max(0, int(float(metrics.get('contentLeft', 0) or 0)))
        content_top = max(0, int(float(metrics.get('contentTop', 0) or 0)))
        content_w = max(1, int(float(metrics.get('contentWidth', view.width()) or view.width())))
        content_h = max(1, int(float(metrics.get('contentHeight', view.height()) or view.height())))
        layout_w = max(content_w, int(float(metrics.get('layoutWidth', view.width()) or view.width())), view.width())
        capture_w = max(layout_w, content_left + content_w)
        state = {
            'view': view,
            'callback': callback,
            'content_left': content_left,
            'content_top': content_top,
            'content_w': content_w,
            'content_h': content_h,
            'layout_w': layout_w,
            'capture_w': capture_w,
            'offset': 0,
            'segments': [],
            'segment_h': 1400,
            'render_scale': 2.0,
        }
        self._share_static_capture_state = state
        self._capture_next_webview_static_segment()

    def _capture_next_webview_static_segment(self):
        state = getattr(self, '_share_static_capture_state', None)
        if not state:
            return
        offset = int(state['offset'])
        content_h = int(state['content_h'])
        if offset >= content_h:
            self._finish_webview_static_capture()
            return
        view = state['view']
        segment_h = min(int(state['segment_h']), content_h - offset)
        layout_w = int(state['layout_w'])
        capture_w = int(state.get('capture_w', layout_w))
        render_scale = max(1.0, float(state.get('render_scale', 1.0) or 1.0))
        view.setGeometry(
            -10000,
            -10000,
            max(1, int(capture_w * render_scale)),
            max(1, int(segment_h * render_scale)),
        )
        bg = '#2D2D2D' if is_dark_theme(app) else '#FFFFFF'
        content_left = int(state['content_left'])
        content_top = int(state['content_top'])
        style_css = f"""
          html {{
            overflow: hidden !important;
            scrollbar-width: none !important;
            background: {bg} !important;
            width: {layout_w}px !important;
            min-width: {layout_w}px !important;
            max-width: {layout_w}px !important;
          }}
          body {{
            overflow: visible !important;
            width: {layout_w}px !important;
            min-width: {layout_w}px !important;
            max-width: {layout_w}px !important;
            transform: scale({render_scale}) translate(-{content_left}px, -{content_top + offset}px) !important;
            transform-origin: 0 0 !important;
            background: {bg} !important;
          }}
          ::-webkit-scrollbar {{
            display: none !important;
            width: 0 !important;
            height: 0 !important;
          }}
        """
        view.page().runJavaScript(
            f"""
            (() => {{
              const styleId = 'broccoli-share-static-capture-style';
              let style = document.getElementById(styleId);
              if (!style) {{
                style = document.createElement('style');
                style.id = styleId;
                document.head.appendChild(style);
              }}
              style.textContent = {json.dumps(style_css)};
              window.scrollTo(0, 0);
            }})();
            """,
            lambda _result: QTimer.singleShot(180, self._grab_current_webview_static_segment),
        )

    def _grab_current_webview_static_segment(self):
        state = getattr(self, '_share_static_capture_state', None)
        if not state:
            return
        view = state['view']
        pixmap = view.grab()
        if pixmap.isNull():
            self._share_static_capture_state = None
            self._capture_webview_full_page_by_scroll(view, state['callback'])
            return
        dpr = max(1.0, float(pixmap.devicePixelRatio()))
        render_scale = max(1.0, float(state.get('render_scale', 1.0) or 1.0))
        effective_dpr = dpr * render_scale
        image = pixmap.toImage()
        crop_w = min(image.width(), max(1, int(round(int(state['content_w']) * effective_dpr))))
        crop_h = min(image.height(), max(1, int(round((int(state['content_h']) - int(state['offset'])) * effective_dpr))))
        segment = image.copy(0, 0, crop_w, crop_h)
        state['segments'].append((int(state['offset']), segment, effective_dpr))
        state['offset'] = int(state['offset']) + max(1, int(round(crop_h / effective_dpr)))
        self._capture_next_webview_static_segment()

    def _finish_webview_static_capture(self):
        state = getattr(self, '_share_static_capture_state', None)
        self._share_static_capture_state = None
        if not state:
            return
        segments = state.get('segments') or []
        if not segments:
            self._capture_webview_full_page_by_scroll(state['view'], state['callback'])
            return
        dpr = max(1.0, float(segments[0][2]))
        canvas_w = max(1, int(int(state['content_w']) * dpr))
        canvas_h = max(1, int(int(state['content_h']) * dpr))
        max_canvas_h = 120000
        if canvas_h > max_canvas_h:
            scale = max_canvas_h / canvas_h
            canvas_h = max_canvas_h
            canvas_w = max(1, int(canvas_w * scale))
        else:
            scale = 1.0
        canvas = QImage(canvas_w, canvas_h, QImage.Format.Format_ARGB32)
        canvas.fill(QColor('#2D2D2D' if is_dark_theme(app) else '#FFFFFF'))
        painter = QPainter(canvas)
        for offset, segment, _dpr in segments:
            y = int(offset * dpr * scale)
            if scale != 1.0:
                target_w = max(1, int(segment.width() * scale))
                target_h = max(1, int(segment.height() * scale))
                painter.drawImage(QRect(0, y, target_w, target_h), segment)
            else:
                painter.drawImage(0, y, segment)
        painter.end()
        callback = state.get('callback')
        self._finalize_share_image_async(canvas, callback)

    def _capture_webview_pdf_page(self, view: QWebEngineView, callback) -> bool:
        if view is None or view.width() <= 0 or view.height() <= 0:
            return False
        page = view.page()
        if page is None or not hasattr(page, 'printToPdf'):
            return False
        page.runJavaScript(
            """
            (() => {
              const doc = document.documentElement;
              const body = document.body || doc;
              const originalX = window.scrollX || doc.scrollLeft || 0;
              const originalY = window.scrollY || doc.scrollTop || 0;
              const docW = Math.ceil(Math.max(
                body ? body.scrollWidth : 0,
                doc ? doc.scrollWidth : 0,
                doc ? doc.clientWidth : 0,
                window.innerWidth || 0
              ));
              const docH = Math.ceil(Math.max(
                body ? body.scrollHeight : 0,
                doc ? doc.scrollHeight : 0,
                doc ? doc.clientHeight : 0,
                window.innerHeight || 0
              ));
              const rects = [];
              const addRect = (rect) => {
                if (!rect || rect.width < 1 || rect.height < 1) return;
                rects.push({
                  left: rect.left + originalX,
                  top: rect.top + originalY,
                  right: rect.right + originalX,
                  bottom: rect.bottom + originalY
                });
              };
              const root = document.querySelector('.share-capture') || body;
              const walker = document.createTreeWalker(
                root,
                NodeFilter.SHOW_TEXT,
                {
                  acceptNode: (node) => (
                    node.nodeValue && node.nodeValue.trim()
                      ? NodeFilter.FILTER_ACCEPT
                      : NodeFilter.FILTER_REJECT
                  )
                }
              );
              const range = document.createRange();
              let node;
              while ((node = walker.nextNode())) {
                range.selectNodeContents(node);
                for (const rect of range.getClientRects()) addRect(rect);
              }
              if (range.detach) range.detach();
              const mediaSelector = [
                'img', 'video', 'canvas', 'svg', 'table', 'pre', 'blockquote',
                '.attachment-display-block', '.pipeline-details',
                '.qa-label', '.pipeline-default-heading'
              ].join(',');
              root.querySelectorAll(mediaSelector).forEach((el) => {
                const st = window.getComputedStyle(el);
                if (!st || st.display === 'none' || st.visibility === 'hidden' || Number(st.opacity || 1) === 0) {
                  return;
                }
                addRect(el.getBoundingClientRect());
              });
              if (!rects.length) addRect((root || body).getBoundingClientRect());
              const padLeft = 56;
              const padRight = 160;
              const padTop = 88;
              const padBottom = 96;
              const left = Math.max(0, Math.floor(Math.min(...rects.map(r => r.left)) - padLeft));
              const top = Math.max(0, Math.floor(Math.min(...rects.map(r => r.top)) - padTop));
              const right = Math.ceil(Math.max(...rects.map(r => r.right)) + padRight);
              const bottom = Math.ceil(Math.max(...rects.map(r => r.bottom)) + padBottom);
              return {
                originalX,
                originalY,
                contentLeft: left,
                contentTop: top,
                contentWidth: Math.max(1, right - left),
                contentHeight: Math.max(1, bottom - top)
              };
            })();
            """,
            lambda metrics: self._start_webview_pdf_capture(view, metrics, callback),
        )
        return True

    def _start_webview_pdf_capture(self, view: QWebEngineView, metrics, callback):
        if not isinstance(metrics, dict):
            self._capture_webview_full_page_by_scroll(view, callback)
            return
        try:
            from PyQt6.QtCore import QMarginsF, QSizeF
            from PyQt6.QtGui import QPageLayout, QPageSize
            content_left = max(0, int(float(metrics.get('contentLeft', 0) or 0)))
            content_top = max(0, int(float(metrics.get('contentTop', 0) or 0)))
            content_w = max(1, int(float(metrics.get('contentWidth', view.width()) or view.width())))
            content_h = max(1, int(float(metrics.get('contentHeight', view.height()) or view.height())))
            original_x = int(float(metrics.get('originalX', 0) or 0))
            original_y = int(float(metrics.get('originalY', 0) or 0))
            px_to_pt = 72.0 / 96.0
            page_size_f = QSizeF(content_w * px_to_pt, content_h * px_to_pt)
            try:
                page_size = QPageSize(page_size_f, QPageSize.Unit.Point, 'Broccoli Share')
            except TypeError:
                page_size = QPageSize(page_size_f, QPageSize.Unit.Point)
            try:
                layout = QPageLayout(
                    page_size,
                    QPageLayout.Orientation.Portrait,
                    QMarginsF(0, 0, 0, 0),
                    QPageLayout.Unit.Point,
                )
                try:
                    layout.setMode(QPageLayout.Mode.FullPageMode)
                except Exception:
                    pass
            except Exception:
                layout = None
            style_css = f"""
              html, body {{ scrollbar-width: none !important; }}
              ::-webkit-scrollbar {{
                display: none !important;
                width: 0 !important;
                height: 0 !important;
              }}
              @media print {{
                @page {{ size: {content_w}px {content_h}px; margin: 0; }}
                html, body {{
                  margin: 0 !important;
                  padding: 0 !important;
                  width: {content_w}px !important;
                  min-width: {content_w}px !important;
                  height: {content_h}px !important;
                  min-height: {content_h}px !important;
                  overflow: visible !important;
                }}
                body {{
                  transform: translate(-{content_left}px, -{content_top}px) !important;
                  transform-origin: 0 0 !important;
                }}
              }}
            """
            state = {
                'view': view,
                'callback': callback,
                'fallback': lambda: self._capture_webview_full_page_by_scroll(view, callback),
                'original_x': original_x,
                'original_y': original_y,
                'content_w': content_w,
                'content_h': content_h,
            }
            self._share_pdf_capture_state = state
            view.page().runJavaScript(
                f"""
                (() => {{
                  const styleId = 'broccoli-share-pdf-style';
                  let style = document.getElementById(styleId);
                  if (!style) {{
                    style = document.createElement('style');
                    style.id = styleId;
                    document.head.appendChild(style);
                  }}
                  style.textContent = {json.dumps(style_css)};
                }})();
                """,
                lambda _result: QTimer.singleShot(
                    80,
                    lambda: self._run_webview_print_to_pdf(view, layout),
                ),
            )
        except Exception:
            self._capture_webview_full_page_by_scroll(view, callback)

    def _run_webview_print_to_pdf(self, view: QWebEngineView, layout):
        try:
            if layout is not None:
                view.page().printToPdf(
                    lambda data: self._finish_webview_pdf_capture(data),
                    layout,
                )
            else:
                view.page().printToPdf(lambda data: self._finish_webview_pdf_capture(data))
        except TypeError:
            try:
                view.page().printToPdf(lambda data: self._finish_webview_pdf_capture(data))
            except Exception:
                self._finish_webview_pdf_capture(b'')
        except Exception:
            self._finish_webview_pdf_capture(b'')

    def _finish_webview_pdf_capture(self, data):
        state = getattr(self, '_share_pdf_capture_state', None)
        self._share_pdf_capture_state = None
        if not state:
            return
        view = state['view']
        view.page().runJavaScript(
            f"""
            (() => {{
              const style = document.getElementById('broccoli-share-pdf-style');
              if (style) style.remove();
              window.scrollTo({int(state['original_x'])}, {int(state['original_y'])});
            }})();
            """
        )
        try:
            pdf_bytes = bytes(data)
        except Exception:
            pdf_bytes = b''
        if not pdf_bytes:
            state['fallback']()
            return
        try:
            from PyQt6.QtCore import QByteArray, QBuffer, QIODevice
            from PyQt6.QtPdf import QPdfDocument
            pdf_doc = QPdfDocument(self)
            buffer = QBuffer(self)
            buffer.setData(QByteArray(pdf_bytes))
            buffer.open(QIODevice.OpenModeFlag.ReadOnly)
            status = pdf_doc.load(buffer)
            if status != QPdfDocument.Status.Ready or pdf_doc.pageCount() <= 0:
                buffer.close()
                state['fallback']()
                return
            scale = 2.0
            pages = []
            total_h = 0
            max_w = 1
            for i in range(pdf_doc.pageCount()):
                point_size = pdf_doc.pagePointSize(i)
                image_size = QSize(
                    max(1, int(point_size.width() * scale)),
                    max(1, int(point_size.height() * scale)),
                )
                image = pdf_doc.render(i, image_size)
                if image.isNull():
                    continue
                pages.append(image)
                max_w = max(max_w, image.width())
                total_h += image.height()
            buffer.close()
            if not pages:
                state['fallback']()
                return
            max_canvas_h = 120000
            if total_h > max_canvas_h:
                shrink = max_canvas_h / total_h
                canvas_w = max(1, int(max_w * shrink))
                canvas_h = max_canvas_h
            else:
                shrink = 1.0
                canvas_w = max_w
                canvas_h = total_h
            canvas = QImage(canvas_w, canvas_h, QImage.Format.Format_ARGB32)
            canvas.fill(QColor('#2D2D2D' if is_dark_theme(app) else '#FFFFFF'))
            painter = QPainter(canvas)
            y = 0
            for image in pages:
                if shrink != 1.0:
                    target_h = max(1, int(image.height() * shrink))
                    target_w = max(1, int(image.width() * shrink))
                    painter.drawImage(QRect(0, y, target_w, target_h), image)
                    y += target_h
                else:
                    painter.drawImage(0, y, image)
                    y += image.height()
            painter.end()
            callback = state.get('callback')
            self._finalize_share_image_async(canvas, callback)
        except Exception:
            state['fallback']()

    def _capture_webview_full_page_by_scroll(self, view: QWebEngineView, callback):
        if view is None or view.width() <= 0 or view.height() <= 0:
            return
        view.page().runJavaScript(
            """
            (() => {
              const styleId = 'broccoli-share-capture-style';
              let style = document.getElementById(styleId);
              if (!style) {
                style = document.createElement('style');
                style.id = styleId;
                document.head.appendChild(style);
              }
              style.textContent = `
                html, body { scrollbar-width: none !important; }
                ::-webkit-scrollbar {
                  display: none !important;
                  width: 0 !important;
                  height: 0 !important;
                }
              `;

              const doc = document.documentElement;
              const body = document.body || doc;
              const originalX = window.scrollX || doc.scrollLeft || 0;
              const originalY = window.scrollY || doc.scrollTop || 0;
              const docW = Math.ceil(Math.max(
                body ? body.scrollWidth : 0,
                doc ? doc.scrollWidth : 0,
                doc ? doc.clientWidth : 0,
                window.innerWidth || 0
              ));
              const docH = Math.ceil(Math.max(
                body ? body.scrollHeight : 0,
                doc ? doc.scrollHeight : 0,
                doc ? doc.clientHeight : 0,
                window.innerHeight || 0
              ));
              const rects = [];
              const addRect = (rect) => {
                if (!rect || rect.width < 1 || rect.height < 1) return;
                rects.push({
                  left: rect.left + originalX,
                  top: rect.top + originalY,
                  right: rect.right + originalX,
                  bottom: rect.bottom + originalY
                });
              };
              const root = document.querySelector('.share-capture') || body;
              const walker = document.createTreeWalker(
                root,
                NodeFilter.SHOW_TEXT,
                {
                  acceptNode: (node) => (
                    node.nodeValue && node.nodeValue.trim()
                      ? NodeFilter.FILTER_ACCEPT
                      : NodeFilter.FILTER_REJECT
                  )
                }
              );
              const range = document.createRange();
              let node;
              while ((node = walker.nextNode())) {
                range.selectNodeContents(node);
                for (const rect of range.getClientRects()) addRect(rect);
              }
              if (range.detach) range.detach();

              const mediaSelector = [
                'img', 'video', 'canvas', 'svg', 'table', 'pre', 'blockquote',
                '.attachment-display-block', '.pipeline-details',
                '.qa-label', '.pipeline-default-heading'
              ].join(',');
              root.querySelectorAll(mediaSelector).forEach((el) => {
                const st = window.getComputedStyle(el);
                if (!st || st.display === 'none' || st.visibility === 'hidden' || Number(st.opacity || 1) === 0) {
                  return;
                }
                addRect(el.getBoundingClientRect());
              });

              if (!rects.length) {
                addRect((root || body).getBoundingClientRect());
              }
              const padLeft = 56;
              const padRight = 160;
              const padTop = 88;
              const padBottom = 96;
              const left = Math.max(0, Math.floor(Math.min(...rects.map(r => r.left)) - padLeft));
              const top = Math.max(0, Math.floor(Math.min(...rects.map(r => r.top)) - padTop));
              const right = Math.ceil(Math.max(...rects.map(r => r.right)) + padRight);
              const bottom = Math.ceil(Math.max(...rects.map(r => r.bottom)) + padBottom);
              return {
                originalX,
                originalY,
                contentLeft: left,
                contentTop: top,
                contentWidth: Math.max(1, right - left),
                contentHeight: Math.max(1, bottom - top),
                viewportWidth: Math.ceil((doc && doc.clientWidth) || window.innerWidth || 0),
                viewportHeight: Math.ceil((doc && doc.clientHeight) || window.innerHeight || 0)
              };
            })();
            """,
            lambda metrics: self._start_webview_segment_capture(view, metrics, callback),
        )

    def _start_webview_segment_capture(self, view: QWebEngineView, metrics, callback):
        if not isinstance(metrics, dict):
            return
        content_left = max(0, int(float(metrics.get('contentLeft', 0) or 0)))
        content_top = max(0, int(float(metrics.get('contentTop', 0) or 0)))
        content_w = max(1, int(float(metrics.get('contentWidth', view.width()) or view.width())))
        content_h = max(1, int(float(metrics.get('contentHeight', view.height()) or view.height())))
        original_x = int(float(metrics.get('x', 0) or 0))
        original_y = int(float(metrics.get('y', 0) or 0))
        original_x = int(float(metrics.get('originalX', original_x) or original_x))
        original_y = int(float(metrics.get('originalY', original_y) or original_y))
        viewport_h = max(1, min(view.height(), int(float(metrics.get('viewportHeight', view.height()) or view.height()))))
        viewport_w = max(1, min(view.width(), int(float(metrics.get('viewportWidth', view.width()) or view.width()))))
        state = {
            'view': view,
            'callback': callback,
            'content_left': content_left,
            'content_top': content_top,
            'content_w': content_w,
            'content_h': content_h,
            'content_right': content_left + content_w,
            'content_bottom': content_top + content_h,
            'original_x': original_x,
            'original_y': original_y,
            'viewport_h': viewport_h,
            'viewport_w': viewport_w,
            'segments': [],
            'next_top': content_top,
            'safety': 0,
        }
        self._share_full_capture_state = state
        self._capture_next_webview_segment()

    def _capture_next_webview_segment(self):
        state = self._share_full_capture_state
        if not state:
            return
        view = state['view']
        y = int(state['next_top'])
        if y >= int(state['content_bottom']) or int(state.get('safety', 0)) > 320:
            self._finish_webview_segment_capture()
            return
        state['safety'] = int(state.get('safety', 0)) + 1
        view.page().runJavaScript(f"window.scrollTo({int(state['content_left'])}, {y});")
        QTimer.singleShot(140, self._grab_current_webview_segment)

    def _grab_current_webview_segment(self):
        state = self._share_full_capture_state
        if not state:
            return
        view = state['view']
        view.page().runJavaScript(
            """
            (() => {
              const doc = document.documentElement;
              return {
                x: window.scrollX || doc.scrollLeft || 0,
                y: window.scrollY || doc.scrollTop || 0,
                viewportWidth: Math.ceil((doc && doc.clientWidth) || window.innerWidth || 0),
                viewportHeight: Math.ceil((doc && doc.clientHeight) || window.innerHeight || 0)
              };
            })();
            """,
            self._grab_current_webview_segment_after_scroll,
        )

    def _grab_current_webview_segment_after_scroll(self, viewport_metrics):
        state = self._share_full_capture_state
        if not state:
            return
        view = state['view']
        if not isinstance(viewport_metrics, dict):
            viewport_metrics = {}
        scroll_x = int(float(viewport_metrics.get('x', 0) or 0))
        scroll_y = int(float(viewport_metrics.get('y', 0) or 0))
        viewport_w = max(1, min(view.width(), int(float(viewport_metrics.get('viewportWidth', state['viewport_w']) or state['viewport_w']))))
        viewport_h = max(1, min(view.height(), int(float(viewport_metrics.get('viewportHeight', state['viewport_h']) or state['viewport_h']))))
        content_left = int(state['content_left'])
        content_top = int(state['content_top'])
        content_right = int(state['content_right'])
        content_bottom = int(state['content_bottom'])
        visible_left = max(content_left, scroll_x)
        visible_top = max(content_top, scroll_y)
        visible_right = min(content_right, scroll_x + viewport_w)
        visible_bottom = min(content_bottom, scroll_y + viewport_h)
        logical_take_w = max(0, visible_right - visible_left)
        logical_take_h = max(0, visible_bottom - visible_top)
        if logical_take_w <= 0 or logical_take_h <= 0:
            state['next_top'] = min(content_bottom, int(state['next_top']) + viewport_h)
            self._capture_next_webview_segment()
            return
        pixmap = view.grab()
        if pixmap.isNull():
            self._finish_webview_segment_capture()
            return
        dpr = max(1.0, float(pixmap.devicePixelRatio()))
        image = pixmap.toImage()
        crop_x = max(0, int(round((visible_left - scroll_x) * dpr)))
        crop_y = max(0, int(round((visible_top - scroll_y) * dpr)))
        crop_w = min(image.width() - crop_x, max(1, int(round(logical_take_w * dpr))))
        crop_h = min(image.height() - crop_y, max(1, int(round(logical_take_h * dpr))))
        if crop_w <= 0 or crop_h <= 0:
            state['next_top'] = min(content_bottom, int(state['next_top']) + viewport_h)
            self._capture_next_webview_segment()
            return
        segment = image.copy(crop_x, crop_y, crop_w, crop_h)
        dest_x = max(0, visible_left - content_left)
        dest_y = max(0, visible_top - content_top)
        state['segments'].append((dest_x, dest_y, segment, dpr))
        next_top = visible_bottom
        if next_top <= int(state['next_top']) + 1:
            next_top = int(state['next_top']) + max(1, viewport_h)
        state['next_top'] = min(content_bottom, next_top)
        self._capture_next_webview_segment()

    def _finish_webview_segment_capture(self):
        state = self._share_full_capture_state
        self._share_full_capture_state = None
        if not state:
            return
        view = state['view']
        segments = state.get('segments', [])
        view.page().runJavaScript(
            f"""
            (() => {{
              const style = document.getElementById('broccoli-share-capture-style');
              if (style) style.remove();
              window.scrollTo({int(state['original_x'])}, {int(state['original_y'])});
            }})();
            """
        )
        if not segments:
            return
        dpr = max(1.0, float(segments[0][3]))
        canvas_w = max(1, int(int(state['content_w']) * dpr))
        canvas_h = max(1, int(int(state['content_h']) * dpr))
        max_canvas_h = 120000
        if canvas_h > max_canvas_h:
            scale = max_canvas_h / canvas_h
            canvas_h = max_canvas_h
            canvas_w = max(1, int(canvas_w * scale))
        else:
            scale = 1.0
        canvas = QImage(canvas_w, canvas_h, QImage.Format.Format_ARGB32)
        canvas.fill(QColor('#2D2D2D' if is_dark_theme(app) else '#FFFFFF'))
        painter = QPainter(canvas)
        for x, y, segment, _seg_dpr in segments:
            target_x = int(x * dpr * scale)
            target_y = int(y * dpr * scale)
            if scale != 1.0:
                target_h = max(1, int(segment.height() * scale))
                target_w = max(1, int(segment.width() * scale))
                painter.drawImage(QRect(target_x, target_y, target_w, target_h), segment)
            else:
                painter.drawImage(target_x, target_y, segment)
        painter.end()
        callback = state.get('callback')
        self._finalize_share_image_async(canvas, callback)

    def _web_conversation_view_key(self, view) -> str:
        return str(id(view)) if view is not None else ''

    def _web_conversation_panel_and_view(self, tab_index: int, view_index: int):
        panel, _dock = self._external_prompt_panel_for_index(int(tab_index))
        if panel is None:
            return None, None
        try:
            views = getattr(panel, '_views', [])
            view = views[int(view_index)] if 0 <= int(view_index) < len(views) else None
        except Exception:
            view = None
        return panel, view

    def _web_conversation_panel_for_view(self, target_view):
        if target_view is None:
            return None, None, None
        for tab_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, _dock = self._external_prompt_panel_for_index(tab_index)
            for idx, view in enumerate(getattr(panel, '_views', []) if panel is not None else []):
                if view is target_view:
                    return panel, tab_index, idx
        return None, None, None

    def _web_conversation_view_is_sleeping(self, panel, view) -> bool:
        if panel is None or view is None:
            return False
        try:
            state = panel._view_lifecycle_state(view) if hasattr(panel, '_view_lifecycle_state') else None
            frozen_state = panel._page_lifecycle_state('Frozen') if hasattr(panel, '_page_lifecycle_state') else None
            discarded_state = panel._page_lifecycle_state('Discarded') if hasattr(panel, '_page_lifecycle_state') else None
            return state is not None and (state == frozen_state or state == discarded_state)
        except Exception:
            return False

    def _web_conversation_source_key_for_view(self, tab_index: int, view) -> str:
        scope = 'web' if int(tab_index) == TAB_WEB else 'localhost' if int(tab_index) == TAB_LOCALHOST else 'unknown'
        try:
            url = view.url().toString()
        except Exception:
            url = ''
        return f'{scope}:{web_conversation_cache_key(url)}'

    def _web_conversation_capture_is_fresh(self, view, max_age_sec: int = 20) -> bool:
        key = self._web_conversation_view_key(view)
        cached = getattr(self, '_web_conversation_cache_by_view', {}).get(key)
        if not isinstance(cached, dict):
            return False
        try:
            return (time.monotonic() - float(cached.get('_captured_monotonic', 0) or 0)) <= max(1, int(max_age_sec))
        except Exception:
            return False

    def _web_conversation_cached_capture_for_view(self, view, *, schedule_if_stale: bool = True, tab_index: int | None = None, view_index: int | None = None) -> dict | None:
        if view is None:
            return None
        if tab_index is None or view_index is None:
            _panel, found_tab, found_idx = self._web_conversation_panel_for_view(view)
            if tab_index is None:
                tab_index = found_tab
            if view_index is None:
                view_index = found_idx
        key = self._web_conversation_view_key(view)
        cached = getattr(self, '_web_conversation_cache_by_view', {}).get(key)
        try:
            current_url = view.url().toString()
        except Exception:
            current_url = ''
        if isinstance(cached, dict):
            cached_url = canonical_web_conversation_url(cached.get('current_url') or cached.get('url') or '')
            if not current_url or cached_url == canonical_web_conversation_url(current_url):
                if self._web_conversation_capture_quality(cached).get('bad_external_prompt_only'):
                    if schedule_if_stale:
                        self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason='bad-cache')
                    return None
                if schedule_if_stale and not self._web_conversation_capture_is_fresh(view, max_age_sec=25):
                    self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason='stale-menu')
                return cached
        disk = load_web_conversation_cache(current_url) if current_url else None
        if isinstance(disk, dict):
            if self._web_conversation_capture_quality(disk).get('bad_external_prompt_only'):
                if schedule_if_stale:
                    self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason='bad-disk-cache')
                return None
            disk['_captured_monotonic'] = 0.0
            self._web_conversation_cache_by_view[key] = disk
            if schedule_if_stale:
                self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason='disk-stale')
            return disk
        if schedule_if_stale:
            self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason='missing')
        return None

    def _schedule_web_conversation_capture_for_view(self, view, tab_index: int | None = None, view_index: int | None = None, *, reason: str = 'manual', delay_ms: int = 2500):
        if view is None:
            return
        key = self._web_conversation_view_key(view)
        if not key:
            return
        panel = None
        if tab_index is not None:
            panel, _dock = self._external_prompt_panel_for_index(int(tab_index))
        if panel is None:
            panel, found_tab, found_idx = self._web_conversation_panel_for_view(view)
            if tab_index is None:
                tab_index = found_tab
            if view_index is None:
                view_index = found_idx
        if self._web_conversation_view_is_sleeping(panel, view):
            return
        timers = getattr(self, '_web_conversation_capture_timers', None)
        if timers is None:
            return
        timer = timers.get(key)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timers[key] = timer
        try:
            timer.timeout.disconnect()
        except Exception:
            pass
        timer.timeout.connect(lambda v=view, tab=tab_index, idx=view_index, why=reason: self._capture_web_conversation_view(v, tab, idx, why))
        timer.start(max(250, int(delay_ms)))

    def _schedule_web_conversation_capture(self, tab_index: int, view_index: int, *, reason: str = 'event', delay_ms: int = 2500):
        _panel, view = self._web_conversation_panel_and_view(tab_index, view_index)
        self._schedule_web_conversation_capture_for_view(view, tab_index, view_index, reason=reason, delay_ms=delay_ms)

    def _schedule_all_web_conversation_captures(self):
        for tab_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, _dock = self._external_prompt_panel_for_index(tab_index)
            for idx, view in enumerate(getattr(panel, '_views', []) if panel is not None else []):
                self._schedule_web_conversation_capture_for_view(view, tab_index, idx, reason='initial', delay_ms=700 + idx * 350)

    def _schedule_periodic_web_conversation_captures(self):
        for tab_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, _dock = self._external_prompt_panel_for_index(tab_index)
            for idx, view in enumerate(getattr(panel, '_views', []) if panel is not None else []):
                if view is None:
                    continue
                if self._web_conversation_view_is_sleeping(panel, view):
                    continue
                if self._web_conversation_capture_is_fresh(view, max_age_sec=45):
                    continue
                self._schedule_web_conversation_capture_for_view(view, tab_index, idx, reason='periodic', delay_ms=1500 + idx * 250)

    def _capture_web_conversation_view(self, view, tab_index: int | None = None, view_index: int | None = None, reason: str = 'capture'):
        if view is None:
            return
        key = self._web_conversation_view_key(view)
        if not key or key in self._web_conversation_capture_inflight:
            return
        try:
            url = view.url().toString()
        except Exception:
            url = ''
        if not url or url.startswith(('about:', 'chrome:', 'devtools:')):
            return
        panel = None
        if tab_index is not None:
            panel, _dock = self._external_prompt_panel_for_index(int(tab_index))
        if panel is None:
            panel, found_tab, found_idx = self._web_conversation_panel_for_view(view)
            if tab_index is None:
                tab_index = found_tab
            if view_index is None:
                view_index = found_idx
        if self._web_conversation_view_is_sleeping(panel, view):
            return
        now = time.monotonic()
        last_started = float(self._web_conversation_last_started.get(key, 0) or 0)
        if now - last_started < 8:
            return
        self._web_conversation_last_started[key] = now
        self._web_conversation_capture_inflight.add(key)
        state = {
            'capture': None,
            'assets': [],
            'html': '',
            'remaining': 3,
        }

        def complete():
            state['remaining'] = max(0, int(state.get('remaining', 0)) - 1)
            if state['remaining'] > 0:
                return
            self._web_conversation_capture_inflight.discard(key)
            capture = state.get('capture') if isinstance(state.get('capture'), dict) else {}
            if not capture:
                return
            capture = self._normalize_web_conversation_capture(capture)
            capture['assets'] = state.get('assets') if isinstance(state.get('assets'), list) else []
            capture['current_url'] = url
            if tab_index is not None:
                capture['tab_scope'] = 'web' if int(tab_index) == TAB_WEB else 'localhost' if int(tab_index) == TAB_LOCALHOST else 'unknown'
            if view_index is not None:
                capture['tab_index'] = int(view_index)
            previous = self._web_conversation_cache_by_view.get(key)
            current_canonical = canonical_web_conversation_url(url)
            previous_canonical = canonical_web_conversation_url(
                previous.get('current_url') or previous.get('url') or ''
            ) if isinstance(previous, dict) else ''
            if current_canonical != previous_canonical:
                previous = load_web_conversation_cache(url, capture.get('source', '')) or {}
                previous_canonical = canonical_web_conversation_url(
                    previous.get('current_url') or previous.get('url') or ''
                ) if isinstance(previous, dict) else ''
            if isinstance(previous, dict) and previous_canonical == current_canonical:
                if not self._web_conversation_capture_should_replace_cached(capture, previous):
                    previous['_captured_monotonic'] = time.monotonic()
                    self._web_conversation_cache_by_view[key] = previous
                    return
                merged_messages = self._merge_web_conversation_messages(
                    list(previous.get('messages') or []),
                    list(capture.get('messages') or []),
                )
                if merged_messages:
                    capture['messages'] = merged_messages
                previous_assets = previous.get('assets') if isinstance(previous.get('assets'), list) else []
                if previous_assets:
                    asset_keys = {
                        (str(item.get('type', '')), str(item.get('url', '')), str(item.get('name', '')))
                        for item in capture.get('assets', []) if isinstance(item, dict)
                    }
                    merged_assets = list(capture.get('assets') or [])
                    for item in previous_assets:
                        if not isinstance(item, dict):
                            continue
                        key_tuple = (str(item.get('type', '')), str(item.get('url', '')), str(item.get('name', '')))
                        if key_tuple not in asset_keys:
                            merged_assets.append(item)
                            asset_keys.add(key_tuple)
                    capture['assets'] = merged_assets[:120]
            capture['content_hash'] = web_conversation_capture_hash(capture)
            previous_hash = previous.get('content_hash') if isinstance(previous, dict) else ''
            capture['_captured_monotonic'] = time.monotonic()
            self._web_conversation_cache_by_view[key] = capture
            if self._web_conversation_capture_quality(capture).get('bad_external_prompt_only') and not previous:
                return
            if capture['content_hash'] == previous_hash and previous and previous.get('cache_path'):
                capture['cache_path'] = previous.get('cache_path')
                capture['cache_dir'] = previous.get('cache_dir')
                return

            html_text = str(state.get('html') or '')

            def writer(payload=dict(capture), html=html_text):
                try:
                    saved = write_web_conversation_cache(payload, html)
                    if isinstance(saved, dict):
                        saved['_captured_monotonic'] = payload.get('_captured_monotonic', time.monotonic())
                        self._web_conversation_cache_by_view[key] = saved
                except Exception:
                    logging.exception('Failed to write web conversation cache')

            threading.Thread(target=writer, daemon=True).start()

        try:
            view.page().runJavaScript(
                _WEB_CONVERSATION_CAPTURE_JS,
                lambda payload: (state.__setitem__('capture', payload if isinstance(payload, dict) else {}), complete()),
            )
        except Exception:
            complete()
        try:
            view.page().runJavaScript(
                _WEB_PAGE_ASSET_CAPTURE_JS,
                lambda assets: (state.__setitem__('assets', assets if isinstance(assets, list) else []), complete()),
            )
        except Exception:
            complete()
        try:
            view.page().toHtml(lambda html: (state.__setitem__('html', str(html or '')), complete()))
        except Exception:
            complete()

    def _web_capture_for_active_external_tab(self, tab_index: int) -> dict | None:
        panel, _dock = self._external_prompt_panel_for_index(tab_index)
        if panel is None or not hasattr(panel, 'active_view'):
            return None
        try:
            view = panel.active_view()
            view_index = panel.active_index() if hasattr(panel, 'active_index') else None
        except Exception:
            return None
        return self._web_conversation_cached_capture_for_view(view, tab_index=tab_index, view_index=view_index)

    def _external_prompt_panel_for_index(self, index: int):
        if index == TAB_WEB:
            return getattr(self, 'ai_web_panel', None), getattr(self, 'web_prompt_dock', None)
        if index == TAB_LOCALHOST:
            return getattr(self, 'localhost_panel', None), getattr(self, 'localhost_prompt_dock', None)
        return None, None

    def _install_send_shortcuts(self):
        if hasattr(self, '_send_shortcuts'):
            return
        self._send_shortcuts = []
        for sequence in ('Ctrl+Return', 'Ctrl+Enter', 'Meta+Return', 'Meta+Enter'):
            shortcut = QShortcut(QKeySequence(sequence), self)
            shortcut.setContext(Qt.ShortcutContext.WindowShortcut)
            shortcut.activated.connect(self._handle_send_shortcut)
            self._send_shortcuts.append(shortcut)

    def _on_external_prompt_dock_visibility_changed(self):
        self._update_web_conversation_sync_button_geometry()
        self._update_send_shortcut_enabled()

    def _update_send_shortcut_enabled(self):
        shortcuts = getattr(self, '_send_shortcuts', None)
        if not shortcuts or not hasattr(self, 'stacked_widget'):
            return
        enabled = False
        try:
            current_index = int(self.stacked_widget.currentIndex())
        except Exception:
            current_index = -1
        if current_index == TAB_API:
            enabled = True
        elif current_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, dock = self._external_prompt_panel_for_index(current_index)
            prompt_text = dock.prompt_text() if dock is not None and hasattr(dock, 'prompt_text') else ''
            enabled = bool(
                panel is not None
                and dock is not None
                and panel.is_prompt_dock_visible()
                and str(prompt_text or '').strip()
            )
        for shortcut in shortcuts:
            shortcut.setEnabled(enabled)

    def _handle_send_shortcut(self):
        if not hasattr(self, 'stacked_widget'):
            return
        try:
            current_index = int(self.stacked_widget.currentIndex())
        except Exception:
            return
        if current_index == TAB_API:
            button = getattr(self, 'btn_sub1', None)
            button_text = str(button.text()) if button is not None else ''
            if button is None or not button.isEnabled() or button_text.startswith('⛔'):
                return
            self.SendX()
            return
        if current_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, dock = self._external_prompt_panel_for_index(current_index)
            if panel is None or dock is None or not panel.is_prompt_dock_visible():
                return
            self.SendExternalPromptDockX(current_index)

    def _current_external_prompt_pair(self):
        return self._external_prompt_panel_for_index(self.stacked_widget.currentIndex())

    def _active_external_prompt_dock(self):
        _panel, dock = self._current_external_prompt_pair()
        return dock

    @staticmethod
    def _sync_external_prompt_dock_height(panel, dock):
        try:
            if panel is not None and dock is not None and panel.is_prompt_dock_visible():
                panel.set_prompt_dock_height(dock.sizeHint().height())
        except Exception:
            pass

    def _toggle_current_external_prompt_dock(self):
        panel, _dock = self._current_external_prompt_pair()
        if panel is None:
            return
        panel.set_prompt_dock_visible(not panel.is_prompt_dock_visible(), animated=True)
        if panel.is_prompt_dock_visible() and getattr(self, '_webfetch_records', None) and not getattr(self, '_webfetch_panel_dismissed', False):
            self._show_webfetch_panel()
        elif hasattr(self, 'webfetch_panel'):
            self.webfetch_panel.hide()

    def _update_external_prompt_trigger_geometry(self):
        if not hasattr(self, '_external_prompt_trigger_btn'):
            return
        index = self.stacked_widget.currentIndex() if hasattr(self, 'stacked_widget') else -1
        if index not in EXTERNAL_PROMPT_TAB_INDICES:
            self._external_prompt_trigger_btn.hide()
            return
        try:
            top = self.stacked_widget.mapTo(self.qw3, QPoint(0, 0)).y()
            height = self.stacked_widget.height()
        except Exception:
            top = 58
            height = max(0, self.qw3.height() - top)
        edge_gap = max(0, int(getattr(self, 'EDGE_AUTO_HIDE_PEEK_PX', 2)))
        trigger_w = int(getattr(self, '_external_prompt_trigger_w', 28))
        self._external_prompt_trigger_btn.setGeometry(
            edge_gap,
            max(0, top),
            max(0, trigger_w - edge_gap),
            max(0, height),
        )
        self._external_prompt_trigger_btn.show()
        self._external_prompt_trigger_btn.raise_()
        self._update_web_conversation_sync_button_geometry()

    def _web_conversation_sync_button_rect(self) -> QRect:
        diameter = WebConversationSyncButton.DIAMETER
        try:
            y = self._webfetch_panel_rect().y()
        except Exception:
            y = 58
        return QRect(20, max(0, y), diameter, diameter)

    def _update_web_conversation_sync_button_geometry(self):
        if not hasattr(self, 'web_conversation_sync_button'):
            return
        index = self.stacked_widget.currentIndex() if hasattr(self, 'stacked_widget') else -1
        if index not in EXTERNAL_PROMPT_TAB_INDICES:
            self.web_conversation_sync_button.hide()
            return
        panel, _dock = self._external_prompt_panel_for_index(index)
        if panel is None or not panel.is_prompt_dock_visible():
            self.web_conversation_sync_button.hide()
            return
        self.web_conversation_sync_button.setGeometry(self._web_conversation_sync_button_rect())
        self.web_conversation_sync_button.show()
        self.web_conversation_sync_button.raise_()

    def _selected_non_active_web_views(self, panel, dock) -> list:
        if panel is None or dock is None or not hasattr(panel, 'active_view'):
            return []
        try:
            active_view = panel.active_view()
        except Exception:
            active_view = None
        try:
            selected = dock.selected_target_views(panel) if hasattr(dock, 'selected_target_views') else []
        except Exception:
            selected = []
        return [view for view in selected if view is not None and view is not active_view]

    def _show_web_conversation_button_menu(self):
        index = self.stacked_widget.currentIndex() if hasattr(self, 'stacked_widget') else -1
        panel, dock = self._external_prompt_panel_for_index(index)
        if panel is None or dock is None:
            return
        menu = style_broccoli_context_menu(QMenu(self))
        sync_action = menu.addAction('Save current page to API history')
        forward_action = menu.addAction("Send selected tabs' latest replies here")
        forward_action.setEnabled(bool(self._selected_non_active_web_views(panel, dock)))
        chosen = menu.exec(self.web_conversation_sync_button.mapToGlobal(QPoint(0, self.web_conversation_sync_button.height() + 6)))
        if chosen == sync_action:
            self._sync_current_web_conversation_to_api()
        elif chosen == forward_action:
            self._forward_selected_web_replies_to_active(index)

    def _sync_current_web_conversation_to_api(self):
        index = self.stacked_widget.currentIndex() if hasattr(self, 'stacked_widget') else -1
        if index not in EXTERNAL_PROMPT_TAB_INDICES:
            return
        capture = self._web_capture_for_active_external_tab(index)
        if not capture:
            self.web_conversation_sync_button.setToolTip('Web conversation is being captured in the background.')
            return
        self._show_web_conversation_sync_menu(index, capture)

    def _web_conversation_source_key(self, tab_index: int) -> str:
        panel, _dock = self._external_prompt_panel_for_index(tab_index)
        scope = 'web' if tab_index == TAB_WEB else 'localhost' if tab_index == TAB_LOCALHOST else 'unknown'
        try:
            view = panel.active_view() if panel is not None else None
            url = view.url().toString() if view is not None else ''
        except Exception:
            url = ''
        return f'{scope}:{web_conversation_cache_key(url)}'

    @staticmethod
    def _web_text_looks_like_broccoli_external_prompt(text: str) -> bool:
        text = str(text or '')
        return (
            'Broccoli prepared this request for an external AI target' in text
            or '[Broccoli context]' in text
            or '[Final user request]' in text
        )

    @classmethod
    def _web_display_text_from_broccoli_external_prompt(cls, text: str) -> str:
        text = str(text or '').strip()
        if not cls._web_text_looks_like_broccoli_external_prompt(text):
            return text

        def section(label: str) -> str:
            pattern = re.compile(
                r'(?:^|\n|---\s*)\[' + re.escape(label) + r'\]\s*'
                r'([\s\S]*?)(?=(?:\n\s*---\s*(?:\n|\[)|\n\s*\[[A-Z][^\]]+\]\s*|$))',
                re.IGNORECASE,
            )
            match = pattern.search(text)
            return re.sub(r'\n{3,}', '\n\n', match.group(1)).strip() if match else ''

        final_request = section('Final user request')
        if final_request:
            return final_request
        user_sections = [
            re.sub(r'\n{3,}', '\n\n', match.group(1)).strip()
            for match in re.finditer(
                r'(?:^|\n|---\s*)\[(?:User|Human)\]\s*'
                r'([\s\S]*?)(?=(?:\n\s*---\s*(?:\n|\[)|\n\s*\[[A-Z][^\]]+\]\s*|$))',
                text,
                re.IGNORECASE,
            )
            if str(match.group(1) or '').strip()
        ]
        if user_sections:
            return user_sections[-1]
        match = re.search(r'User request:\s*([\s\S]*?)(?=(?:\n\s*\n|$))', text, re.IGNORECASE)
        if match:
            return re.sub(r'\n{3,}', '\n\n', match.group(1)).strip()
        return '\n'.join(text.splitlines()[:12]).strip()

    def _web_conversation_capture_quality(self, capture: dict) -> dict:
        capture = capture if isinstance(capture, dict) else {}
        raw_messages = capture.get('messages') if isinstance(capture.get('messages'), list) else []
        raw_has_external_prompt = any(
            isinstance(item, dict)
            and (
                bool(item.get('_external_prompt') or item.get('external_prompt'))
                or self._web_text_looks_like_broccoli_external_prompt(str(item.get('content', '') or ''))
            )
            for item in raw_messages
        )
        normalized = self._normalize_web_conversation_capture(capture)
        messages = [item for item in normalized.get('messages', []) if isinstance(item, dict)]
        assistant_messages = [item for item in messages if str(item.get('role', '') or '') == 'assistant']
        user_messages = [item for item in messages if str(item.get('role', '') or '') == 'user']
        assistant_chars = sum(len(str(item.get('content', '') or '')) for item in assistant_messages)
        user_chars = sum(len(str(item.get('content', '') or '')) for item in user_messages)
        bad_external_prompt_only = bool(raw_has_external_prompt and user_messages and not assistant_messages)
        parser_source = str(capture.get('parser_source', '') or normalized.get('parser_source', '') or '').strip()
        parser_fallback_used = bool(capture.get('parser_fallback_used') or normalized.get('parser_fallback_used'))
        parser_quality = capture.get('parser_quality') if isinstance(capture.get('parser_quality'), dict) else normalized.get('parser_quality') if isinstance(normalized.get('parser_quality'), dict) else {}
        strict_parser_used = bool(parser_source and 'strict' in parser_source and not parser_fallback_used)
        score = assistant_chars + len(assistant_messages) * 10000 + len(messages) * 100
        if strict_parser_used:
            score += 8000
        if parser_fallback_used:
            score -= 5000
        if bad_external_prompt_only:
            score -= 50000
        return {
            'message_count': len(messages),
            'assistant_count': len(assistant_messages),
            'assistant_chars': assistant_chars,
            'user_count': len(user_messages),
            'user_chars': user_chars,
            'raw_has_external_prompt': raw_has_external_prompt,
            'bad_external_prompt_only': bad_external_prompt_only,
            'parser_source': parser_source,
            'parser_fallback_used': parser_fallback_used,
            'parser_quality': parser_quality,
            'strict_parser_used': strict_parser_used,
            'score': score,
        }

    def _web_conversation_capture_should_replace_cached(self, incoming: dict, previous: dict) -> bool:
        incoming_quality = self._web_conversation_capture_quality(incoming)
        previous_quality = self._web_conversation_capture_quality(previous)
        if incoming_quality.get('bad_external_prompt_only') and previous_quality.get('assistant_count', 0) > 0:
            return False
        if (
                incoming_quality.get('raw_has_external_prompt')
                and incoming_quality.get('assistant_count', 0) == 0
                and previous_quality.get('assistant_count', 0) > 0):
            return False
        if (
                incoming_quality.get('raw_has_external_prompt')
                and previous_quality.get('assistant_chars', 0) > 0
                and incoming_quality.get('assistant_chars', 0) + 240 < previous_quality.get('assistant_chars', 0)
                and incoming_quality.get('message_count', 0) <= previous_quality.get('message_count', 0)):
            return False
        if (
                incoming_quality.get('parser_fallback_used')
                and previous_quality.get('strict_parser_used')
                and previous_quality.get('assistant_count', 0) > 0
                and incoming_quality.get('message_count', 0) <= previous_quality.get('message_count', 0)
                and incoming_quality.get('assistant_chars', 0) <= previous_quality.get('assistant_chars', 0) + 240):
            return False
        if (
                incoming_quality.get('score', 0) + 12000 < previous_quality.get('score', 0)
                and previous_quality.get('assistant_count', 0) > 0
                and incoming_quality.get('message_count', 0) <= previous_quality.get('message_count', 0)):
            return False
        return True

    def _normalize_web_conversation_capture(self, payload) -> dict:
        capture = payload if isinstance(payload, dict) else {}
        now = current_chat_timestamp()
        messages = []
        seen = set()
        for item in capture.get('messages', []) if isinstance(capture.get('messages'), list) else []:
            if not isinstance(item, dict):
                continue
            role = str(item.get('role', '')).strip().lower()
            if role not in {'user', 'assistant'}:
                continue
            content = re.sub(r'\n{3,}', '\n\n', str(item.get('content', '') or '')).strip()
            if not content:
                continue
            is_external_prompt = bool(
                item.get('_external_prompt')
                or item.get('external_prompt')
                or self._web_text_looks_like_broccoli_external_prompt(content)
            )
            if role == 'user' and is_external_prompt:
                content = self._web_display_text_from_broccoli_external_prompt(content)
                if not content:
                    continue
            if role == 'assistant' and is_external_prompt:
                continue
            key = (role, content)
            if key in seen:
                continue
            seen.add(key)
            source = str(item.get('source', '') or capture.get('source', '') or '').strip()
            message = {'role': role, 'content': content, 'timestamp': now}
            if is_external_prompt:
                message['_external_prompt'] = True
            if source:
                message['source'] = source[:40]
            messages.append(message)
        title = sanitize_conversation_title(
            capture.get('title', '') or conversation_title_from_messages(messages, fallback='Web conversation')
        )
        source = str(capture.get('source', '') or '').strip()
        if not source:
            for message in messages:
                source = str(message.get('source', '') or '').strip()
                if source:
                    break
        normalized_payload = {
            'title': title,
            'url': str(capture.get('url', '') or '').strip(),
            'source': source,
            'captured_at': str(capture.get('captured_at', '') or '').strip(),
            'messages': messages,
        }
        parser_source = str(capture.get('parser_source', '') or '').strip()
        if parser_source:
            normalized_payload['parser_source'] = parser_source
        if 'parser_fallback_used' in capture:
            normalized_payload['parser_fallback_used'] = bool(capture.get('parser_fallback_used'))
        if isinstance(capture.get('parser_quality'), dict):
            normalized_payload['parser_quality'] = dict(capture.get('parser_quality') or {})
        return normalized_payload

    @staticmethod
    def _web_capture_source_label(capture: dict) -> str:
        source = str((capture or {}).get('source', '') or '').strip()
        if source:
            return source
        url = str((capture or {}).get('url', '') or '').strip()
        try:
            host = urlparse(url).netloc
            if host:
                return host
        except Exception:
            pass
        return 'Web'

    def _web_capture_markdown_for_share(self, capture: dict) -> str:
        original_assets = capture.get('assets') if isinstance(capture, dict) and isinstance(capture.get('assets'), list) else []
        capture = self._normalize_web_conversation_capture(capture)
        if original_assets:
            capture['assets'] = original_assets
        messages = list(capture.get('messages') or [])
        if not messages:
            return ''
        title = str(capture.get('title', '') or 'Web conversation').strip()
        source = self._web_capture_source_label(capture)
        url = str(capture.get('url', '') or '').strip()
        header = [f'# {title}', '', f'Source: {source}']
        if url:
            header.append(f'URL: {url}')
        assets = capture.get('assets') if isinstance(capture.get('assets'), list) else []
        if assets:
            header.append('')
            header.append('Assets:')
            for asset in assets[:24]:
                if not isinstance(asset, dict):
                    continue
                name = str(asset.get('name', '') or asset.get('type', '') or 'asset').strip()
                asset_url = str(asset.get('url', '') or '').strip()
                if asset_url:
                    header.append(f'- {name}: {asset_url}')
                elif name:
                    header.append(f'- {name}')
        header.append('')
        return ('\n'.join(header) + render_chat_history_markdown(messages)).strip()

    def _share_web_capture_markdown(self, tab_index: int, capture: dict):
        original_assets = capture.get('assets') if isinstance(capture, dict) and isinstance(capture.get('assets'), list) else []
        capture = self._normalize_web_conversation_capture(capture)
        if original_assets:
            capture['assets'] = original_assets
        markdown = self._web_capture_markdown_for_share(capture)
        if not markdown:
            self._show_broccoli_message('Share', 'No current page conversation text was detected.')
            return
        source = self._web_capture_source_label(capture)
        self._show_share_text_dialog(
            f'Full Markdown - {source}',
            markdown,
            subtitle=f'Captured from current {source} URL. Edit before copying or sending.',
        )

    def _start_web_capture_task_capsule_share(self, tab_index: int, capture: dict):
        original_assets = capture.get('assets') if isinstance(capture, dict) and isinstance(capture.get('assets'), list) else []
        capture = self._normalize_web_conversation_capture(capture)
        if original_assets:
            capture['assets'] = original_assets
        markdown = self._web_capture_markdown_for_share(capture)
        if not markdown:
            self._show_broccoli_message('Task Capsule', 'No current page conversation text was detected.')
            return
        profile = load_active_settings_profile()
        profile_name = str(profile.get('name', '') or 'Active API profile').strip()
        model = str(profile.get('model', '') or '').strip()
        choice = ask_broccoli_message(
            self,
            'Task Capsule',
            (
                'Task Capsule will be generated with API profile:\n'
                f'{profile_name}' + (f' / {model}' if model else '') +
                '\n\nIt will not use the AI model open in this web page.'
            ),
            ['Generate', 'Cancel'],
            default_button_text='Generate',
            size=QSize(520, 230),
        )
        if choice != 'Generate':
            return
        source = self._web_capture_source_label(capture)
        self._start_task_capsule_share_from_markdown(
            markdown,
            dialog_title=f'Task Capsule - {source}',
            dialog_subtitle=(
                f'Generated via API profile: {profile_name}'
                + (f' / {model}' if model else '')
                + '. Edit before sending.'
            ),
            source_meta={
                'source': source,
                'title': str(capture.get('title', '') or ''),
                'url': str(capture.get('url', '') or ''),
            },
        )

    def _show_web_conversation_sync_menu(self, tab_index: int, payload):
        original_assets = payload.get('assets') if isinstance(payload, dict) and isinstance(payload.get('assets'), list) else []
        capture = self._normalize_web_conversation_capture(payload)
        if original_assets:
            capture['assets'] = original_assets
        messages = capture.get('messages', [])
        source_key = self._web_conversation_source_key(tab_index)
        bindings = load_web_conversation_bindings()
        linked_path = str(bindings.get(source_key, '') or '').strip()
        linked_exists = bool(linked_path and os.path.exists(linked_path))
        active_exists = bool(self._active_conversation_path and os.path.exists(self._active_conversation_path))
        panel, dock = self._external_prompt_panel_for_index(tab_index)
        forward_views = self._selected_non_active_web_views(panel, dock)
        try:
            selected_views = dock.selected_target_views(panel) if panel is not None and dock is not None and hasattr(dock, 'selected_target_views') else []
        except Exception:
            selected_views = []
        selected_views = [view for view in selected_views if view is not None]

        menu = style_broccoli_context_menu(QMenu(self))
        title_text = f"{len(messages)} messages detected" if messages else 'No current page messages detected'
        title_action = QAction(title_text, menu)
        title_action.setEnabled(False)
        menu.addAction(title_action)
        menu.addSeparator()

        forward_action = QAction("Send selected tabs' latest replies here", menu)
        forward_action.setEnabled(bool(forward_views))
        forward_action.triggered.connect(lambda _checked=False, tab=tab_index: self._forward_selected_web_replies_to_active(tab))
        menu.addAction(forward_action)
        cross_forward_action = QAction("Cross-send latest replies between selected tabs", menu)
        cross_forward_action.setEnabled(len(selected_views) >= 2)
        cross_forward_action.triggered.connect(lambda _checked=False, tab=tab_index: self._cross_forward_selected_web_replies(tab))
        menu.addAction(cross_forward_action)
        menu.addSeparator()

        full_md_action = QAction('Share Full Markdown...', menu)
        full_md_action.setEnabled(bool(messages))
        full_md_action.triggered.connect(
            lambda _checked=False, tab=tab_index, cap=capture: self._share_web_capture_markdown(tab, cap)
        )
        menu.addAction(full_md_action)

        capsule_action = QAction('Generate Task Capsule via API profile...', menu)
        capsule_action.setEnabled(bool(messages))
        capsule_action.triggered.connect(
            lambda _checked=False, tab=tab_index, cap=capture: self._start_web_capture_task_capsule_share(tab, cap)
        )
        menu.addAction(capsule_action)
        menu.addSeparator()

        new_action = QAction('New API history', menu)
        new_action.setEnabled(bool(messages))
        new_action.triggered.connect(lambda _checked=False: self._save_web_conversation_new(source_key, capture))
        menu.addAction(new_action)

        update_action = QAction('Update linked API history', menu)
        update_action.setEnabled(bool(messages) and linked_exists)
        update_action.triggered.connect(lambda _checked=False, path=linked_path: self._save_web_conversation_update(path, source_key, capture))
        menu.addAction(update_action)

        append_action = QAction('Append to current API history', menu)
        append_action.setEnabled(bool(messages) and active_exists)
        append_action.triggered.connect(lambda _checked=False: self._save_web_conversation_append(self._active_conversation_path, source_key, capture))
        menu.addAction(append_action)

        records = list_conversation_records()
        if messages and records:
            choose_menu = menu.addMenu('Choose API history...')
            for record in records[:24]:
                label = str(record.get('title', '') or os.path.basename(record.get('path', ''))).strip()
                if len(label) > 48:
                    label = label[:45].rstrip() + '...'
                action = QAction(label, choose_menu)
                action.setToolTip(str(record.get('path', '')))
                action.triggered.connect(
                    lambda _checked=False, path=record.get('path', ''): self._save_web_conversation_append(path, source_key, capture)
                )
                choose_menu.addAction(action)

        anchor = self.web_conversation_sync_button
        menu.exec(anchor.mapToGlobal(QPoint(0, anchor.height() + 6)))

    @staticmethod
    def _web_view_label(view: QWebEngineView) -> str:
        try:
            host = view.url().host()
            if host:
                if host.endswith('claude.ai'):
                    return 'Claude'
                if host.endswith('chatgpt.com') or host.endswith('openai.com'):
                    return 'ChatGPT'
                if host.endswith('gemini.google.com'):
                    return 'Gemini'
                return host
        except Exception:
            pass
        return 'Web'

    @staticmethod
    def _truncate_forward_text(text: str, limit: int, *, from_tail: bool = False) -> str:
        text = str(text or '').strip()
        limit = max(0, int(limit))
        if limit <= 0:
            return ''
        if len(text) <= limit:
            return text
        if from_tail:
            return '[Older content omitted; showing the latest text]\n' + text[-limit:].lstrip()
        return text[:limit].rstrip() + '\n[truncated]'

    def _forward_record_from_capture(self, capture: dict, view: QWebEngineView) -> dict | None:
        capture = self._normalize_web_conversation_capture(capture)
        raw_source = str(capture.get('source', '') or '').strip()
        source = raw_source or self._web_view_label(view)
        if source == 'Web':
            source = self._web_view_label(view)
        messages = [msg for msg in capture.get('messages', []) if isinstance(msg, dict)]
        latest_assistant = ''
        has_user_message = any(str(message.get('role', '')).strip().lower() == 'user' for message in messages)
        use_structured_latest_reply = raw_source and raw_source != 'Web' and has_user_message
        if use_structured_latest_reply:
            for message in reversed(messages):
                if str(message.get('role', '')).strip().lower() == 'assistant':
                    latest_assistant = str(message.get('content', '') or '').strip()
                    break
        if use_structured_latest_reply and latest_assistant:
            return {
                'source': source,
                'url': str(capture.get('url', '') or '').strip(),
                'content': self._truncate_forward_text(
                    latest_assistant,
                    WEB_REPLY_FORWARD_SOURCE_CHAR_LIMIT,
                    from_tail=False,
                ),
                'fallback': False,
            }
        full_parts = []
        for message in messages:
            content = str(message.get('content', '') or '').strip()
            if not content:
                continue
            role = str(message.get('role', '') or 'content').strip().title()
            full_parts.append(f'{role}: {content}')
        full_text = '\n\n'.join(full_parts).strip()
        if not full_text:
            return None
        return {
            'source': source,
            'url': str(capture.get('url', '') or '').strip(),
            'content': self._truncate_forward_text(
                full_text,
                WEB_REPLY_FORWARD_SOURCE_CHAR_LIMIT,
                from_tail=True,
            ),
            'fallback': True,
        }

    def _forward_record_from_latest_payload(self, payload: dict, view: QWebEngineView) -> dict | None:
        payload = payload if isinstance(payload, dict) else {}
        content = str(payload.get('content', '') or '').strip()
        if not content:
            return None
        raw_source = str(payload.get('source', '') or '').strip()
        source = raw_source or self._web_view_label(view)
        if source == 'Web':
            source = self._web_view_label(view)
        return {
            'source': source,
            'url': str(payload.get('url', '') or '').strip(),
            'content': self._truncate_forward_text(
                content,
                WEB_REPLY_FORWARD_SOURCE_CHAR_LIMIT,
                from_tail=False,
            ),
            'fallback': bool(payload.get('fallback')),
        }

    def _capture_forward_record_from_view(self, view: QWebEngineView, callback):
        capture = self._web_conversation_cached_capture_for_view(view)
        callback(view, self._forward_record_from_capture(capture, view) if isinstance(capture, dict) else None)

    def _build_forwarded_web_replies_prompt(self, records: list[dict], *, cross_send: bool = False) -> str:
        blocks = []
        total = 0
        for record in records:
            source = str(record.get('source', '') or 'Web').strip()
            content = str(record.get('content', '') or '').strip()
            if not content:
                continue
            remaining = WEB_REPLY_FORWARD_TOTAL_CHAR_LIMIT - total
            if remaining <= 0:
                break
            if len(content) > remaining:
                content = self._truncate_forward_text(content, remaining, from_tail=bool(record.get('fallback')))
            total += len(content)
            title = f'[{source} captured text]' if record.get('fallback') else f'[{source} latest reply]'
            url = str(record.get('url', '') or '').strip()
            header = title + (f'\nURL: {url}' if url else '')
            blocks.append(f'{header}\n{content}')
        if not blocks:
            return ''
        if cross_send:
            intro = (
                'Use the following latest replies from the other selected AI/web tabs as context. '
                'Summarize them into your own answer, compare important differences, and continue the discussion.'
            )
        else:
            intro = (
                'Use the following text forwarded from other selected AI/web tabs as context. '
                'Each block includes its source. Respond to the combined context.'
            )
        return (
            intro + '\n\n'
            + '\n\n---\n\n'.join(blocks)
        )

    def _forward_selected_web_replies_to_active(self, tab_index: int):
        panel, dock = self._external_prompt_panel_for_index(int(tab_index))
        if panel is None or dock is None:
            return
        try:
            target_view = panel.active_view()
        except Exception:
            target_view = None
        source_views = self._selected_non_active_web_views(panel, dock)
        if target_view is None or not source_views:
            return
        activation_delay = 0
        if hasattr(panel, 'hold_views_active'):
            activation_delay = int(panel.hold_views_active([target_view, *source_views]) or 0)
        self.web_conversation_sync_button.setEnabled(False)
        state = {
            'remaining': len(source_views),
            'records': [],
        }

        def finish():
            self.web_conversation_sync_button.setEnabled(True)
            records = state.get('records', [])
            prompt = self._build_forwarded_web_replies_prompt(records)
            if not prompt:
                self.web_conversation_sync_button.setToolTip('No text was detected in the selected tabs.')
                return
            self._inject_text_to_web_view(target_view, prompt)
            QTimer.singleShot(
                850,
                lambda v=target_view: self._wait_then_click_web_send_button(
                    v,
                    timeout_ms=8000,
                    caller='web_forward',
                ),
            )

        def after_capture(view, record):
            if record is not None:
                state['records'].append(record)
            state['remaining'] = max(0, int(state.get('remaining', 0)) - 1)
            if state['remaining'] <= 0:
                finish()

        def capture_one(view):
            self._capture_forward_record_from_view(view, after_capture)

        for offset, view in enumerate(source_views):
            QTimer.singleShot(activation_delay + offset * 120, lambda v=view: capture_one(v))

    def _cross_forward_selected_web_replies(self, tab_index: int):
        panel, dock = self._external_prompt_panel_for_index(int(tab_index))
        if panel is None or dock is None:
            return
        try:
            selected_views = dock.selected_target_views(panel) if hasattr(dock, 'selected_target_views') else []
        except Exception:
            selected_views = []
        selected_views = [view for view in selected_views if view is not None]
        if len(selected_views) < 2:
            return
        activation_delay = 0
        if hasattr(panel, 'hold_views_active'):
            activation_delay = int(panel.hold_views_active(selected_views) or 0)
        self.web_conversation_sync_button.setEnabled(False)
        state = {
            'remaining': len(selected_views),
            'records_by_view': {},
        }

        def finish():
            self.web_conversation_sync_button.setEnabled(True)
            records_by_view = state.get('records_by_view', {})
            if len(records_by_view) < 2:
                self.web_conversation_sync_button.setToolTip('Not enough text was detected in the selected tabs.')
                return
            for offset, target_view in enumerate(selected_views):
                source_records = [
                    record
                    for view, record in records_by_view.items()
                    if view is not target_view and record is not None
                ]
                prompt = self._build_forwarded_web_replies_prompt(source_records, cross_send=True)
                if not prompt:
                    continue
                delay = offset * 650
                QTimer.singleShot(delay, lambda v=target_view, p=prompt: self._inject_text_to_web_view(v, p))
                QTimer.singleShot(
                    delay + 900,
                    lambda v=target_view: self._wait_then_click_web_send_button(
                        v,
                        timeout_ms=8000,
                        caller='web_cross_forward',
                    ),
                )

        def after_capture(view, record):
            if record is not None:
                state['records_by_view'][view] = record
            state['remaining'] = max(0, int(state.get('remaining', 0)) - 1)
            if state['remaining'] <= 0:
                finish()

        def capture_one(view):
            self._capture_forward_record_from_view(view, after_capture)

        for offset, view in enumerate(selected_views):
            QTimer.singleShot(activation_delay + offset * 120, lambda v=view: capture_one(v))

    @staticmethod
    def _web_message_signature(message: dict) -> tuple[str, str]:
        return (
            str(message.get('role', '')).strip().lower(),
            re.sub(r'\s+', ' ', str(message.get('content', '') or '').strip()),
        )

    def _merge_web_conversation_messages(self, existing: list[dict], incoming: list[dict]) -> list[dict]:
        existing = [msg for msg in existing or [] if normalize_chat_history_message(msg)]
        incoming = [msg for msg in incoming or [] if normalize_chat_history_message(msg)]
        if not existing:
            return incoming
        if not incoming:
            return existing
        existing_sig = [self._web_message_signature(msg) for msg in existing]
        incoming_sig = [self._web_message_signature(msg) for msg in incoming]
        max_overlap = min(len(existing_sig), len(incoming_sig))
        overlap = 0
        for size in range(max_overlap, 0, -1):
            if existing_sig[-size:] == incoming_sig[:size]:
                overlap = size
                break
        if overlap:
            return existing + incoming[overlap:]
        if len(incoming_sig) >= len(existing_sig) and incoming_sig[:len(existing_sig)] == existing_sig:
            return incoming
        return existing + incoming

    def _save_web_conversation_record(self,
                                      path: str,
                                      capture: dict,
                                      messages: list[dict],
                                      source_key: str,
                                      bind: bool = True) -> dict | None:
        if not path or not messages:
            return None
        now = datetime.datetime.now().isoformat(timespec='seconds')
        existing = load_conversation_record(path)
        title_with_source = web_conversation_title_with_source(
            capture.get('title') or conversation_title_from_messages(messages, fallback='Web conversation'),
            capture.get('source', ''),
        )
        record = existing if existing is not None else {
            'id': Path(path).stem.split('_', 1)[0],
            'title': title_with_source,
            'created_at': now,
            'messages': [],
        }
        record['messages'] = list(messages)
        record['title'] = sanitize_conversation_title(record.get('title') or title_with_source)
        record['updated_at'] = now
        record['rendered_markdown'] = render_chat_history_markdown(messages)
        saved = write_conversation_record(path, record)
        if bind:
            bindings = load_web_conversation_bindings()
            bindings[source_key] = saved['path']
            save_web_conversation_bindings(bindings)
        self._active_conversation_path = saved['path']
        save_chat_history_messages(saved['messages'])
        self.render_final_output(saved['rendered_markdown'], history_messages=saved['messages'])
        self._refresh_history_panel()
        self._refresh_links_panel()
        self._refresh_outputs_panel()
        self._refresh_branch_state_from_current_conversation()
        return saved

    def _save_web_conversation_new(self, source_key: str, capture: dict):
        messages = list(capture.get('messages') or [])
        convo_id = datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
        title = web_conversation_title_with_source(
            capture.get('title') or conversation_title_from_messages(messages, fallback='Web conversation'),
            capture.get('source', ''),
        )
        filename = f"{convo_id}_{sanitize_conversation_filename(title)}.json"
        path = os.path.join(CONVERSATIONS_DIR, filename)
        suffix = 2
        while os.path.exists(path):
            filename = f"{convo_id}_{sanitize_conversation_filename(title)}-{suffix}.json"
            path = os.path.join(CONVERSATIONS_DIR, filename)
            suffix += 1
        self._save_web_conversation_record(path, capture, messages, source_key, bind=True)

    def _save_web_conversation_update(self, path: str, source_key: str, capture: dict):
        if not path:
            return
        self._save_web_conversation_record(path, capture, list(capture.get('messages') or []), source_key, bind=True)

    def _save_web_conversation_append(self, path: str, source_key: str, capture: dict):
        if not path:
            return
        record = load_conversation_record(path)
        existing_messages = list(record.get('messages', [])) if record else []
        merged = self._merge_web_conversation_messages(existing_messages, list(capture.get('messages') or []))
        self._save_web_conversation_record(path, capture, merged, source_key, bind=True)

    def _prepare_web_external_attachments(self, dock: ExternalPromptDock) -> tuple[list, list]:
        direct_attachments = []
        retrieval_documents = []
        for item in dock.attachment_items():
            path = str(item.get('path', '')).strip()
            if not path or not os.path.exists(path):
                continue
            use_embedding = bool(item.get('use_embedding'))
            if use_embedding and attachment_supports_embedding(path):
                extracted = extract_attachment_text(path, allow_ocr=True, limit_chars=None)
                if extracted and str(extracted.get('content', '')).strip():
                    retrieval_documents.append({
                        'name': extracted.get('name') or os.path.basename(path),
                        'content': extracted.get('content', ''),
                    })
                    continue
            encoded = _encode_attachment_file(path)
            if encoded:
                direct_attachments.append(encoded)
        return direct_attachments, retrieval_documents

    def _build_web_external_prompt(self, raw_question: str, dock: ExternalPromptDock, skip_retrieval: bool = False) -> tuple[str, list[dict], list]:
        full_history_messages = get_current_chat_history_messages()
        history_messages, selected_message_indices = self._filter_history_messages_by_branch(full_history_messages)
        attachments, retrieval_documents = self._prepare_web_external_attachments(dock)
        if skip_retrieval:
            retrieval_documents = []
        webfetch_pages = self._selected_webfetch_pages()
        webfetch_full_text_blocks = []
        if webfetch_pages and not skip_retrieval:
            webfetch_documents = webfetch_documents_from_pages(webfetch_pages)
            if self._webfetch_context_use_embedding_enabled():
                retrieval_documents.extend(webfetch_documents)
            else:
                webfetch_full_text_blocks.extend(
                    f"[Web page: {doc.get('name', 'Web page')}]\n{doc.get('content', '')}"
                    for doc in webfetch_documents
                    if str(doc.get('content', '')).strip()
                )

        api_key, endpoint = load_runtime_openai_client_config()
        modelnow = read_text_file(BasePath + 'modelnow.txt', DEFAULT_MODEL)
        timeout = load_saved_timeout()
        attachment_context = ''
        if retrieval_documents and not skip_retrieval:
            attachment_context, _refs = self._build_attachment_retrieval_context(
                raw_question,
                retrieval_documents,
                api_key,
                endpoint,
                timeout,
            )

        context_blocks = []
        active_profile = load_active_settings_profile()
        if not skip_retrieval and read_text_file(BasePath + 'history.txt', '0') == '1':
            history_context = self._build_active_history_context(
                raw_question,
                history_messages,
                api_key,
                endpoint,
                modelnow,
                timeout,
                selected_message_indices=selected_message_indices,
            )
            if history_context:
                context_blocks.append(history_context)
        if not skip_retrieval:
            external_context = self._build_external_context_prompt_context(raw_question)
            if external_context:
                context_blocks.append(external_context)
        if not skip_retrieval and active_profile.get('remember_memory', True):
            memory_context = self._build_saved_memory_prompt_context(raw_question)
            if memory_context:
                context_blocks.append(memory_context)
        if not skip_retrieval:
            vision_context = self._build_background_vision_prompt_context()
            if vision_context:
                context_blocks.append(vision_context)
        if attachment_context:
            context_blocks.append(attachment_context)

        direct_text_blocks = []
        for item in attachments:
            items = item if isinstance(item, list) else [item]
            for att in items:
                if isinstance(att, dict) and att.get('kind') == 'text' and str(att.get('content', '')).strip():
                    direct_text_blocks.append(f"[Attached file: {att.get('name', 'Attachment')}]\n{att.get('content', '')}")

        final_parts = []
        context_text = '\n\n'.join(block for block in context_blocks if str(block).strip()).strip()
        if context_text:
            final_parts.append('Use the following context if relevant:\n' + context_text)
        if direct_text_blocks:
            final_parts.append('Attached text:\n' + '\n\n'.join(direct_text_blocks))
        if webfetch_full_text_blocks:
            final_parts.append('Web page content:\n' + '\n\n'.join(webfetch_full_text_blocks))
        if raw_question.strip() or not skip_retrieval:
            final_parts.append('User request:\n' + raw_question)
        base_prompt = '\n\n---\n\n'.join(final_parts).strip()
        if skip_retrieval and not raw_question.strip() and not base_prompt:
            return '', [], attachments
        return dock.build_mode_prompt(base_prompt), [], attachments

    def SendExternalPromptDockX(self, tab_index: int):
        panel, dock = self._external_prompt_panel_for_index(int(tab_index))
        if dock is not None and dock.mode_index() == 2 and not dock.target_lang_combo.currentText().strip():
            dock.target_lang_combo.setFocus()
            return
        view = panel.active_view() if panel is not None else None
        selected_views = dock.selected_target_views(panel) if panel is not None and dock is not None and hasattr(dock, 'selected_target_views') else []
        if (
            view is not None
            and dock is not None
            and len(selected_views) == 1
            and selected_views[0] is view
            and self._is_claude_web_view(view)
        ):
            self.SendClaudeDockX(tab_index)
            return
        self.SendWebX(tab_index=tab_index, force_auto_send=True)

    def SendClaudeDockX(self, tab_index: int):
        index = int(tab_index)
        panel, dock = self._external_prompt_panel_for_index(index)
        if panel is None or dock is None:
            return
        view = panel.active_view()
        if view is None:
            return
        globals_store = load_settings_store().get('globals', {})
        raw_question = dock.prompt_text().strip()
        has_pending_attachments = bool(
            getattr(dock, 'attachment_tray', None) is not None
            and dock.attachment_tray.has_cards()
        )
        if not raw_question and not has_pending_attachments:
            try:
                raw_question = subprocess.check_output('pbpaste', env={'LANG': 'en_US.UTF-8'}).decode('utf-8').strip()
                if raw_question:
                    dock.prompt_edit.setPlainText(raw_question)
            except Exception:
                pass
        if not raw_question and not has_pending_attachments:
            return
        activation_delay = 0
        if hasattr(panel, 'hold_views_active'):
            activation_delay = int(panel.hold_views_active([view]) or 0)

        skip_retrieval = bool(globals_store.get('skip_retrieval_for_blank_prompt', False)) and not raw_question and has_pending_attachments
        final_prompt, _attachment_records, direct_attachments = self._build_web_external_prompt(
            raw_question,
            dock,
            skip_retrieval=skip_retrieval,
        )
        image_items = self._collect_direct_image_attachments(direct_attachments)
        upload_paths = self._collect_web_upload_paths(dock)
        clear_after_send = self._clear_attachments_after_send_enabled()

        def wait_then_submit(v=view, d=dock):
            if clear_after_send:
                d.clear_attachments()
            self._wait_then_click_web_send_button(v, caller='claude_dock')

        def wait_for_manual_claude_presence(v=view, d=dock, paths=None):
            names = [os.path.basename(str(path)) for path in (paths or []) if str(path).strip()]
            QTimer.singleShot(
                1600,
                lambda vv=v, nn=names, dd=d: self._wait_for_web_attachment_presence(
                    vv,
                    nn,
                    timeout_ms=30000,
                    callback=lambda ok, vvv=vv, ddd=dd: (
                        wait_then_submit(vvv, ddd) if ok else self._wait_then_click_web_send_button(
                            vvv,
                            timeout_ms=12000,
                            caller='claude_dock_attachment_fallback',
                        )
                    ),
                ),
            )

        QTimer.singleShot(activation_delay, lambda v=view, prompt=final_prompt: self._inject_text_to_web_view(v, prompt))
        if upload_paths:
            QTimer.singleShot(
                activation_delay + 260,
                lambda v=view, paths=list(upload_paths): self._activate_claude_composer(
                    v,
                    callback=lambda vv=v, pp=list(paths): self._inject_files_to_claude_by_drop(
                        vv,
                        pp,
                        fallback_callback=lambda vvv=vv, ppp=list(pp): wait_for_manual_claude_presence(vvv, dock, ppp),
                        callback=lambda vvv=vv, ppp=list(pp): wait_for_manual_claude_presence(vvv, dock, ppp),
                    ),
                ),
            )
        elif image_items:
            QTimer.singleShot(
                activation_delay + 220,
                lambda v=view, imgs=image_items: self._inject_images_to_web_view(
                    v,
                    imgs,
                    callback=lambda vv=v: wait_then_submit(vv, dock),
                ),
            )
        else:
            QTimer.singleShot(activation_delay + 850, lambda v=view: wait_then_submit(v, dock))
        dock.clear_prompt()

    def SendWebX(self, tab_index: int | None = None, force_auto_send: bool = False):
        index = self.stacked_widget.currentIndex() if tab_index is None else int(tab_index)
        panel, dock = self._external_prompt_panel_for_index(index)
        if panel is None or dock is None:
            return
        globals_store = load_settings_store().get('globals', {})
        raw_question = dock.prompt_text().strip()
        allow_blank_with_attachments = bool(globals_store.get('allow_blank_prompt_with_attachments', False))
        force_blank_prompt_once = bool(getattr(self, '_force_external_blank_prompt_once', False))
        self._force_external_blank_prompt_once = False
        has_pending_attachments = bool(
            getattr(dock, 'attachment_tray', None) is not None
            and dock.attachment_tray.has_cards()
        )
        can_send_blank_prompt = (
            allow_blank_with_attachments or force_blank_prompt_once or bool(force_auto_send)
        ) and has_pending_attachments
        if not raw_question and not can_send_blank_prompt:
            try:
                raw_question = subprocess.check_output('pbpaste', env={'LANG': 'en_US.UTF-8'}).decode('utf-8').strip()
                if raw_question:
                    dock.prompt_edit.setPlainText(raw_question)
            except Exception:
                pass
        if not raw_question and not can_send_blank_prompt:
            return
        skip_retrieval = bool(globals_store.get('skip_retrieval_for_blank_prompt', False)) and not raw_question and can_send_blank_prompt
        final_prompt, _attachment_records, direct_attachments = self._build_web_external_prompt(
            raw_question,
            dock,
            skip_retrieval=skip_retrieval,
        )
        views = dock.selected_target_views(panel) if hasattr(dock, 'selected_target_views') else [panel.active_view()]
        if not views:
            return
        activation_delay = 0
        if hasattr(panel, 'hold_views_active'):
            activation_delay = int(panel.hold_views_active(views) or 0)
        image_items = self._collect_direct_image_attachments(direct_attachments)
        upload_paths = self._collect_web_upload_paths(dock)
        force_web_auto_send_once = bool(getattr(self, '_force_web_auto_send_once', False))
        self._force_web_auto_send_once = False
        auto_send = bool(force_auto_send) or self._web_auto_send_after_inject_enabled() or force_web_auto_send_once
        clear_after_send = self._clear_attachments_after_send_enabled()

        def after_attachment_handoff(v, d, click):
            log_broccoli_claude(f'attachment handoff confirmed; auto_send={click}')
            if clear_after_send:
                d.clear_attachments()
            if click:
                self._wait_then_click_web_send_button(v, caller='web_dock_attachment')

        def after_attachment_timeout():
            show_broccoli_message(
                self,
                'Attachment upload',
                'The web page did not confirm that the attachment was added. The attachment was kept in Broccoli.',
            )

        def after_claude_detection_timeout(v, click):
            log_broccoli_claude(f'attachment detection timeout; auto_send={click}')
            if click:
                self._wait_then_click_web_send_button(
                    v,
                    timeout_ms=12000,
                    caller='web_dock_claude_attachment_timeout',
                )
            else:
                after_attachment_timeout()

        def wait_for_claude_presence(v, d, paths, click, on_failure):
            names = [os.path.basename(str(path)) for path in paths or [] if str(path).strip()]
            QTimer.singleShot(
                1600,
                lambda vv=v, nn=names, dd=d, cc=click, fail=on_failure: self._wait_for_web_attachment_presence(
                    vv,
                    nn,
                    timeout_ms=30000,
                    callback=lambda ok, vvv=vv, ddd=dd, ccc=cc, fff=fail: (
                        after_attachment_handoff(vvv, ddd, ccc) if ok else fff()
                    ),
                ),
            )

        def start_claude_drop_first(v, d, paths, click):
            self._activate_claude_composer(
                v,
                callback=lambda vv=v, dd=d, pp=list(paths), cc=click: self._inject_files_to_claude_by_drop(
                    vv,
                    pp,
                    fallback_callback=lambda vvv=vv, ddd=dd, ppp=list(pp), ccc=cc: wait_for_claude_presence(
                        vvv,
                        ddd,
                        ppp,
                        ccc,
                        on_failure=lambda vvvv=vvv, cccc=ccc: after_claude_detection_timeout(vvvv, cccc),
                    ),
                    callback=lambda vvv=vv, ddd=dd, ppp=list(pp), ccc=cc: wait_for_claude_presence(
                        vvv,
                        ddd,
                        ppp,
                        ccc,
                        on_failure=lambda vvvv=vvv, cccc=ccc: after_claude_detection_timeout(vvvv, cccc),
                    ),
                ),
            )

        for offset, view in enumerate(views):
            delay = activation_delay + offset * 450
            QTimer.singleShot(delay, lambda v=view: self._inject_text_to_web_view(v, final_prompt))
            if self._is_claude_web_view(view) and upload_paths:
                QTimer.singleShot(
                    delay + 260,
                    lambda v=view, paths=list(upload_paths), click=auto_send: start_claude_drop_first(
                        v,
                        dock,
                        paths,
                        click,
                    ),
                )
            elif image_items:
                if self._is_grok_web_view(view) or self._is_perplexity_web_view(view):
                    QTimer.singleShot(
                        delay + 220,
                        lambda v=view, imgs=image_items, click=auto_send: self._activate_web_composer(
                            v,
                            callback=lambda vv=v, ii=imgs, cc=click: self._inject_images_to_web_view(
                                vv,
                                ii,
                                callback=lambda vvv=vv, ddd=dock, ccc=cc: after_attachment_handoff(vvv, ddd, ccc),
                            ),
                        ),
                    )
                else:
                    QTimer.singleShot(
                        delay + 220,
                        lambda v=view, imgs=image_items, click=auto_send: self._inject_images_to_web_view(
                            v,
                            imgs,
                            callback=lambda vv=v, ddd=dock, ccc=click: after_attachment_handoff(vv, ddd, ccc),
                        ),
                    )
            elif auto_send:
                QTimer.singleShot(
                    delay + 850,
                    lambda v=view: self._wait_then_click_web_send_button(
                        v,
                        timeout_ms=5000,
                        caller='web_dock',
                    ),
                )
        if clear_after_send and not upload_paths and not image_items and has_pending_attachments:
            dock.clear_attachments()
        dock.clear_prompt()

    def _collect_direct_image_attachments(self, direct_attachments: list) -> list[dict]:
        images = []
        for item in direct_attachments or []:
            items = item if isinstance(item, list) else [item]
            for att in items:
                if isinstance(att, dict) and att.get('kind') == 'image' and att.get('b64'):
                    images.append(att)
        return images

    def _collect_web_upload_paths(self, dock: ExternalPromptDock) -> list[str]:
        paths = []
        allowed = set(ATTACHMENT_IMAGE_EXTS) | {'.pdf', '.docx'}
        for path in dock.attachment_paths():
            ext = os.path.splitext(str(path))[1].lower()
            if ext in allowed and os.path.exists(str(path)):
                paths.append(str(path))
        return paths

    @staticmethod
    def _is_claude_web_view(view: QWebEngineView) -> bool:
        try:
            host = view.url().host().lower()
        except Exception:
            host = ''
        return host.endswith('claude.ai')

    @staticmethod
    def _is_grok_web_view(view: QWebEngineView) -> bool:
        try:
            host = view.url().host().lower()
        except Exception:
            host = ''
        return host.endswith('grok.com')

    @staticmethod
    def _is_perplexity_web_view(view: QWebEngineView) -> bool:
        try:
            host = view.url().host().lower()
        except Exception:
            host = ''
        return host.endswith('perplexity.ai')

    @staticmethod
    def _is_gemini_web_view(view: QWebEngineView) -> bool:
        try:
            host = view.url().host().lower()
        except Exception:
            host = ''
        return host.endswith('gemini.google.com')

    @staticmethod
    def _web_auto_send_after_inject_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('web_auto_send_after_inject', False))

    @staticmethod
    def _webfetch_context_use_embedding_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('webfetch_context_use_embedding', True))

    @staticmethod
    def _clear_attachments_after_send_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('clear_attachments_after_send', True))

    @staticmethod
    def _generated_output_context_use_embedding_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('generated_output_context_use_embedding', False))

    def _send_web_view_mouse_click(self, view: QWebEngineView, x: float, y: float):
        try:
            view_point = QPoint(int(x), int(y))
            target = view.childAt(view_point) or view.focusProxy() or view
            if target is not view:
                target_point = target.mapFrom(view, view_point)
            else:
                target_point = view_point
            local = QPointF(float(target_point.x()), float(target_point.y()))
            global_point = target.mapToGlobal(target_point)
            global_pos = QPointF(float(global_point.x()), float(global_point.y()))
            press = PyQt6.QtGui.QMouseEvent(
                QEvent.Type.MouseButtonPress,
                local,
                global_pos,
                Qt.MouseButton.LeftButton,
                Qt.MouseButton.LeftButton,
                Qt.KeyboardModifier.NoModifier,
            )
            release = PyQt6.QtGui.QMouseEvent(
                QEvent.Type.MouseButtonRelease,
                local,
                global_pos,
                Qt.MouseButton.LeftButton,
                Qt.MouseButton.NoButton,
                Qt.KeyboardModifier.NoModifier,
            )
            view.setFocus(Qt.FocusReason.MouseFocusReason)
            target.setFocus(Qt.FocusReason.MouseFocusReason)
            QApplication.sendEvent(target, press)
            QApplication.sendEvent(target, release)
        except Exception:
            pass

    def _send_web_view_cmd_return(self, view: QWebEngineView):
        log_broccoli_claude('sending Claude submit shortcut sequence')
        try:
            target = QApplication.focusWidget()
            if target is None or (target is not view and not view.isAncestorOf(target)):
                target = view.focusProxy() or view.childAt(QPoint(max(1, view.width() // 2), max(1, view.height() // 2))) or view
            log_broccoli_claude(f'shortcut target={type(target).__name__}')
            view.setFocus(Qt.FocusReason.ShortcutFocusReason)
            target.setFocus(Qt.FocusReason.ShortcutFocusReason)

            def send_qt_key(key, modifiers, label):
                log_broccoli_claude(f'Qt key event: {label}')
                press = PyQt6.QtGui.QKeyEvent(
                    QEvent.Type.KeyPress,
                    key,
                    modifiers,
                    '\r',
                )
                release = PyQt6.QtGui.QKeyEvent(
                    QEvent.Type.KeyRelease,
                    key,
                    modifiers,
                    '\r',
                )
                QApplication.sendEvent(target, press)
                QApplication.sendEvent(target, release)

            # On macOS Qt maps Command to ControlModifier; keep MetaModifier as a fallback for embedded Chromium.
            for qt_key_name, qt_key in (('Return', Qt.Key.Key_Return), ('Enter', Qt.Key.Key_Enter)):
                send_qt_key(qt_key, Qt.KeyboardModifier.ControlModifier, f'Command+{qt_key_name}')
                send_qt_key(qt_key, Qt.KeyboardModifier.MetaModifier, f'Meta+{qt_key_name}')

            log_broccoli_claude('scheduling pyautogui submit fallback sequence')
            QTimer.singleShot(180, lambda: (
                log_broccoli_claude('pyautogui command+enter fallback fired'),
                pyautogui.hotkey('command', 'enter')
            ))
            QTimer.singleShot(360, lambda: (
                log_broccoli_claude('pyautogui ctrl+enter fallback fired'),
                pyautogui.hotkey('ctrl', 'enter')
            ))
            QTimer.singleShot(540, lambda: (
                log_broccoli_claude('pyautogui command+return fallback fired'),
                pyautogui.hotkey('command', 'return')
            ))
        except Exception as exc:
            log_broccoli_claude(f'shortcut send failed: {exc}')
            try:
                pyautogui.hotkey('command', 'enter')
                pyautogui.hotkey('ctrl', 'enter')
            except Exception:
                pass

    def _activate_web_composer(self, view: QWebEngineView, callback=None):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const input = Array.from(document.querySelectorAll('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0];
            if (!input) return null;
            const rect = input.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + Math.min(80, Math.max(12, rect.width * 0.18)))),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + Math.min(24, Math.max(10, rect.height * 0.5))))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))
            if callback:
                QTimer.singleShot(140, callback)

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if callback:
                QTimer.singleShot(0, callback)

    def _activate_claude_composer(self, view: QWebEngineView, callback=None):
        self._activate_web_composer(view, callback=callback)

    def _click_claude_send_button_if_present(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const btn = Array.from(document.querySelectorAll('button')).find(node => {
                return visible(node)
                    && !disabled(node)
                    && String(node.getAttribute('aria-label') || '').trim().toLowerCase() === 'send message';
            });
            if (!btn) return null;
            btn.focus && btn.focus();
            btn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, composed: true, pointerType: 'mouse' }));
            btn.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, composed: true }));
            btn.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true, composed: true, pointerType: 'mouse' }));
            btn.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, composed: true }));
            btn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, composed: true }));
            return 'clicked';
        })()
        """
        try:
            view.page().runJavaScript(js)
        except Exception:
            pass

    def _submit_claude_with_shortcut(self, view: QWebEngineView):
        log_broccoli_claude('submit via Claude send button requested')
        self._activate_claude_composer(
            view,
            callback=lambda v=view: (
                QTimer.singleShot(180, lambda: self._click_claude_send_button_if_present(v)),
            ),
        )

    @staticmethod
    def _inject_text_to_web_view(view: QWebEngineView, text: str, callback=None):
        text_json = json.dumps(str(text or ''), ensure_ascii=False)
        js = f"""
        (function() {{
            const t = {text_json};
            const visible = (node) => {{
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            }};
            const candidates = Array.from(document.querySelectorAll('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom);
            const input = candidates[0] || null;
            if (!input) return {{ ok: false, mode: 'no-input', observedLength: 0, expectedLength: t.length }};
            const observed = () => String(
                input.tagName && input.tagName.toLowerCase() === 'textarea'
                    ? (input.value || '')
                    : (input.innerText || input.textContent || '')
            );
            const fireInputEvents = (data) => {{
                try {{
                    input.dispatchEvent(new InputEvent('beforeinput', {{
                        bubbles: true,
                        cancelable: true,
                        composed: true,
                        inputType: 'insertText',
                        data
                    }}));
                }} catch (err) {{}}
                try {{
                    input.dispatchEvent(new InputEvent('input', {{
                        bubbles: true,
                        cancelable: true,
                        composed: true,
                        inputType: 'insertText',
                        data
                    }}));
                }} catch (err) {{
                    input.dispatchEvent(new Event('input', {{ bubbles: true, cancelable: true, composed: true }}));
                }}
                input.dispatchEvent(new Event('change', {{ bubbles: true, cancelable: true, composed: true }}));
                input.dispatchEvent(new KeyboardEvent('keyup', {{ key: ' ', code: 'Space', bubbles: true, composed: true }}));
            }};
            input.focus();
            input.click && input.click();
            if (input.tagName && input.tagName.toLowerCase() === 'textarea') {{
                const setter = Object.getOwnPropertyDescriptor(
                    HTMLTextAreaElement.prototype, 'value').set;
                setter.call(input, t);
                fireInputEvents(t);
                const value = observed();
                return {{ ok: value.length > 0 || t.length === 0, mode: 'textarea', observedLength: value.length, expectedLength: t.length }};
            }}
            const selection = window.getSelection && window.getSelection();
            if (selection && document.createRange) {{
                const range = document.createRange();
                range.selectNodeContents(input);
                selection.removeAllRanges();
                selection.addRange(range);
            }}
            document.execCommand('selectAll', false, null);
            document.execCommand('insertText', false, t);
            fireInputEvents(t);
            let value = observed();
            if (t.length > 0 && value.length === 0) {{
                input.textContent = '';
                input.appendChild(document.createTextNode(t));
                fireInputEvents(t);
                value = observed();
            }}
            return {{ ok: value.length > 0 || t.length === 0, mode: 'contenteditable', observedLength: value.length, expectedLength: t.length }};
        }})()
        """
        def after(result):
            if callback:
                callback(result if isinstance(result, dict) else {})
        if callback:
            view.page().runJavaScript(js, after)
        else:
            view.page().runJavaScript(js)

    def _prepare_web_upload_file_payloads(self, paths: list[str], max_bytes: int = 25 * 1024 * 1024) -> list[dict]:
        payloads = []
        for path in paths or []:
            path = str(path)
            if not path or not os.path.exists(path) or not os.path.isfile(path):
                continue
            try:
                if os.path.getsize(path) > max_bytes:
                    continue
                with open(path, 'rb') as fh:
                    encoded = base64.b64encode(fh.read()).decode('ascii')
            except Exception:
                continue
            payloads.append({
                'name': os.path.basename(path),
                'mime': mimetypes.guess_type(path)[0] or 'application/octet-stream',
                'b64': encoded,
            })
        return payloads

    def _wait_for_web_attachment_presence(self,
                                          view: QWebEngineView,
                                          expected_names: list[str] | None = None,
                                          timeout_ms: int = 6000,
                                          interval_ms: int = 350,
                                          callback=None):
        names = [
            os.path.basename(str(name)).lower()
            for name in (expected_names or [])
            if str(name).strip()
        ]
        started_at = time.monotonic()
        names_json = json.dumps(names, ensure_ascii=False)
        probe_js = """
        (function() {
            const names = __EXPECTED_NAMES__;
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const textOf = (node) => [
                node.innerText,
                node.getAttribute && node.getAttribute('aria-label'),
                node.getAttribute && node.getAttribute('title'),
                node.getAttribute && node.getAttribute('data-testid'),
                node.getAttribute && node.getAttribute('alt'),
                node.id,
                node.className
            ].filter(Boolean).join(' ').toLowerCase();
            const input = document.querySelector('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea');
            const composerCandidates = [
                input && input.closest('form'),
                input && input.closest('[data-testid*="composer"]'),
                input && input.closest('[class*="composer"]'),
                input && input.closest('[class*="prompt"]'),
                input && input.parentElement && input.parentElement.parentElement,
                input && input.parentElement
            ].filter(node => node && visible(node));
            const area = (node) => {
                const rect = node.getBoundingClientRect();
                return rect.width * rect.height;
            };
            const composer = composerCandidates
                .sort((a, b) => area(b) - area(a))
                .find(node => {
                    const rect = node.getBoundingClientRect();
                    return rect.width >= 180 && rect.height >= 36;
                }) || null;
            const composerRect = composer ? composer.getBoundingClientRect() : null;
            const inAttachmentArea = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                if (!composerRect) {
                    return rect.top > window.innerHeight * 0.32;
                }
                return rect.bottom >= composerRect.top - 120
                    && rect.top <= composerRect.bottom + 80
                    && rect.right >= composerRect.left - 40
                    && rect.left <= composerRect.right + 40;
            };
            const scopedVisible = Array.from(document.querySelectorAll('body *'))
                .filter(node => visible(node) && inAttachmentArea(node));
            if (names.length) {
                const named = scopedVisible.find(node => {
                    const text = textOf(node);
                    return names.some(name => name && text.includes(name));
                });
                if (named) return { present: true, reason: 'filename' };
            }
            const attachmentLike = scopedVisible.find(node => {
                const tag = String(node.tagName || '').toLowerCase();
                const text = textOf(node);
                const isControl = tag === 'button'
                    || tag === 'label'
                    || node.getAttribute('role') === 'button'
                    || /(remove|delete|trash|close|clear|attach|upload|削除|消去|删除|移除|上传|アップロード)/.test(text);
                if (!isControl && /(attachment|attached|thumbnail|preview|image attached|file attached|添付済|附件已添加|已添加附件)/.test(text)) return true;
                if (['img', 'canvas', 'figure', 'picture'].includes(tag) || node.getAttribute('role') === 'img') {
                    const rect = node.getBoundingClientRect();
                    return rect.width >= 24 && rect.height >= 24;
                }
                if (!isControl) {
                    const rect = node.getBoundingClientRect();
                    const style = window.getComputedStyle(node);
                    const hasBgImage = style.backgroundImage && style.backgroundImage !== 'none' && /url\\(/.test(style.backgroundImage);
                    if (hasBgImage && rect.width >= 24 && rect.height >= 24) return true;
                    if (/(attachment|attached|thumbnail|preview|image|file|upload)/.test(text)
                        && rect.width >= 36
                        && rect.height >= 24
                        && node.querySelector('img, canvas, figure, picture, [role="img"]')) {
                        return true;
                    }
                }
                return false;
            });
            if (attachmentLike) return { present: true, reason: 'attachment-node' };
            const busy = scopedVisible.find(node => {
                const text = textOf(node);
                return node.getAttribute('role') === 'progressbar'
                    || node.getAttribute('aria-busy') === 'true'
                    || /(uploading|upload in progress|attaching|processing file|processing image|正在上传|上传中|処理中|アップロード中)/.test(text);
            });
            if (busy) return { present: true, reason: 'uploading' };
            return { present: false, reason: 'not-found' };
        })()
        """.replace('__EXPECTED_NAMES__', names_json)

        def probe():
            if time.monotonic() - started_at > max(1, timeout_ms) / 1000:
                if callback:
                    callback(False)
                return
            try:
                page = view.page()
            except Exception:
                if callback:
                    callback(False)
                return

            def after(result):
                result = result if isinstance(result, dict) else {}
                if bool(result.get('present')):
                    if callback:
                        callback(True)
                    return
                QTimer.singleShot(max(100, int(interval_ms)), probe)

            try:
                page.runJavaScript(probe_js, after)
            except Exception:
                QTimer.singleShot(max(100, int(interval_ms)), probe)

        probe()

    def _inject_files_to_claude_by_drop(self, view: QWebEngineView, paths: list[str], fallback_callback=None, callback=None):
        payloads = self._prepare_web_upload_file_payloads(paths)
        if not payloads:
            if fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)
            return
        payload_json = json.dumps(payloads, ensure_ascii=False)
        js = f"""
        (async function() {{
            const payloads = {payload_json};
            const visible = (node) => {{
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
            }};
            const b64ToBytes = (b64) => {{
                const bin = atob(b64);
                const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                return bytes;
            }};
            const files = payloads.map(item => new File(
                [b64ToBytes(item.b64)],
                item.name || 'attachment',
                {{ type: item.mime || 'application/octet-stream', lastModified: Date.now() }}
            ));
            if (!files.length) return 'no-files';
            const target =
                Array.from(document.querySelectorAll('[contenteditable="true"], textarea'))
                    .filter(visible)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || Array.from(document.querySelectorAll('[data-testid*="composer"], form, main'))
                    .filter(visible)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || document.body;
            if (!target) return 'no-target';
            target.focus && target.focus();
            target.click && target.click();
            const makeDataTransfer = () => {{
                const dt = new DataTransfer();
                files.forEach(file => dt.items.add(file));
                return dt;
            }};
            const dragDt = makeDataTransfer();
            for (const type of ['dragenter', 'dragover', 'drop']) {{
                target.dispatchEvent(new DragEvent(type, {{
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    dataTransfer: dragDt
                }}));
            }}
            const pasteDt = makeDataTransfer();
            try {{
                target.dispatchEvent(new ClipboardEvent('paste', {{
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    clipboardData: pasteDt
                }}));
            }} catch (err) {{
                const ev = new Event('paste', {{ bubbles: true, cancelable: true, composed: true }});
                Object.defineProperty(ev, 'clipboardData', {{ value: pasteDt }});
                target.dispatchEvent(ev);
            }}
            return 'dropped';
        }})()
        """

        def after(result):
            if str(result or '') == 'dropped':
                if callback:
                    QTimer.singleShot(0, callback)
            elif fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)

    def _inject_files_to_web_by_drop(self, view: QWebEngineView, paths: list[str], fallback_callback=None, callback=None):
        self._inject_files_to_claude_by_drop(
            view,
            paths,
            fallback_callback=fallback_callback,
            callback=callback,
        )

    def _upload_external_web_target_attachments(self, view: QWebEngineView, paths: list[str], callback=None):
        upload_paths = []
        seen = set()
        for path in paths or []:
            value = str(path or '').strip()
            if not value or not os.path.exists(value) or not os.path.isfile(value):
                continue
            value = os.path.abspath(value)
            if value in seen:
                continue
            seen.add(value)
            upload_paths.append(value)
        if not upload_paths:
            if callback:
                QTimer.singleShot(0, lambda: callback(True, 'no-files'))
            return
        names = [os.path.basename(path) for path in upload_paths]
        finished = {'done': False}

        def finish(ok: bool, reason: str):
            if finished.get('done'):
                return
            finished['done'] = True
            if callback:
                callback(bool(ok), str(reason or ''))

        def wait_for_presence():
            QTimer.singleShot(
                1400,
                lambda: self._wait_for_web_attachment_presence(
                    view,
                    names,
                    timeout_ms=45000,
                    interval_ms=350,
                    callback=lambda ok: finish(bool(ok), 'presence-confirmed' if ok else 'presence-timeout'),
                ),
            )

        def start_drop():
            self._inject_files_to_web_by_drop(
                view,
                upload_paths,
                fallback_callback=wait_for_presence,
                callback=wait_for_presence,
            )

        self._activate_web_composer(view, callback=start_drop)

    def _submit_grok_with_button(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const buttons = Array.from(document.querySelectorAll('button'));
            const btn = buttons.find(node => {
                if (!visible(node) || disabled(node)) return false;
                const label = String(node.getAttribute('aria-label') || '').trim().toLowerCase();
                const testid = String(node.getAttribute('data-testid') || '').trim().toLowerCase();
                const type = String(node.getAttribute('type') || '').trim().toLowerCase();
                return label === 'submit' && (testid === 'chat-submit' || type === 'submit');
            });
            if (!btn) return null;
            const rect = btn.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + rect.width / 2)),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + rect.height / 2))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            pass

    def _submit_perplexity_with_button(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const btn = Array.from(document.querySelectorAll('button')).find(node => {
                if (!visible(node) || disabled(node)) return false;
                const label = String(node.getAttribute('aria-label') || '').trim().toLowerCase();
                const type = String(node.getAttribute('type') || '').trim().toLowerCase();
                return label === 'submit' && type === 'button';
            });
            if (!btn) return null;
            const rect = btn.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + rect.width / 2)),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + rect.height / 2))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            pass

    def _click_web_view_send_button(self, view: QWebEngineView):
        claude = self._is_claude_web_view(view)
        if claude:
            self._submit_claude_with_shortcut(view)
            return
        if self._is_grok_web_view(view):
            self._submit_grok_with_button(view)
            return
        if self._is_perplexity_web_view(view):
            self._submit_perplexity_with_button(view)
            return
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const clickButton = (btn) => {
                btn.focus && btn.focus();
                btn.dispatchEvent(new PointerEvent('pointerdown', {bubbles: true, cancelable: true, composed: true, pointerType: 'mouse'}));
                btn.dispatchEvent(new MouseEvent('mousedown', {bubbles: true, cancelable: true, composed: true}));
                btn.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, cancelable: true, composed: true, pointerType: 'mouse'}));
                btn.dispatchEvent(new MouseEvent('mouseup', {bubbles: true, cancelable: true, composed: true}));
                btn.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, composed: true}));
            };
            const buttons = Array.from(document.querySelectorAll('button, [role="button"]'));
            const candidates = buttons.filter(btn => {
                if (!visible(btn) || disabled(btn)) return false;
                const text = [
                    btn.innerText,
                    btn.getAttribute('aria-label'),
                    btn.getAttribute('title'),
                    btn.getAttribute('data-testid')
                ].filter(Boolean).join(' ').toLowerCase();
                if (/(stop|cancel|停止|中止|キャンセル|voice|mic|microphone|audio|dictate)/.test(text)) return false;
                return /(send|submit|发送|送信|送出|送信する|送出する)/.test(text);
            });
            if (candidates.length) {
                clickButton(candidates[candidates.length - 1]);
                return 'button';
            }
            const input = document.querySelector('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea');
            if (input) {
                input.focus();
                const opts = {
                    key: 'Enter',
                    code: 'Enter',
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    metaKey: false,
                    ctrlKey: false,
                    shiftKey: false,
                    altKey: false
                };
                input.dispatchEvent(new KeyboardEvent('keydown', opts));
                input.dispatchEvent(new KeyboardEvent('keypress', opts));
                input.dispatchEvent(new KeyboardEvent('keyup', opts));
                return 'enter';
            }
            return 'not-found';
        })()
        """
        try:
            view.page().runJavaScript(js)
        except Exception:
            pass

    def _wait_then_click_web_send_button(self,
                                         view: QWebEngineView,
                                         timeout_ms: int = 15000,
                                         interval_ms: int = 450,
                                         stable_hits: int = 2,
                                         callback=None,
                                         show_error: bool = True,
                                         caller: str = '',
                                         result_callback=None):
        claude = self._is_claude_web_view(view)
        caller = str(caller or '').strip()

        def skipped_message() -> tuple[str, str]:
            title = 'Auto send skipped'
            if caller:
                title = f'Auto send skipped ({caller})'
            if caller == 'online_memory':
                return (
                    title,
                    'The web page did not finish enabling Send for the online memory prompt. The prompt was left in the page.',
                )
            if caller in {'web_forward', 'web_cross_forward'}:
                return (
                    title,
                    'The target web page did not finish enabling Send after forwarded text was inserted. The prompt was left in the page.',
                )
            if caller.startswith('claude_dock') or caller.startswith('web_dock'):
                return (
                    title,
                    'The web page did not finish enabling Send after the prompt or attachment was added. The prompt and attachment were left in the page.',
                )
            return (
                title,
                'The web page did not finish enabling Send after the attachment was added. The prompt and attachment were left in the page.',
            )

        def after_ready(result):
            result = result if isinstance(result, dict) else {}
            if bool(result.get('ready')):
                if claude:
                    log_broccoli_claude(f'send readiness ready; caller={caller or "unknown"}; reason={result.get("reason", "")}')
                self._click_web_view_send_button(view)
                if result_callback:
                    payload = dict(result)
                    payload['clicked'] = True
                    payload['caller'] = caller
                    result_callback(payload)
                if callback:
                    callback(True)
                return
            if claude:
                log_broccoli_claude(f'auto send skipped after timeout; caller={caller or "unknown"}; last_reason={result.get("reason", "")}')
            if show_error:
                title, message = skipped_message()
                show_broccoli_message(
                    self,
                    title,
                    message,
                )
            if result_callback:
                payload = dict(result)
                payload['clicked'] = False
                payload['caller'] = caller
                result_callback(payload)
            if callback:
                callback(False)

        wait_for_web_chat_ready(
            view,
            after_ready,
            timeout_ms=timeout_ms,
            interval_ms=interval_ms,
            stable_hits=stable_hits,
            mode='send',
            allow_text_stability_fallback=False,
        )

    def _inject_images_to_web_view(self, view: QWebEngineView, image_items: list[dict], callback=None):
        items = [item for item in image_items if isinstance(item, dict) and item.get('b64')]
        if not items:
            if callback:
                QTimer.singleShot(0, callback)
            return
        focus_js = """
        (function() {
            const el = document.querySelector('div[contenteditable="true"]')
                    || document.querySelector('textarea');
            if (el) { el.focus(); return true; }
            return false;
        })()
        """

        def paste_next(idx: int):
            if idx >= len(items):
                if callback:
                    QTimer.singleShot(650, callback)
                return
            item = items[idx]
            try:
                raw = base64.b64decode(item.get('b64', ''))
                qimg = QImage.fromData(raw)
            except Exception:
                QTimer.singleShot(50, lambda: paste_next(idx + 1))
                return
            if qimg.isNull():
                QTimer.singleShot(50, lambda: paste_next(idx + 1))
                return
            QGuiApplication.clipboard().setImage(qimg)

            def do_paste(focused):
                if focused:
                    view.page().triggerAction(QWebEnginePage.WebAction.Paste)
                QTimer.singleShot(350, lambda: paste_next(idx + 1))

            view.page().runJavaScript(focus_js, do_paste)

        paste_next(0)

    def _refresh_web_lifecycle_visibility(self, current_index: int | None = None):
        if current_index is None:
            try:
                current_index = self.stacked_widget.currentIndex()
            except Exception:
                current_index = -1
        for tab_index, attr in ((TAB_WEB, 'ai_web_panel'), (TAB_LOCALHOST, 'localhost_panel')):
            panel = getattr(self, attr, None)
            if panel is not None and hasattr(panel, 'set_panel_visible'):
                panel.set_panel_visible(int(current_index) == tab_index)

    def apply_web_lifecycle_settings(self, mode: str | None = None):
        if mode is None:
            mode = load_settings_store().get('globals', {}).get('web_lifecycle_mode', DEFAULT_WEB_LIFECYCLE_MODE)
        mode = normalize_web_lifecycle_mode(mode)
        for attr in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, attr, None)
            if panel is not None and hasattr(panel, 'set_lifecycle_mode'):
                panel.set_lifecycle_mode(mode)
        self._refresh_web_lifecycle_visibility()

    def _on_tab_changed(self, index):
        """Tab 切换时更新 DrawingLayer 可见性和 qw3 背景色。"""
        self._install_selection_context_menus()
        self._update_send_shortcut_enabled()
        is_assistant = (index == TAB_API)
        is_terminal = (index == TAB_TERMINAL)
        is_external_prompt_tab = index in EXTERNAL_PROMPT_TAB_INDICES
        self._refresh_web_lifecycle_visibility(index)
        self.pill_nav.set_theme('dark' if (index == TAB_TERMINAL or is_dark_theme(app)) else 'light')
        self._set_top_chrome_button_theme(index == TAB_TERMINAL or is_dark_theme(app))
        self.settings_panel.set_force_dark(index == TAB_TERMINAL)
        self.outputs_panel.set_force_dark(index == TAB_TERMINAL)
        if not is_assistant:
            self._history_trigger_btn.hide()
            self._links_trigger_btn.hide()
            self._branch_trigger_btn.hide()
            if hasattr(self, 'webfetch_panel') and not is_external_prompt_tab:
                self.webfetch_panel.hide()
            if self._history_panel_visible:
                self.hide_history_panel()
            if self._links_panel_visible:
                self.hide_links_panel()
            if self._branch_panel_visible:
                self.hide_branch_panel()
            if self._share_panel_visible:
                self.hide_share_panel()
            self._text1_popup.hide()
        else:
            self._branch_trigger_btn.show()
            self._branch_trigger_btn.raise_()
            self._raise_webfetch_panel_if_visible()
            self._history_trigger_btn.show()
            self._history_trigger_btn.raise_()
            self._links_trigger_btn.show()
            self._links_trigger_btn.raise_()
            if getattr(self, '_webfetch_records', None) and not getattr(self, '_webfetch_panel_dismissed', False):
                self._show_webfetch_panel()
            self._refresh_text1_popup_visibility()
            self._refresh_branch_state_from_current_conversation()
            self._refresh_agent_send_button_state()
        self._refresh_agent_conversation_shelf()
        if not is_terminal:
            self._hide_terminal_side_triggers()
            if self._terminal_history_panel_visible:
                self.hide_terminal_history_panel()
            if self._terminal_favorites_panel_visible:
                self.hide_terminal_favorites_panel()
        else:
            self._refresh_terminal_history_panel()
            self._refresh_terminal_favorites_panel()
            self._show_terminal_side_triggers()
        self._outputs_trigger_btn.show()
        self._outputs_trigger_btn.raise_()
        self._refresh_outputs_panel()
        if is_external_prompt_tab:
            self._update_external_prompt_trigger_geometry()
            self._update_web_conversation_sync_button_geometry()
            panel, _dock = self._external_prompt_panel_for_index(index)
            try:
                active_idx = panel.active_index() if panel is not None and hasattr(panel, 'active_index') else 0
                self._schedule_web_conversation_capture(index, active_idx, reason='tab-switch', delay_ms=1800)
            except Exception:
                pass
            if panel is not None and panel.is_prompt_dock_visible() and getattr(self, '_webfetch_records', None) and not getattr(self, '_webfetch_panel_dismissed', False):
                self._show_webfetch_panel()
            elif hasattr(self, 'webfetch_panel'):
                self.webfetch_panel.hide()
        elif hasattr(self, '_external_prompt_trigger_btn'):
            self._external_prompt_trigger_btn.hide()
            if hasattr(self, 'web_conversation_sync_button'):
                self.web_conversation_sync_button.hide()
        if not self._settings_panel_visible:
            self._settings_trigger_btn.show()
            self._settings_trigger_btn.raise_()
        # self.btn0_2.setVisible(is_assistant)

        if not is_assistant:
            self.drawing_layer.setVisible(False)
        else:
            is_expanded = (self.i % 2 == 1)
            trans = getattr(self, 'trans', 0)
            is_html_view = (trans % 2 == 0)
            self.drawing_layer.setVisible(is_expanded and is_html_view)

        if index == TAB_API:  # Assistant
            self._set_qw3_bg('#2D2D2D' if is_dark_theme(app) else '#FFFFFF')
        elif index == TAB_WEB:   # AI Web
            self._prime_external_tab_background(TAB_WEB)
            self.ai_web_panel.active_view().page().runJavaScript(
                self._BG_JS,
                lambda color, tab_index=TAB_WEB: self._apply_web_bg(color, tab_index),
            )
        elif index == TAB_LOCALHOST:  # Localhost
            self._prime_external_tab_background(TAB_LOCALHOST)
            self.localhost_panel.active_view().page().runJavaScript(
                self._BG_JS,
                lambda color, tab_index=TAB_LOCALHOST: self._apply_web_bg(color, tab_index),
            )
        elif index == TAB_TERMINAL:  # Terminal
            self._set_qw3_bg('#2D2D2D', border='#2D2D2D')

    # JS 取背景色：采样 viewport 内可见点，向上寻找最近的不透明背景色。
    _BG_JS = (
        "(function(){"
        "  function opaque(c){"
        "    if(!c||c==='transparent'||c==='rgba(0, 0, 0, 0)') return false;"
        "    var m=c.match(/^rgba\\(([^,]+),([^,]+),([^,]+),([^\\)]+)\\)$/);"
        "    if(m) return parseFloat(m[4])>0.12;"
        "    return true;"
        "  }"
        "  function normalize(c){"
        "    if(!c) return '';"
        "    var m=c.match(/^rgb\\((\\d+),\\s*(\\d+),\\s*(\\d+)\\)$/);"
        "    if(m){"
        "      function hx(n){return Math.max(0,Math.min(255,parseInt(n,10))).toString(16).padStart(2,'0');}"
        "      return '#'+hx(m[1])+hx(m[2])+hx(m[3]);"
        "    }"
        "    return c;"
        "  }"
        "  function bgAt(x,y){"
        "    var el=document.elementFromPoint(x,y);"
        "    while(el){"
        "      var c=getComputedStyle(el).backgroundColor;"
        "      if(opaque(c)) return normalize(c);"
        "      el=el.parentElement;"
        "    }"
        "    return '';"
        "  }"
        "  var w=Math.max(1,window.innerWidth||document.documentElement.clientWidth||1);"
        "  var h=Math.max(1,window.innerHeight||document.documentElement.clientHeight||1);"
        "  var points=["
        "    [0.04,0.04],[0.5,0.04],[0.96,0.04],"
        "    [0.04,0.18],[0.5,0.18],[0.96,0.18],"
        "    [0.04,0.5],[0.5,0.5],[0.96,0.5],"
        "    [0.04,0.82],[0.5,0.82],[0.96,0.82],"
        "    [0.04,0.96],[0.5,0.96],[0.96,0.96]"
        "  ];"
        "  var counts={};"
        "  for(var i=0;i<points.length;i++){"
        "    var c=bgAt(Math.round((w-1)*points[i][0]),Math.round((h-1)*points[i][1]));"
        "    if(c) counts[c]=(counts[c]||0)+1;"
        "  }"
        "  var best='',bestCount=0;"
        "  Object.keys(counts).forEach(function(c){if(counts[c]>bestCount){best=c;bestCount=counts[c];}});"
        "  if(best) return best;"
        "  var body=getComputedStyle(document.body||document.documentElement).backgroundColor;"
        "  if(opaque(body)) return normalize(body);"
        "  var root=getComputedStyle(document.documentElement).backgroundColor;"
        "  if(opaque(root)) return normalize(root);"
        "  return '#FFFFFF';"
        "})()"
    )

    def _on_web_loaded(self, ok, panel, tab_index):
        """活跃 view 加载完成后，若该 tab 正在显示则更新背景色。"""
        if ok and self.stacked_widget.currentIndex() == tab_index:
            panel.active_view().page().runJavaScript(
                self._BG_JS,
                lambda color, tab_index=tab_index: self._apply_web_bg(color, tab_index),
            )

    def _apply_web_bg(self, color_str, tab_index=None):
        """将 JS 返回的颜色应用到 qw3；透明/空时回退白色。"""
        if tab_index is not None:
            try:
                if self.stacked_widget.currentIndex() != int(tab_index):
                    return
            except Exception:
                return
        if not color_str or color_str.strip() in ('rgba(0, 0, 0, 0)', 'transparent', ''):
            color_str = '#FFFFFF'
        if tab_index in EXTERNAL_PROMPT_TAB_INDICES:
            try:
                self._external_tab_backgrounds[int(tab_index)] = color_str
            except Exception:
                pass
        self._set_external_tab_background(tab_index, color_str)

    def _set_external_tab_background(self, tab_index, color_str: str):
        color_str = str(color_str or '').strip() or '#FFFFFF'
        if tab_index == TAB_WEB:
            panel = getattr(self, 'ai_web_panel', None)
        elif tab_index == TAB_LOCALHOST:
            panel = getattr(self, 'localhost_panel', None)
        else:
            panel = None
        if panel is not None and hasattr(panel, 'set_panel_background'):
            panel.set_panel_background(color_str)
        self._set_qw3_bg(color_str)

    def _prime_external_tab_background(self, tab_index: int):
        try:
            tab_index = int(tab_index)
        except Exception:
            return
        cached = getattr(self, '_external_tab_backgrounds', {}).get(tab_index, '#FFFFFF')
        self._set_external_tab_background(tab_index, cached or '#FFFFFF')

    def _set_qw3_bg(self, bg_css, border='#ECECEC'):
        """动态覆盖 qw3 的背景色（保留其他样式属性）。"""
        if border == '#ECECEC' and is_dark_theme(app):
            border = '#2D2D2D'
        if hasattr(self.qw3, 'set_smooth_panel_background'):
            self.qw3.set_smooth_panel_background(bg_css, border, 59)
        self.qw3.setStyleSheet("QWidget#Main-1 { border: none; background: transparent; }")

