    def _refresh_skill_item(self, row: int):
        if not (0 <= row < len(self._skill_records)):
            return
        item = self.skill_list_widget.item(row)
        if item is None:
            return
        record = self._skill_records[row]
        previous = self._skill_updating
        self._skill_updating = True
        item.setText(self._skill_item_text(record))
        item.setCheckState(Qt.CheckState.Checked if record.get('enabled', True) else Qt.CheckState.Unchecked)
        self._skill_updating = previous

